window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0096", [{"word":"temperature regulation","ipa_uk":"/ˈtemprətʃə ˌreɡjuˈleɪʃn/","ipa_us":"/ˈtemprətʃər ˌreɡjuˈleɪʃən/","definition_zh":"体温调节；温度调控（把温度维持在所需范围内的过程）","definition_en":"the control of temperature within a required range, especially the keeping of body temperature near a set point","core_image":"一只恒温箱与一具身体并排：箱内温度计的指针被按在一格不动，箱外昼夜与四季不断变化","scene":"沙漠里，正午最热时蜥蜴从晒热的石块挪到岩缝的阴影里，把身体贴在凉的一方。Desert lizards rely on behaviour for temperature regulation when the midday heat peaks.","sceneCN":"这里 temperature regulation 指「靠行为把体温维持在可承受范围」（第 2 个义项：行为性体温调节）；句意为正午最热时，沙漠蜥蜴靠行为进行体温调节。图中可辨识物件：岩缝阴影、抬起的头、晒热的石块、远处沙丘。","pos":[{"tag":"n.","zh":"体温调节；温度调控（不可数；指具体机制时可数，复数 temperature regulations）"}],"collocations":[{"phrase":"body temperature regulation","zh":"体温调节"},{"phrase":"behavioural temperature regulation","zh":"行为性体温调节"},{"phrase":"temperature regulation mechanism","zh":"温度调节机制"},{"phrase":"precise temperature regulation","zh":"精确控温"},{"phrase":"temperature regulation system","zh":"温度调节系统"},{"phrase":"failure of temperature regulation","zh":"体温调节失灵"}],"forms":[{"label":"复数（指多种调节机制）","form":"temperature regulations"},{"label":"同义术语（体温调节）","form":"thermoregulation"},{"label":"形容词（体温调节的）","form":"thermoregulatory"},{"label":"相关动词","form":"regulate"},{"label":"相关名词（调节器）","form":"regulator"},{"label":"相关名词（调节；规章）","form":"regulation"}],"derivatives":[{"word":"thermoregulation","pos":"n.","zh":"thermo-（希腊 thermē「热」）+ regulation → 以生理手段维持体温的过程"},{"word":"thermoregulatory","pos":"adj.","zh":"thermoregulation + -ory（形容词后缀）→ 与体温调节有关的"},{"word":"regulator","pos":"n.","zh":"regulate + -or（施动者后缀）→ 执行调节的器件或主体"},{"word":"regulatory","pos":"adj.","zh":"regulator + -y（形容词后缀）→ 具有调节或监管性质的"},{"word":"regulate","pos":"v.","zh":"regula（拉丁「直尺、规则」）+ -ate → 按规则把某量校准到范围内"}],"senses":[{"no":"01","title":"Physiological control of core temperature","titleCN":"维持核心体温的生理调节","definition":"the internal process that keeps an animal's core temperature near a set point whatever the weather does","definitionCN":"无论外界天气如何，把动物核心体温维持在接近设定值的内部过程","example":"Sweating and shivering are the two ends of human temperature regulation.","exampleCN":"出汗与发抖是人类体温调节的两个端点。","why":"Temperature names a measured degree of heat and regulation names rule-bound correction, so the phrase means holding a degree of heat inside a rule.","whyCN":"temperature 指测得的冷热程度，regulation 指按规则校正，因此这个短语就是「把冷热程度守在规则之内」。"},{"no":"02","title":"Behavioural control by moving or posturing","titleCN":"靠移动位置与姿态的行为性调节","definition":"the use of shade, sun, posture or grouping rather than internal chemistry to adjust body heat","definitionCN":"不靠体内化学变化，而靠阴影、日照、姿态或结群来调整体温","example":"Desert lizards rely on behaviour for temperature regulation when the midday heat peaks.","exampleCN":"正午最热时，沙漠蜥蜴靠行为进行体温调节。","why":"Behaviour is the cheapest thermostat: an animal changes where it stands instead of changing how its body burns fuel.","whyCN":"行为是最省力的恒温器：动物改变站位，而不必改变身体燃烧燃料的方式。"},{"no":"03","title":"Control of temperature inside a building or machine","titleCN":"建筑或设备内部的温度控制","definition":"the engineering maintenance of a chosen temperature in a room, vehicle or instrument","definitionCN":"在房间、载具或仪器中把温度维持在选定值的技术性工作","example":"The server room needs precise temperature regulation to keep the drives from overheating.","exampleCN":"这间服务器机房需要精确控温，以免硬盘过热。","why":"The same word moves from bodies to rooms because both are systems that must hold a set value against a changing surroundings.","whyCN":"这个词从身体转到房间，因为两者都是要在变化的环境中守住设定值的系统。"},{"no":"04","title":"Thermal buffering by water, forest or soil","titleCN":"水体、森林或土壤对周边温度的缓冲","definition":"the moderating effect a large body of water, woodland or moist soil has on the air around it","definitionCN":"大片水体、林地或湿土对周围空气温度的缓和作用","example":"The lake provides temperature regulation for the valley, softening summer heat and winter frost.","exampleCN":"这片湖为山谷起到温度调节作用，缓和了夏热与冬霜。","why":"A lake holds heat longer than air does, so it acts like a regulator fitted to the whole valley.","whyCN":"湖水比空气更能存住热量，因此它像装在整个山谷上的一只调节器。"},{"no":"05","title":"A particular mechanism or set of structures","titleCN":"一套具体的调节机制或结构（可数用法）","definition":"one identifiable mechanism, organ or reflex that contributes to keeping the body at its set point","definitionCN":"参与把身体维持在设定值的某一可辨识机制、器官或反射","example":"Each species has evolved its own temperature regulation, from panting to blubber.","exampleCN":"每个物种都演化出自己的温度调节方式，从喘气散热到皮下脂肪保温。","why":"Once the process is treated as a countable thing, the phrase can name one device in the body's control kit.","whyCN":"一旦把这一过程当作可数的物件，这个短语就能指身体调控装备中的某一件。"},{"no":"06","title":"Collective control in a social insect colony","titleCN":"社会性昆虫群体的集体调温","definition":"the coordinated fanning, clustering or evaporating by which a colony holds its nest at a steady temperature","definitionCN":"蜂群或蚁群通过扇风、结团或蒸发协调把巢温维持在稳定值","example":"Honeybees achieve temperature regulation by fanning the hive in waves.","exampleCN":"蜜蜂靠一波接一波地扇风来实现蜂巢的温度调节。","why":"The regulators here are not organs but workers acting together, so the phrase shifts from physiology to collective behaviour.","whyCN":"这里的调节者不是器官，而是共同行动的工蜂，因此这个短语从生理学转到集体行为。"},{"no":"07","title":"Clinical management of a patient's body heat","titleCN":"临床对病人体温的管理","definition":"the warming or cooling of a patient by medical staff to keep the body within safe limits","definitionCN":"医护人员对病人加温或降温，使体温保持在安全范围","example":"Nurses watched the patient's temperature regulation closely after the operation.","exampleCN":"手术后护士密切观察病人的体温调节情况。","why":"Medicine borrows the phrase when the body's own regulation fails and must be managed from outside.","whyCN":"当身体自身的调节失效、必须由外部接管时，医学就借用了这个短语。"},{"no":"08","title":"Holding a fixed temperature in an experiment or facility","titleCN":"实验或养殖场所的恒温控制","definition":"the maintenance of a constant temperature in a laboratory, hatchery or greenhouse for the sake of a procedure","definitionCN":"为了某项实验或生产流程，在实验室、孵化场或温室中维持恒定温度","example":"The hatchery maintains temperature regulation at a constant level for the eggs.","exampleCN":"孵化场为种蛋把温度调节维持在恒定水平。","why":"Here regulation means engineering control only: no organism is adjusting itself, the room is.","whyCN":"这里的 regulation 只指工程控制：调节自身的不是生物，而是房间。"}],"etymology":{"intro":{"en":"Temperature reaches English through French from Latin temperatura 'a tempering, moderation', built on temperare 'to mix in due proportion, regulate'. Regulation comes from Latin regula 'straight stick, rule', a diminutive of regere 'to lead straight'. The two words were joined into an English phrase only in modern technical writing, so the exact first date is uncertain.","cn":"temperature 经法语来自拉丁 temperatura「调和、适度」，由 temperare「按比例掺和、调节」构成；regulation 来自拉丁 regula「直尺、规则」，是 regere「引直、统治」的指小形式。两词组合成英语短语只是近代技术文献中的事，确切首见年代不确定。"},"items":[{"era":"LATIN TEMPERARE","en":"Temperare meant 'to mix in due proportion, to regulate'. It is generally connected with tempus 'time, season', on the idea of the right season or the right blend, but the deeper link is debated.","cn":"temperare 意为「按适当比例掺和、调节」。一般认为它与 tempus「时间、时节」有关，取「合宜的时节、合宜的配比」之意，但更深层的联系仍有争议。"},{"era":"LATIN TEMPERATURA","en":"The noun temperatura named a tempering or moderation. Its use for a measured degree of heat belongs to later scientific English, not to classical Latin.","cn":"名词 temperatura 指「调和、适度」。用它表示测得的冷热程度，是后来科学英语的发展，并非古典拉丁的用法。"},{"era":"LATIN REGULA / REGERE","en":"Regula was a straight piece of wood used as a rule; regere meant 'to lead straight, direct, rule'. Both descend from a root meaning 'to move in a straight line'.","cn":"regula 是取直用的木条，即「尺、规则」；regere 意为「引直、指导、统治」。两者都出自表示「沿直线移动」的词根。"},{"era":"FRENCH AND EARLY ENGLISH","en":"Temperature and regulation entered English by way of French and Latin in the sixteenth century, regulation first naming the act of making something regular.","cn":"temperature 与 regulation 在十六世纪经法语和拉丁进入英语，regulation 最初指「使某物变得有规则」这一动作。"},{"era":"MODERN PHRASE","en":"The pairing of a measured quantity with a control term is a modern habit; it settled in physiology and engineering writing in the nineteenth and twentieth centuries, though the exact first use is uncertain.","cn":"把测得的量与一个控制词并置，是近代的构词习惯；它在十九至二十世纪的生理学与工程文献中固定下来，确切首见年代不确定。"},{"era":"MODERN SYNONYM","en":"Thermoregulation, built from Greek thermē 'heat', is the learned synonym coined in the twentieth century; the plainer phrase remains common in textbooks.","cn":"由希腊 thermē「热」构成的 thermoregulation，是二十世纪新造的书面对应术语；较朴素的短语仍常见于教科书。"}]},"similar":{"note":{"en":"Group one holds forms built on the same Latin stock that are easily confused; group two holds expressions for controlling heat with a different scope.","cn":"第一组是同出拉丁词干、容易混淆的形式；第二组是控制热量但适用范围不同的说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"thermoregulation","ipa":"/ˌθɜːməʊˌreɡjuˈleɪʃn/","tag":"same meaning, Greek prefix","definition":"The technical synonym: thermo- 'heat' replaces the English noun temperature, but the process named is identical.","definitionCN":"技术性同义词：用 thermo-「热」替换英语名词 temperature，所指过程完全相同。"},{"word":"temperate","ipa":"/ˈtempərət/","tag":"same root, different suffix","definition":"From temperare plus -atus: 'kept within bounds', hence a mild climate or a restrained person, not a control process.","definitionCN":"由 temperare 加 -atus 构成，意为「被守在限度内」，因此指温和的气候或克制的人，而非调控过程。"},{"word":"temperament","ipa":"/ˈtemprəmənt/","tag":"same root, inner mixture","definition":"From Latin temperamentum 'due mixture': the old idea that a person's character is a blend of humours, not a thermal mechanism.","definitionCN":"来自拉丁 temperamentum「合宜的混合」：旧说认为人的性情是体液的配比，与热调控机制无关。"},{"word":"regulation","ipa":"/ˌreɡjuˈleɪʃn/","tag":"control or a rule","definition":"The noun alone can name an official rule or the act of controlling; only with temperature does it become a thermal process.","definitionCN":"这个名词单独用时可指正式规章或控制动作；只有与 temperature 连用才成为热学过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"temperature control","ipa":"/ˈtemprətʃə kənˈtrəʊl/","tag":"engineering focus","definition":"The everyday engineering phrase for holding a room or device at a chosen temperature; it rarely refers to a living body.","definitionCN":"工程上的日常说法，指把房间或设备维持在选定温度；很少指活体。"},{"word":"climate control","ipa":"/ˈklaɪmət kənˈtrəʊl/","tag":"air plus moisture","definition":"Control of temperature together with humidity and air movement, a wider job than temperature alone.","definitionCN":"连同湿度与气流一起控制，范围比单控温度更宽。"},{"word":"thermal management","ipa":"/ˈθɜːml ˈmænɪdʒmənt/","tag":"electronics and design","definition":"The engineering discipline of removing heat from components; it is about carrying heat away, not holding a set point.","definitionCN":"把热量从元件排走的工程领域；重点在于导热出去，而非守住设定值。"},{"word":"thermoregulatory","ipa":"/ˌθɜːməʊˈreɡjulətəri/","tag":"adjective form","definition":"The adjective describing structures or behaviours that serve thermoregulation, as in thermoregulatory sweating.","definitionCN":"形容词，描述服务于体温调节的结构或行为，如调节性出汗。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Temperature is a measured degree; regulation is rule-bound correction: a rule for the thermometer.","cn":"temperature 是测得的度数，regulation 是按规则校正：给温度计定一条规则。"},{"en":"The family runs regulate, regulation, regulator, regulatory, thermoregulation, thermoregulatory.","cn":"同族词包括 regulate、regulation、regulator、regulatory、thermoregulation、thermoregulatory。"},{"en":"Fixed phrases mark the field: body temperature regulation, behavioural temperature regulation, precise temperature regulation.","cn":"固定搭配标出领域：体温调节、行为性体温调节、精确控温。"},{"en":"Thermo- comes from Greek thermē 'heat', the same element seen in thermometer and thermostat.","cn":"thermo- 来自希腊 thermē「热」，同样出现在 thermometer 与 thermostat 中。"},{"en":"The phrase splits naturally into a quantity and a control, which is exactly how a thermostat works.","cn":"这个短语天然分成「量」与「控制」两半，恒温器正是这样工作的。"}],"abstract":[{"en":"Picture a ruler laid against a thermometer and a hand pushing the mercury back whenever it climbs.","cn":"想象一把尺子贴在温度计上，水银一爬高就有一只手把它按回去。"},{"en":"Picture a lake breathing out cool air over a hot valley every afternoon.","cn":"想象一片湖每天午后向炎热的山谷呼出凉气。"},{"en":"Picture a crowd of bees acting as one slow fan.","cn":"想象一大群蜜蜂合成一台缓慢转动的风扇。"}]},"examples":[{"en":"Sweating and shivering are the two ends of human temperature regulation.","cn":"出汗与发抖是人类体温调节的两个端点。"},{"en":"The lake provides temperature regulation for the valley, softening summer heat and winter frost.","cn":"这片湖为山谷起到温度调节作用，缓和了夏热与冬霜。"},{"en":"The server room needs precise temperature regulation to keep the drives from overheating.","cn":"这间服务器机房需要精确控温，以免硬盘过热。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「温度 + 规章」——给温度定一条规章，不许它跑出范围 → 体温调节、温度调控","word":"temperature regulation"},"root":"temperature 经法语来自拉丁 temperatura「调和、适度」，由 temperare「掺和、调节」构成（一般认为与 tempus「时间、时节」有关，更深来源不确定）；regulation 来自拉丁 regula「直尺、规则」，由 regere「引直、统治」加指小后缀构成。英语 temperature regulation。","sensesIntro":{"en":"Eight senses follow one gesture: a set point is held against a changing world. The gesture is first internal and chemical, then behavioural, then collective, then moved outward onto rooms, lakes, patients and hatcheries.","cn":"八个义项沿同一个动作展开：在变化的世界里守住一个设定值。这个动作先发生在体内与化学层面，再转为行为、集体行为，最后外移到房间、湖泊、病人与孵化场。"},"semanticMap":{"core":{"en":"CORE IMAGE: a pointer held at one mark on a dial while the weather outside the box keeps moving.","cn":"核心意象：表盘上的指针被按在一格不动，箱外的天气却不断变化。"},"chain":["DEGREE OF HEAT","SET POINT","SENSING","CORRECTION","STABLE RANGE","OUTWARD CONTROL"],"branches":[{"senses":"S1 · S5","en":"INNER THERMOSTAT: the body senses, corrects and holds its own core value, whether as a process or as one named mechanism.","cn":"体内恒温器：身体自行感知、校正并守住核心值，既可指过程，也可指某一具体机制。"},{"senses":"S2 · S6","en":"MOVING THE BODY: shade, posture and the fanning of a colony do the correcting without inner chemistry.","cn":"挪动身体：阴影、姿态与蜂群扇风，不用体内化学也能完成校正。"},{"senses":"S3 · S8","en":"OUTWARD CONTROL: a room or hatchery is held at a chosen value by equipment, not by a living regulator.","cn":"向外控制：房间或孵化场由设备守住选定值，调节者不是活物。"},{"senses":"S4","en":"BUFFERING LANDSCAPE: a lake stores heat and slows the swing of the air above it.","cn":"缓冲的景观：湖泊存住热量，使上方气温的摆动变慢。"},{"senses":"S7","en":"BORROWED CONTROL: when the inner thermostat fails, staff take over the set point.","cn":"借来的控制：体内恒温器失灵时，由医护人员接管设定值。"}]},"affixes":{"intro":{"en":"The phrase is made of two Latin-derived nouns, each analysable into a root and a suffix, and each root also builds a family of English words.","cn":"这个短语由两个拉丁来源的名词构成，每个都可拆成词根与后缀，每个词根又各自衍生出一族英语词。"},"latinIntro":{"en":"Latin temperare and its noun temperatura stand behind temperature; Latin regula and regere stand behind regulate and regulation. The Greek element thermo- supplies the technical synonym.","cn":"拉丁 temperare 及其名词 temperatura 是 temperature 的来源；拉丁 regula 与 regere 是 regulate、regulation 的来源；希腊成分 thermo- 提供技术性同义术语。"},"items":[{"word":"temperature","structure":"temperare + -tura (result noun)","meaning":"a tempering; a measured degree of heat","meaningCN":"调和的结果；测得的冷热程度","example":"The temperature fell below zero before dawn.","exampleCN":"黎明前气温降到了零度以下。"},{"word":"regulate","structure":"regula + -ate (verb-forming)","meaning":"to control by rule","meaningCN":"按规则控制","example":"The valve regulates the flow of steam.","exampleCN":"阀门调节蒸汽流量。"},{"word":"regulation","structure":"regulate + -ion (action or result)","meaning":"the act of controlling; an official rule","meaningCN":"控制动作；正式规章","example":"New regulations govern the discharge of warm water.","exampleCN":"新规章管束温水的排放。"},{"word":"regulator","structure":"regulate + -or (agent)","meaning":"one that regulates","meaningCN":"执行调节者","example":"A pressure regulator sits on the pipe.","exampleCN":"管子上装着一只压力调节器。"},{"word":"regulatory","structure":"regulator + -y (adjective)","meaning":"serving to regulate","meaningCN":"起调节或监管作用的","example":"The agency has regulatory power over the plant.","exampleCN":"该机构对这座工厂拥有监管权。"},{"word":"thermoregulation","structure":"thermo- (Greek 'heat') + regulation","meaning":"the body's own control of heat","meaningCN":"身体自身对热量的调控","example":"Thermoregulation fails first in the very old.","exampleCN":"高龄者的体温调节最先失灵。"},{"word":"thermoregulatory","structure":"thermoregulation + -ory (adjective)","meaning":"relating to heat control","meaningCN":"与体温调节相关的","example":"Panting is a thermoregulatory reflex.","exampleCN":"喘气是一种体温调节反射。"},{"word":"thermometer","structure":"thermo- + Greek metron 'measure'","meaning":"an instrument for measuring heat","meaningCN":"测量冷热程度的仪器","example":"The thermometer read forty degrees at noon.","exampleCN":"正午温度计读数为四十度。"},{"word":"thermostat","structure":"thermo- + Greek statos 'standing'","meaning":"a device that holds a set temperature","meaningCN":"守住设定温度的设备","example":"The thermostat keeps the room at nineteen degrees.","exampleCN":"恒温器把房间保持在十九度。"}],"latinEntries":[{"word":"temperare","structure":"temperare, temperavi, temperatum (verb, first conjugation)","meaning":"to mix in due proportion, regulate","meaningCN":"按比例掺和；调节"},{"word":"temperatura","structure":"temperatura, temperaturae (f., first declension)","meaning":"a tempering, moderation","meaningCN":"调和；适度"},{"word":"regula","structure":"regula, regulae (f., first declension)","meaning":"a straight stick, rule","meaningCN":"直木条；规则"},{"word":"regere","structure":"regere, rexi, rectum (verb, third conjugation)","meaning":"to lead straight, direct, rule","meaningCN":"引直；指导；统治"}]}},{"word":"hibernation","ipa_uk":"/ˌhaɪbəˈneɪʃn/","ipa_us":"/ˌhaɪbərˈneɪʃən/","definition_zh":"冬眠；越冬休眠状态；（计算机）休眠","definition_en":"a state in which an animal passes the winter with greatly lowered body temperature and metabolism","core_image":"洞穴深处一只动物蜷成一团，呼吸慢到几乎听不见，洞口外面覆着厚雪","scene":"洞穴深处，一只蝙蝠把身体缩成一团，心跳降到每分钟几次，整个冬天几乎不动。A deep hibernation lets the bat survive months without food.","sceneCN":"这里 hibernation 指「动物以极低代谢状态度过整个冬天的休眠」（第 1 个义项：越冬低代谢休眠状态）；句意为深度冬眠让这只蝙蝠在没有食物的数月里存活。图中可辨识物件：倒挂的蝙蝠、岩壁凹处、呼出的白气、洞口的雪。","pos":[{"tag":"n.","zh":"冬眠；越冬休眠（不可数；指一次具体的冬眠期时可数，复数 hibernations）"}],"collocations":[{"phrase":"enter hibernation","zh":"进入冬眠"},{"phrase":"deep hibernation","zh":"深度冬眠"},{"phrase":"prolonged hibernation","zh":"长时间冬眠"},{"phrase":"hibernation period","zh":"冬眠期"},{"phrase":"hibernation site","zh":"冬眠场所"},{"phrase":"arouse from hibernation","zh":"从冬眠中苏醒"}],"forms":[{"label":"复数（指多次或多种冬眠）","form":"hibernations"},{"label":"动词（冬眠）","form":"hibernate"},{"label":"形容词（冬眠的；冬天的）","form":"hibernal"},{"label":"名词（冬眠者）","form":"hibernator"},{"label":"名词（越冬场所；越冬芽）","form":"hibernaculum"},{"label":"形容词（冬眠中的）","form":"hibernating"}],"derivatives":[{"word":"hibernate","pos":"v.","zh":"hibernate（基础动词；hibernation 由 hibernate + -ion 动作名词后缀构成）→ 以低代谢状态过冬"},{"word":"hibernator","pos":"n.","zh":"hibernate + -or（施动者后缀）→ 进行冬眠的动物"},{"word":"hibernaculum","pos":"n.","zh":"hibernare + -aculum（拉丁「场所」后缀）→ 越冬的巢、穴或越冬芽"},{"word":"hibernal","pos":"adj.","zh":"hibernus（拉丁「冬天的」）+ -al（形容词后缀）→ 属于冬天的"},{"word":"pre-hibernation","pos":"n./adj.","zh":"pre-（在前）+ hibernation → 冬眠之前的积蓄与准备阶段"}],"senses":[{"no":"01","title":"The winter dormant state","titleCN":"动物越冬的低代谢休眠状态","definition":"the condition in which an animal's body temperature, heart rate and metabolism fall sharply for the winter","definitionCN":"动物体温、心率与代谢在冬季大幅下降的状态","example":"A deep hibernation lets the bat survive months without food.","exampleCN":"深度冬眠让这只蝙蝠在没有食物的数月里存活。","why":"Latin hibernare meant 'to pass the winter', so the noun first names the whole wintering, then the physiological state that makes it possible.","whyCN":"拉丁 hibernare 意为「过冬」，因此这个名词先指整个越冬过程，再指使越冬成为可能的生理状态。"},{"no":"02","title":"The span of months spent dormant","titleCN":"处于休眠的那段时间","definition":"the period from the onset of dormancy to the spring awakening","definitionCN":"从进入休眠到春天苏醒之间的这段时间","example":"Their hibernation lasts from the first hard frost to the thaw.","exampleCN":"它们的冬眠从第一场严霜持续到解冻。","why":"A state and the time it fills are named by the same noun, so hibernation can answer the question 'how long?'.","whyCN":"状态与状态所占的时间用同一个名词表达，因此 hibernation 也能回答「多久」。"},{"no":"03","title":"The physiological mechanism behind it","titleCN":"支撑冬眠的生理机制","definition":"the controlled drop in temperature, breathing and heartbeat that keeps the body alive on stored fat","definitionCN":"体温、呼吸与心跳的受控下降，使身体靠储存的脂肪维持生命","example":"Hibernation slows the heart to a few beats a minute.","exampleCN":"冬眠把心跳降到每分钟几次。","why":"The word can name the mechanism rather than the season because the interesting part is how the body survives the cold.","whyCN":"这个词可以指机制而非季节，因为真正引人注意的是身体如何在寒冷中活下来。"},{"no":"04","title":"Winter dormancy in a particular group","titleCN":"某一类群的越冬休眠","definition":"the specific form of winter rest found in bats, insects, snakes or other named animals","definitionCN":"蝙蝠、昆虫、蛇等特定动物所具有的那一种越冬休眠","example":"Insect hibernation may begin long before the first snow.","exampleCN":"昆虫的冬眠可能在第一场雪之前很久就开始。","why":"Because each group does it differently, the noun is often paired with the animal's name to mark a distinct pattern.","whyCN":"因为各类群做法不同，这个名词常与动物名连用，标出一种特定的模式。"},{"no":"05","title":"Suspending a computer to disk","titleCN":"计算机把内存写入磁盘的休眠","definition":"the power state in which a computer writes its memory to disk and shuts down completely until switched on again","definitionCN":"计算机把内存内容写入磁盘并完全断电，直到再次开机才恢复的电源状态","example":"The laptop's hibernation saves the open files to disk before the battery dies.","exampleCN":"笔记本的休眠在电池耗尽前把打开的文件存入磁盘。","why":"The machine imitates the animal: activity stops, the body is preserved in a safe place, and waking is still possible.","whyCN":"机器模仿动物：活动停止，内容被保存在安全处，之后仍能醒来。"},{"no":"06","title":"Induced torpor for long spaceflight","titleCN":"长期太空飞行中的人为休眠设想","definition":"the proposed medical state in which astronauts would be cooled and slowed to cut food, water and oxygen needs","definitionCN":"设想中的医学状态：让航天员降温减速，以减少食物、水与氧气需求","example":"Engineers study hibernation as a way to cut the supplies needed for a Mars mission.","exampleCN":"工程师研究冬眠，把它作为减少火星任务补给需求的办法。","why":"Space medicine borrows the animal strategy because mass is expensive and months of cruising are long.","whyCN":"航天医学借用动物的策略，因为载荷重量昂贵，而数月巡航又太漫长。"},{"no":"07","title":"A period of institutional stagnation","titleCN":"组织或市场的长期蛰伏","definition":"a figurative stretch in which a company, market or project stops growing and waits for better conditions","definitionCN":"公司、市场或项目停止成长、等待时机好转的比喻性停滞期","example":"The industry's hibernation ended when demand returned.","exampleCN":"需求回升后，这个行业的蛰伏期结束了。","why":"The metaphor keeps the shape of the biological state: low activity, preserved resources, eventual waking.","whyCN":"这个比喻保留了生物状态的外形：低活动、保住资源、最终醒来。"},{"no":"08","title":"Therapeutic cooling of a patient","titleCN":"对病人的治疗性低温处理","definition":"a controlled medical cooling used to protect the brain or organs after injury or during long surgery","definitionCN":"在损伤之后或长时间手术中，用受控降温保护大脑或器官的医疗手段","example":"Doctors are testing induced hibernation to protect tissue during long operations.","exampleCN":"医生正在试验诱导性休眠，以在长时间手术中保护组织。","why":"The clinical sense borrows the name because cooling slows demand for oxygen in tissue, as it does in a hibernating animal.","whyCN":"临床义借用这个名称，因为降温会像冬眠动物那样降低组织对氧的需求。"}],"etymology":{"intro":{"en":"Hibernation comes from Latin hibernare 'to pass the winter', a verb built on hibernus 'wintry' and hiems 'winter'. The noun entered English in the seventeenth century, first as a description of wintering and soon as a biological state.","cn":"hibernation 来自拉丁 hibernare「过冬」，该动词由 hibernus「冬天的」与 hiems「冬天」构成。这个名词在十七世纪进入英语，最初描述越冬，随后指生物学上的休眠状态。"},"items":[{"era":"LATIN HIEMS","en":"Hiems was the ordinary Latin noun for winter. Its further origin is usually traced to a reconstructed Indo-European root for snow and winter, written with an asterisk because the form is reconstructed, not attested.","cn":"hiems 是拉丁语中表示「冬天」的常用名词。其更早来源一般追溯到原始印欧语中表示雪与冬天的重构词根；因该形式是重构而非有文献佐证，学界用星号标出。"},{"era":"LATIN HIBERNUS","en":"Hibernus meant 'wintry, of winter', an adjective derived from hiems. It survives in English hibernal, a formal word for winter things.","cn":"hibernus 意为「冬天的、冬季的」，是由 hiems 派生的形容词，在英语中留下 hibernal 这一正式用词。"},{"era":"LATIN HIBERNARE","en":"Hibernare meant 'to winter, to spend the winter'. In classical use it described soldiers wintering in camp; the biological sense of torpor is a later scientific narrowing.","cn":"hibernare 意为「过冬、度过冬天」。古典用法指士兵在营地越冬；指生理性昏睡的生物学义是后来科学用法的收窄。"},{"era":"SEVENTEENTH-CENTURY ENGLISH","en":"English took the noun in the 1660s, at first for the act of wintering and then for the dormant condition of animals. The precise first written date varies between sources.","cn":"英语在十七世纪六十年代引入这个名词，先指越冬这件事，后指动物的休眠状态。各家记载的最早书面年代略有出入。"},{"era":"MODERN PHYSIOLOGY","en":"As physiology measured metabolism, the word was fixed to the state of lowered temperature, heart rate and oxygen use, distinguishing true hibernation from ordinary sleep.","cn":"随着生理学能够测量代谢，这个词被固定为体温、心率与耗氧下降的状态，从而与普通睡眠区分开来。"},{"era":"TWENTIETH-CENTURY COMPUTING","en":"Computing borrowed the word in the late twentieth century for the power state that writes memory to disk and shuts the machine down.","cn":"计算技术在二十世纪后期借用这个词，指把内存写入磁盘并关机的电源状态。"}]},"similar":{"note":{"en":"Group one holds forms from the same Latin winter family that are easily mixed up; group two holds other words for reduced biological activity.","cn":"第一组是同出拉丁「冬天」词族、容易混淆的形式；第二组是其他表示生物活动降低的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hibernal","ipa":"/haɪˈbɜːnl/","tag":"same family, adjective","definition":"An adjective meaning 'of winter', from hibernus; it describes the season, not the dormant state.","definitionCN":"由 hibernus 来的形容词，意为「冬季的」，描述季节而非休眠状态。"},{"word":"hibernaculum","ipa":"/ˌhaɪbəˈnækjələm/","tag":"same family, a place","definition":"The Latin word for winter quarters, used in biology for the shelter or bud in which an organism overwinters.","definitionCN":"拉丁语「冬营」，生物学用来指生物越冬所在的巢穴或越冬芽。"},{"word":"hibernator","ipa":"/ˈhaɪbəneɪtə/","tag":"same family, an agent","definition":"The agent noun for an animal that hibernates, formed with -or just as in generator or oscillator.","definitionCN":"指进行冬眠的动物的施动名词，与 generator、oscillator 一样由 -or 构成。"},{"word":"hibernate","ipa":"/ˈhaɪbəneɪt/","tag":"same family, the verb","definition":"The verb behind the noun; using it in place of hibernation changes the sentence from a state to an action.","definitionCN":"名词背后的动词；用它替换 hibernation，句子就从状态变成动作。"}]},{"heading":"NEAR MEANING","entries":[{"word":"dormancy","ipa":"/ˈdɔːmənsi/","tag":"general growth pause","definition":"A broad term for any temporary slowdown in growth or activity, including seeds and buds; hibernation is one winter form of it.","definitionCN":"泛指生长或活动暂时减慢，包括种子与芽；冬眠是其中一种冬季形式。"},{"word":"torpor","ipa":"/ˈtɔːpə/","tag":"short daily slowness","definition":"A short-term drop in body temperature and activity, often nightly; hibernation is the long seasonal version.","definitionCN":"体温与活动短时间下降，常按夜发生；冬眠是漫长的季节性版本。"},{"word":"aestivation","ipa":"/ˌiːstɪˈveɪʃn/","tag":"the summer counterpart","definition":"The summer equivalent, passed through heat or drought rather than cold; the two words are seasonal opposites.","definitionCN":"夏季对应形式，是在炎热或干旱中而非寒冷中度过；两词是季节上的对立面。"},{"word":"overwintering","ipa":"/ˌəʊvəˈwɪntərɪŋ/","tag":"surviving, not necessarily dormant","definition":"Surviving the winter by any strategy, including migration or active foraging; it does not require deep torpor.","definitionCN":"以任何策略活过冬天，包括迁徙或照常觅食；不要求深度昏睡。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin hiems 'winter' plus hibernus 'wintry' gives hibernare 'to winter': winter turned into a verb.","cn":"拉丁 hiems「冬天」加 hibernus「冬季的」得出 hibernare「过冬」：把冬天变成动词。"},{"en":"The family runs hibernate, hibernation, hibernator, hibernaculum, hibernal, pre-hibernation.","cn":"同族词包括 hibernate、hibernation、hibernator、hibernaculum、hibernal、pre-hibernation。"},{"en":"Fixed phrases mark the state: enter hibernation, deep hibernation, arouse from hibernation.","cn":"固定搭配标出状态：进入冬眠、深度冬眠、从冬眠中苏醒。"},{"en":"The computer command hibernate uses the same picture: save the body, stop the clock, wake later.","cn":"电脑的休眠命令用的是同一幅图：保存身体、停下时钟、日后再唤醒。"},{"en":"Hibernation is seasonal, not nightly: torpor is the short version, hibernation the long one.","cn":"冬眠是季节性的而非每夜的：昏睡是短版本，冬眠是长版本。"}],"abstract":[{"en":"Picture a clock wound down but not broken, its hands parked until someone shakes it.","cn":"想象一只发条松开却未损坏的钟，指针停着，直到有人把它摇醒。"},{"en":"Picture a house closed for the winter with the water drained and the furniture under sheets.","cn":"想象一栋为过冬而封闭的房子，水排空了，家具盖着布。"},{"en":"Picture a seed of silence kept in a drawer until spring opens it.","cn":"想象一粒「沉默的种子」放在抽屉里，等春天把它打开。"}]},"examples":[{"en":"A deep hibernation lets the bat survive months without food.","cn":"深度冬眠让这只蝙蝠在没有食物的数月里存活。"},{"en":"Hibernation slows the heart to a few beats a minute.","cn":"冬眠把心跳降到每分钟几次。"},{"en":"The laptop's hibernation saves the open files to disk before the battery dies.","cn":"笔记本的休眠在电池耗尽前把打开的文件存入磁盘。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「嗨，被窝」——天冷了钻进被窝长睡不醒 → 冬眠","word":"hibernation"},"root":"拉丁 hibernare「过冬」，由 hibernus「冬天的」构成，源于 hiems「冬天」；更早形式一般追溯到原始印欧语表示雪与冬天的重构词根（带星号的重构形式），确切音形存疑。英语 hibernate / hibernation。","sensesIntro":{"en":"Eight senses follow one gesture: life turns itself down to a minimum and waits. The gesture is biological first, then extends to machines, spaceflight, institutions and hospitals.","cn":"八个义项沿同一个动作展开：生命把自己调到最低限度然后等待。这个动作先属于生物，再延伸到机器、航天、机构与医院。"},"semanticMap":{"core":{"en":"CORE IMAGE: a curled body in a cold chamber, breathing almost unheard, snow at the entrance.","cn":"核心意象：寒冷洞穴里蜷成一团的身体，呼吸几乎听不见，洞口是雪。"},"chain":["WINTER","SLOW DOWN","STORE FAT","LOW METABOLISM","LONG WAIT","WAKING"],"branches":[{"senses":"S1 · S3","en":"THE STATE ITSELF: the body's heat, pulse and fuel use all fall to a floor that still supports life.","cn":"状态本身：体温、脉搏与燃料消耗都降到仍能维持生命的下限。"},{"senses":"S2 · S4","en":"TIME AND GROUP: the noun also measures how long the wait lasts and marks how a given animal performs it.","cn":"时间与类群：这个名词还计量等待多久，并标出某类动物的具体做法。"},{"senses":"S5 · S7","en":"BORROWED WAIT: a machine or an industry copies the shape, stopping activity while preserving what matters.","cn":"借来的等待：机器或行业复制这个外形，停掉活动却保住要紧之物。"},{"senses":"S6","en":"ENGINEERED TORPOR: spaceflight proposes to impose the state deliberately to save mass.","cn":"设计出来的昏睡：航天设想人为施加此状态以节省载荷。"},{"senses":"S8","en":"MEDICAL COOLING: hospitals induce a mild version to slow tissue demand.","cn":"医疗降温：医院诱导轻度版本以降低组织需求。"}]},"affixes":{"intro":{"en":"Hibernation is a Latin verb plus a noun suffix, and nearly every part of the family can be read off the same winter root.","cn":"hibernation 是一个拉丁动词加名词后缀，词族中几乎每个成员都能沿同一个「冬天」词根读出来。"},"latinIntro":{"en":"Latin hiems 'winter' gives hibernus 'wintry', which gives hibernare 'to winter'; -atio supplies the action noun, -or the agent and -aculum the place.","cn":"拉丁 hiems「冬天」生出 hibernus「冬季的」，再生动词 hibernare「过冬」；-atio 提供动作名词，-or 表施动者，-aculum 表场所。"},"items":[{"word":"hiems","structure":"hiems, hiemis (Latin noun, third declension)","meaning":"winter","meaningCN":"冬天","example":"Hiems longa erat.","exampleCN":"那个冬天很漫长。"},{"word":"hibernus","structure":"hiems + -rnus (adjective)","meaning":"wintry, of winter","meaningCN":"冬季的","example":"Hibernus ventus mare vexat.","exampleCN":"冬季的风搅扰着大海。"},{"word":"hibernate","structure":"hibernare (Latin verb) + English verb ending","meaning":"to pass the winter dormant","meaningCN":"以休眠状态过冬","example":"Some bats hibernate in caves.","exampleCN":"有些蝙蝠在洞穴里冬眠。"},{"word":"hibernation","structure":"hibernate + -ation (action or state)","meaning":"the state of winter dormancy","meaningCN":"冬季休眠状态","example":"Hibernation lowers the heart rate sharply.","exampleCN":"冬眠使心率大幅下降。"},{"word":"hibernator","structure":"hibernate + -or (agent)","meaning":"an animal that hibernates","meaningCN":"进行冬眠的动物","example":"The cave shelters many hibernators.","exampleCN":"这个洞穴庇护着许多冬眠动物。"},{"word":"hibernaculum","structure":"hibernare + -aculum (place)","meaning":"winter quarters; an overwintering bud","meaningCN":"越冬处所；越冬芽","example":"The larva builds a hibernaculum under the bark.","exampleCN":"幼虫在树皮下筑一个越冬室。"},{"word":"hibernal","structure":"hibernus + -al (adjective)","meaning":"belonging to winter","meaningCN":"属于冬天的","example":"The hibernal light never fully warmed the room.","exampleCN":"冬日的光始终没能把屋子晒暖。"},{"word":"hibernating","structure":"hibernate + -ing (participial adjective)","meaning":"currently in winter dormancy","meaningCN":"正处于冬眠中的","example":"A hibernating bear can be roused but wakes slowly.","exampleCN":"冬眠中的熊可被惊动，但醒来很慢。"},{"word":"pre-hibernation","structure":"pre- (before) + hibernation","meaning":"the fattening period before dormancy","meaningCN":"进入休眠前的积蓄期","example":"Pre-hibernation feeding doubled the animal's weight.","exampleCN":"冬眠前的进食使这只动物的体重翻倍。"}],"latinEntries":[{"word":"hiems","structure":"hiems, hiemis (f., third declension)","meaning":"winter","meaningCN":"冬天"},{"word":"hibernus","structure":"hibernus, hiberna, hibernum (adjective)","meaning":"wintry, of winter","meaningCN":"冬季的；寒冷的"},{"word":"hibernare","structure":"hibernare, hibernavi, hibernatum (verb, first conjugation)","meaning":"to winter, pass the winter","meaningCN":"过冬；越冬"},{"word":"hibernaculum","structure":"hibernaculum, hibernaculi (n., second declension)","meaning":"winter quarters","meaningCN":"冬营；越冬处"}]}},{"word":"hibernate","ipa_uk":"/ˈhaɪbəneɪt/","ipa_us":"/ˈhaɪbərneɪt/","definition_zh":"冬眠；越冬休眠；（计算机）休眠","definition_en":"to pass the winter in a dormant state with lowered body temperature and metabolism","core_image":"秋末一只动物把自己塞进洞穴，呼吸与心跳慢下来，直到春天的暖意把它唤醒","scene":"秋末，一只蝙蝠钻进废弃矿井的深处，体温降到接近洞壁的温度。Some bats hibernate in caves where the temperature stays above freezing.","sceneCN":"这里 hibernate 指「以低代谢状态度过冬天」（第 1 个义项：动物越冬休眠）；句意为有些蝙蝠在温度保持在冰点以上的洞穴里冬眠。图中可辨识物件：矿井支架、倒挂的蝙蝠、岩壁水痕、洞口霜花。","pos":[{"tag":"vi.","zh":"冬眠；越冬休眠（不及物；主语为动物）"},{"tag":"vi.","zh":"（计算机）休眠（不及物；主语为设备或系统）"}],"collocations":[{"phrase":"hibernate through the winter","zh":"整个冬天都在冬眠"},{"phrase":"hibernate in a cave","zh":"在洞穴里冬眠"},{"phrase":"hibernate underground","zh":"在地下冬眠"},{"phrase":"hibernate for months","zh":"冬眠数月"},{"phrase":"hibernate mode","zh":"休眠模式"},{"phrase":"hibernate until spring","zh":"冬眠到春天"}],"forms":[{"label":"三单（he/she/it）","form":"hibernates"},{"label":"过去式","form":"hibernated"},{"label":"过去分词","form":"hibernated"},{"label":"现在分词","form":"hibernating"},{"label":"名词（冬眠）","form":"hibernation"},{"label":"形容词（冬天的）","form":"hibernal"}],"derivatives":[{"word":"hibernation","pos":"n.","zh":"hibernate + -ion（拉丁 -atio 动作名词后缀）→ 冬眠这一状态"},{"word":"hibernator","pos":"n.","zh":"hibernate + -or（施动者后缀）→ 进行冬眠的动物"},{"word":"hibernaculum","pos":"n.","zh":"hibernare + -aculum（场所后缀）→ 越冬的巢穴或越冬芽"},{"word":"hibernal","pos":"adj.","zh":"hibernus（冬天的）+ -al（形容词后缀）→ 冬季的"},{"word":"hibernating","pos":"adj.","zh":"hibernate + -ing（分词形容词）→ 正处于冬眠中的"}],"senses":[{"no":"01","title":"Pass the winter in dormancy","titleCN":"以休眠状态度过冬天","definition":"to spend the winter with body temperature, breathing and metabolism greatly reduced","definitionCN":"在体温、呼吸与代谢大幅降低的状态下度过冬天","example":"Some bats hibernate in caves where the temperature stays above freezing.","exampleCN":"有些蝙蝠在温度保持在冰点以上的洞穴里冬眠。","why":"The Latin verb hibernare simply meant 'to winter'; science narrowed it to wintering in torpor.","whyCN":"拉丁动词 hibernare 本只表示「过冬」；科学用法把它收窄为「在昏睡中过冬」。"},{"no":"02","title":"Survive the cold season","titleCN":"活过寒冷季节（较宽泛的用法）","definition":"to get through the winter, whether by torpor or by some other quiet strategy","definitionCN":"度过冬天，无论靠昏睡还是别的安静策略","example":"The colony hibernates through the coldest eight weeks of the year.","exampleCN":"这个群体在一年中最冷的八周里越冬休眠。","why":"Because the verb names the season itself, it can still carry the older, looser sense of simply lasting until spring.","whyCN":"因为这个动词本指季节本身，所以仍保留较宽松的旧义：只是撑到春天。"},{"no":"03","title":"Put a computer into its disk-saved sleep","titleCN":"让计算机进入把内存存入磁盘的休眠","definition":"to switch a computer into the state that writes memory to disk and cuts all power","definitionCN":"把计算机切换到写入内存到磁盘并完全断电的状态","example":"Set the laptop to hibernate when the lid has been closed for an hour.","exampleCN":"把笔记本设为合盖一小时后休眠。","why":"The machine is said to hibernate because it too stops, stores its contents and waits to be woken.","whyCN":"机器也被说成 hibernate，因为它同样停下、存放内容、等待被唤醒。"},{"no":"04","title":"Withdraw from activity for a long stretch","titleCN":"长期退出活动（人或组织的比喻用法）","definition":"to stop working, publishing or competing for a long period and then return","definitionCN":"长时间停止工作、发表或竞争，然后再回来","example":"The author hibernated for three years and then published a short, sharp book.","exampleCN":"这位作者蛰伏三年，然后出版了一本短而锐利的书。","why":"Withdrawal plus preserved capacity is the same shape as torpor, so the verb transfers easily to people and careers.","whyCN":"退出加上保有能力，与昏睡同形，因此这个动词很容易转到人和事业上。"},{"no":"05","title":"Stay indoors through the cold months","titleCN":"整个冬天闭门不出","definition":"to leave the house as little as possible during winter, in informal speech","definitionCN":"口语中指冬天尽量不出门","example":"We hibernate at home from December to March, baking and watching old films.","exampleCN":"我们从十二月到三月都窝在家里，烤点心、看老电影。","why":"The humorous human use keeps only the shell of the word: warm shelter, low activity, no travel.","whyCN":"人的幽默用法只保留这个词的外壳：温暖的住处、低活动、不出行。"},{"no":"06","title":"Overwinter in a particular animal group","titleCN":"某类动物特有的越冬方式","definition":"to adopt the winter rest characteristic of bats, insects, snakes or another named group","definitionCN":"采用蝙蝠、昆虫、蛇等特定类群所具有的越冬休眠方式","example":"Certain insects hibernate as larvae buried below the frost line.","exampleCN":"某些昆虫以幼虫形态在冻线以下休眠越冬。","why":"Group names add information because the physiological pattern differs sharply from species to species.","whyCN":"加上类群名能补充信息，因为不同物种的生理模式差别很大。"},{"no":"07","title":"Fall into a long idle state","titleCN":"设备或账户长期闲置后自动停用","definition":"to become inactive after a long period without use, as an account, service or machine does","definitionCN":"长时间无人使用后进入不活跃状态，如账户、服务或机器","example":"Dormant accounts hibernate after two years and need a fresh login.","exampleCN":"休眠账户两年后会停用，需要重新登录。","why":"This technical use borrows only the pause, not the metabolism: nothing is stored except state.","whyCN":"这一技术用法只借用「暂停」，不涉及代谢：除了状态之外没有东西被保存。"},{"no":"08","title":"Lie low and revive later","titleCN":"暂时停摆、日后再复苏","definition":"to remain inactive as a project or plan until conditions allow it to start again","definitionCN":"作为项目或计划保持不活跃，直到条件允许重新启动","example":"The plan hibernated during the funding freeze and revived last spring.","exampleCN":"这项计划在资金冻结期间停摆，去年春天又复苏了。","why":"The word promises revival: hibernation is a pause, not an ending, which is why it suits stalled projects.","whyCN":"这个词承诺复苏：冬眠只是暂停而非终结，因此适合形容停滞的项目。"}],"etymology":{"intro":{"en":"Hibernate is a seventeenth-century English verb from Latin hibernare 'to pass the winter', itself from hibernus 'wintry' and hiems 'winter'. The Latin verb first described soldiers and animals wintering in place.","cn":"hibernate 是十七世纪英语动词，来自拉丁 hibernare「过冬」，后者又由 hibernus「冬季的」与 hiems「冬天」构成。该拉丁动词最初描述士兵与动物在原地越冬。"},"items":[{"era":"LATIN HIEMS","en":"Hiems was the standard noun for winter. Its earlier history is usually traced to a reconstructed Indo-European root for snow, a form marked with an asterisk because it is rebuilt rather than recorded.","cn":"hiems 是表示「冬天」的标准拉丁名词。其更早历史一般追溯到原始印欧语中表示雪的重构词根，该形式带星号，表示是重建而非有记录。"},{"era":"LATIN HIBERNUS","en":"From hiems came hibernus 'wintry', which survives in the English adjective hibernal and in the name of the winter months.","cn":"由 hiems 生出 hibernus「冬季的」，它留在英语形容词 hibernal 中，也留在冬季月份的名称里。"},{"era":"LATIN HIBERNARE","en":"Hibernare meant 'to winter, to spend the winter'. Classical writers used it of troops in winter camp, not yet of animals in torpor.","cn":"hibernare 意为「过冬、度过冬天」。古典作家用它指部队在冬营驻扎，尚未用于动物的昏睡。"},{"era":"ENGLISH VERB","en":"The English verb appears in the seventeenth century. Sources differ on the exact first record, so the date should be treated as approximate.","cn":"英语动词出现于十七世纪。各家对确切首见记载说法不一，因此年代应视为约数。"},{"era":"SCIENTIFIC NARROWING","en":"Nineteenth- and twentieth-century physiology fixed the verb to the measurable state of low temperature, slow pulse and reduced oxygen use.","cn":"十九至二十世纪的生理学把这个动词固定为体温低、脉搏慢、耗氧少这一可测量状态。"},{"era":"COMPUTING EXTENSION","en":"Late twentieth-century computing extended the verb to a machine state, keeping the metaphor of a body saved and asleep.","cn":"二十世纪后期的计算技术把这个动词扩展到机器状态，保留了「身体被保存并睡着」的比喻。"}]},"similar":{"note":{"en":"Group one holds members of the same winter family that differ only by suffix; group two holds other verbs for resting through a hard season.","cn":"第一组是同一「冬天」词族中仅后缀不同的成员；第二组是其他表示在艰难季节中休息的动词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"hibernation","ipa":"/ˌhaɪbəˈneɪʃn/","tag":"same verb, noun","definition":"The noun of the same verb, naming the state rather than the act; swapping the two changes the grammar of the sentence.","definitionCN":"同一动词的名词形式，指状态而非动作；两者互换会改变句子的语法结构。"},{"word":"hibernal","ipa":"/haɪˈbɜːnl/","tag":"same family, season","definition":"An adjective for 'of winter', from hibernus; it describes weather or light, never an animal's behaviour.","definitionCN":"由 hibernus 来的「冬季的」形容词，描述天气或光线，绝不描述动物行为。"},{"word":"hibernaculum","ipa":"/ˌhaɪbəˈnækjələm/","tag":"same family, shelter","definition":"The place or bud in which an organism overwinters; it is a noun of location, not an action.","definitionCN":"生物越冬所在的处所或越冬芽；是表示地点的名词，不是动作。"},{"word":"hibernator","ipa":"/ˈhaɪbəneɪtə/","tag":"same family, agent","definition":"The animal that performs the action, formed with the agent suffix -or.","definitionCN":"执行这一动作的动物，由施动后缀 -or 构成。"}]},{"heading":"NEAR MEANING","entries":[{"word":"overwinter","ipa":"/ˌəʊvəˈwɪntə/","tag":"survive by any means","definition":"To live through the winter by whatever strategy, including staying active; hibernate names one specific strategy.","definitionCN":"以任何策略活过冬天，包括保持活动；hibernate 只指其中一种特定策略。"},{"word":"aestivate","ipa":"/ˈiːstɪveɪt/","tag":"summer counterpart","definition":"To pass the hot or dry season in dormancy; it is the seasonal mirror image of hibernate.","definitionCN":"在炎热或干旱季节休眠；是 hibernate 在季节上的镜像对应词。"},{"word":"sleep","ipa":"/sliːp/","tag":"daily rest","definition":"Ordinary nightly rest with quick waking and normal body temperature; it is far shallower than hibernation.","definitionCN":"普通的夜间休息，容易唤醒且体温正常；比冬眠浅得多。"},{"word":"lie dormant","ipa":"/laɪ ˈdɔːmənt/","tag":"state phrase","definition":"A phrase for being inactive and waiting, often used of ideas, seeds or diseases; it lacks the seasonal winter frame.","definitionCN":"表示不活动并等待的短语，常用于想法、种子或疾病；没有冬季这一季节框架。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Hibernare is 'to winter': the verb is winter turned into an action.","cn":"hibernare 就是「过冬」：这个动词是把冬天变成动作。"},{"en":"The family runs hibernate, hibernation, hibernator, hibernaculum, hibernal, hibernating.","cn":"同族词包括 hibernate、hibernation、hibernator、hibernaculum、hibernal、hibernating。"},{"en":"Fixed phrases mark the use: hibernate through the winter, hibernate in a cave, hibernate until spring.","cn":"固定搭配标出用法：整个冬天冬眠、在洞穴里冬眠、冬眠到春天。"},{"en":"The computer menu item hibernate keeps the same metaphor of a saved body and a stopped clock.","cn":"电脑菜单里的休眠项保留了「保存身体、停下时钟」的同一比喻。"},{"en":"The stress falls on the first syllable: HIB-er-nate, like HIB-ernal.","cn":"重音落在第一音节：HIB-er-nate，与 HIB-ernal 一致。"}],"abstract":[{"en":"Picture an animal folding itself into a drawer and pulling the drawer shut.","cn":"想象一只动物把自己折进抽屉，再把抽屉推上。"},{"en":"Picture a machine saving its whole mind onto a disk before going dark.","cn":"想象一台机器在熄灭前把整个「心思」存进磁盘。"},{"en":"Picture a writer who disappears, then returns with a finished book.","cn":"想象一位作家消失一段时间，再带着写完的书回来。"}]},"examples":[{"en":"Some bats hibernate in caves where the temperature stays above freezing.","cn":"有些蝙蝠在温度保持在冰点以上的洞穴里冬眠。"},{"en":"Certain insects hibernate as larvae buried below the frost line.","cn":"某些昆虫以幼虫形态在冻线以下休眠越冬。"},{"en":"Set the laptop to hibernate when the lid has been closed for an hour.","cn":"把笔记本设为合盖一小时后休眠。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「嗨，被窝里头」——钻进被窝把头一蒙，睡过整个冬天 → 冬眠","word":"hibernate"},"root":"拉丁 hibernare「过冬」，由 hibernus「冬天的」构成，源于 hiems「冬天」；更早形式一般追溯到原始印欧语表示雪与冬天的重构词根（星号形式为重构，非实录），确切音形存疑。英语 hibernate。","sensesIntro":{"en":"Eight senses follow one gesture: activity is switched off and kept off. Biology owns the gesture; people, machines and projects borrow it.","cn":"八个义项沿同一个动作展开：把活动关掉并保持关着。生物学拥有这个动作；人、机器与项目借用它。"},"semanticMap":{"core":{"en":"CORE IMAGE: a body tucked into a cold hole, its pulse slowed to a whisper, waiting for warmth.","cn":"核心意象：一具身体缩进寒冷的洞穴，脉搏慢成耳语，等待暖意。"},"chain":["COLD SEASON","WITHDRAW","SLOW PULSE","LOW FUEL","SUSPENDED TIME","REVIVAL"],"branches":[{"senses":"S1 · S2","en":"SEASONAL REST: the core act is wintering, with torpor as its technical and its looser reading.","cn":"季节性休息：核心动作是越冬，既可读作昏睡，也可读作较宽松的撑过冬天。"},{"senses":"S3 · S7","en":"SWITCHED-OFF MACHINE: equipment copies the pause but stores only its state.","cn":"关掉的机器：设备复制了暂停，但只保存状态。"},{"senses":"S4 · S8","en":"HUMAN AND PROJECT WITHDRAWAL: a person or plan lies low with capacity intact, then returns.","cn":"人与项目的退隐：人或计划带着完整能力潜伏，然后回来。"},{"senses":"S5","en":"HOMELY SHELTER: the everyday sense keeps only warmth, food and no travel.","cn":"居家的庇护：日常义只保留温暖、食物与不出行。"},{"senses":"S6","en":"GROUP PATTERN: different animals perform the same act in sharply different ways.","cn":"类群模式：不同动物以差别很大的方式完成同一动作。"}]},"affixes":{"intro":{"en":"Hibernate is the bare Latin verb adapted to English, and every family member adds a different suffix to the same winter root.","cn":"hibernate 是把拉丁动词直接改成英语，词族每个成员都是在同一「冬天」词根上加不同后缀。"},"latinIntro":{"en":"Hiems 'winter' gives hibernus 'wintry' and hibernare 'to winter'; -atio makes the state noun, -or the agent, -aculum the place, -al the adjective.","cn":"hiems「冬天」生出 hibernus「冬季的」与 hibernare「过冬」；-atio 构成状态名词，-or 表施动者，-aculum 表场所，-al 构成形容词。"},"items":[{"word":"hiems","structure":"hiems, hiemis (Latin noun, third declension)","meaning":"winter","meaningCN":"冬天","example":"Hiems appropinquat.","exampleCN":"冬天临近了。"},{"word":"hibernus","structure":"hiems + -rnus (adjective)","meaning":"wintry","meaningCN":"冬季的","example":"Hiberna tempora dura sunt.","exampleCN":"冬季的时节很艰苦。"},{"word":"hibernate","structure":"hibernare + English verb form","meaning":"to winter in torpor","meaningCN":"昏睡过冬","example":"The frogs hibernate under the mud.","exampleCN":"这些蛙在泥下冬眠。"},{"word":"hibernation","structure":"hibernate + -ation (state noun)","meaning":"winter dormancy","meaningCN":"冬季休眠","example":"Hibernation begins with the first frost.","exampleCN":"冬眠随第一场霜开始。"},{"word":"hibernator","structure":"hibernate + -or (agent)","meaning":"one that hibernates","meaningCN":"冬眠者","example":"Bats are the most familiar hibernators.","exampleCN":"蝙蝠是最为人熟知的冬眠动物。"},{"word":"hibernaculum","structure":"hibernare + -aculum (place)","meaning":"a winter shelter","meaningCN":"越冬处所","example":"The pupa rests in a silk hibernaculum.","exampleCN":"蛹在丝质越冬室里休息。"},{"word":"hibernal","structure":"hibernus + -al (adjective)","meaning":"of winter","meaningCN":"冬季的","example":"Hibernal storms closed the pass.","exampleCN":"冬季风暴封住了山口。"},{"word":"hibernating","structure":"hibernate + -ing (participle)","meaning":"in the act of winter dormancy","meaningCN":"正在冬眠的","example":"A hibernating animal should not be disturbed.","exampleCN":"不应打扰冬眠中的动物。"},{"word":"pre-hibernation","structure":"pre- + hibernation","meaning":"the preparation before dormancy","meaningCN":"冬眠前的准备期","example":"Pre-hibernation fat is laid down in autumn.","exampleCN":"冬眠前的脂肪在秋季囤积。"}],"latinEntries":[{"word":"hiems","structure":"hiems, hiemis (f., third declension)","meaning":"winter","meaningCN":"冬天"},{"word":"hibernus","structure":"hibernus, hiberna, hibernum (adjective)","meaning":"wintry, of winter","meaningCN":"冬季的"},{"word":"hibernare","structure":"hibernare, hibernavi, hibernatum (verb, first conjugation)","meaning":"to winter, pass the winter","meaningCN":"过冬；越冬"},{"word":"hibernaculum","structure":"hibernaculum, hibernaculi (n., second declension)","meaning":"winter quarters","meaningCN":"冬营；越冬处"}]}},{"word":"aestivation","ipa_uk":"/ˌiːstɪˈveɪʃn/","ipa_us":"/ˌiːstəˈveɪʃən/","definition_zh":"夏眠；越夏休眠；（植物学）花被片在花蕾中的排列方式","definition_en":"a dormant state that carries an animal or plant through a hot, dry season; in botany, the way flower parts are folded inside a bud","core_image":"干裂的泥面上，一只蜗牛用黏液封住壳口，把自己关进一层白膜，等雨水回来","scene":"旱季里，池塘缩成一块泥地，蜗牛把壳口封住，缩进壳里不动。Snails enter aestivation when the pond dries and the mud hardens.","sceneCN":"这里 aestivation 指「动物为熬过炎热干旱而进入的休眠」（第 1 个义项：越夏干旱休眠状态）；句意为池塘干涸、泥巴变硬时，蜗牛进入夏眠。图中可辨识物件：龟裂的泥面、封口的蜗牛壳、干枯的草茎、远处的太阳。","pos":[{"tag":"n.","zh":"夏眠；越夏休眠（不可数；指一次具体的夏眠期时可数，复数 aestivations）"},{"tag":"n.","zh":"（植物学）花被片卷叠式；花蕾中各部分的排列方式（可数）"}],"collocations":[{"phrase":"enter aestivation","zh":"进入夏眠"},{"phrase":"aestivation period","zh":"夏眠期"},{"phrase":"aestivation site","zh":"夏眠场所"},{"phrase":"summer aestivation","zh":"夏季休眠"},{"phrase":"floral aestivation","zh":"花被卷叠式"},{"phrase":"arouse from aestivation","zh":"从夏眠中苏醒"}],"forms":[{"label":"复数（指多次夏眠或多种排列式）","form":"aestivations"},{"label":"动词（夏眠）","form":"aestivate"},{"label":"美式拼写（同义）","form":"estivation"},{"label":"形容词（夏季的）","form":"aestival"},{"label":"形容词（夏眠中的）","form":"aestivating"},{"label":"名词（夏眠动物）","form":"aestivator"}],"derivatives":[{"word":"aestivate","pos":"v.","zh":"aestivate（基础动词；aestivation 由 aestivate + -ion 动作名词后缀构成）→ 以休眠状态度过炎热干旱的季节"},{"word":"estivation","pos":"n.","zh":"aestivation 的美式拼写变体，去掉 a- 的拉丁二合字母 → 词义完全相同"},{"word":"aestival","pos":"adj.","zh":"aestas（拉丁「夏天」）+ -ival（形容词后缀）→ 属于夏天的"},{"word":"aestivating","pos":"adj.","zh":"aestivate + -ing（分词形容词）→ 正处于夏眠中的"},{"word":"aestivator","pos":"n.","zh":"aestivate + -or（施动者后缀，较少用）→ 进行夏眠的生物"}],"senses":[{"no":"01","title":"Dormancy through heat and drought","titleCN":"为熬过炎热与干旱而休眠","definition":"the state in which an animal slows its metabolism and shuts itself away until rain or cooler weather returns","definitionCN":"动物降低代谢、把自己封闭起来，直到降雨或凉爽天气回来的状态","example":"Snails enter aestivation when the pond dries and the mud hardens.","exampleCN":"池塘干涸、泥巴变硬时，蜗牛进入夏眠。","why":"Latin aestas meant 'summer', and aestivare meant 'to spend the summer': the word names the season that must be survived.","whyCN":"拉丁 aestas 意为「夏天」，aestivare 意为「度夏」：这个词命名的正是必须熬过去的那一季。"},{"no":"02","title":"The span of the summer rest","titleCN":"夏眠持续的那段时间","definition":"the period from sealing oneself away to the first soaking rain that ends the rest","definitionCN":"从封闭自身到第一场透雨结束休眠之间的这段时间","example":"Their aestivation can last eight months in a dry year.","exampleCN":"在干旱年份，它们的夏眠可以持续八个月。","why":"The noun names both the state and its duration, just as winter sleep does in hibernation.","whyCN":"这个名词既指状态也指时长，正如 hibernation 既指冬眠也指冬眠期。"},{"no":"03","title":"The water-saving mechanism","titleCN":"保水与降低代谢的生理机制","definition":"the sealed shell mouth, mucus plug or buried cocoon that stops water loss during the hot season","definitionCN":"用封住壳口、黏液塞或埋在泥中的茧来阻止失水的机制","example":"Aestivation relies on a mucus seal that cuts water loss almost to zero.","exampleCN":"夏眠依靠黏液封口，把失水几乎降到零。","why":"Heat and drought attack through water loss, so the mechanism is a seal rather than a heater or a cooler.","whyCN":"炎热与干旱通过失水来攻击，因此机制是一道封口，而不是加热或降温。"},{"no":"04","title":"Summer rest in a named animal group","titleCN":"某一类动物的越夏休眠","definition":"the particular form of summer dormancy seen in snails, mudfish, certain frogs or insects","definitionCN":"蜗牛、泥鳅、某些蛙或昆虫所表现的那种夏季休眠","example":"Mudfish aestivation is famous because the fish survives in a dried mud cocoon.","exampleCN":"泥鳅的夏眠很有名，因为它能在干泥茧中存活。","why":"Different groups seal themselves differently, so the noun is often tied to the animal to mark the pattern.","whyCN":"各类群封闭自身的方式不同，因此这个名词常与动物名连用，标出具体模式。"},{"no":"05","title":"The folding of flower parts in a bud","titleCN":"植物学中花被片在花蕾里的排列","definition":"the way sepals and petals are arranged or folded before the flower opens, such as twisted or overlapping","definitionCN":"花萼与花瓣在开花前的排列或折叠方式，如旋转状或覆瓦状","example":"The botanist keyed the species by its twisted floral aestivation.","exampleCN":"植物学家按它旋转状的花被卷叠式来鉴定这个物种。","why":"The same Latin summer word was applied to the summer opening of flowers, and botanists kept it for the pattern seen before opening.","whyCN":"同一个拉丁「夏天」词也被用于花在夏季开放，植物学家沿用它指开花前的排列格局。"},{"no":"06","title":"Summer survival in plants","titleCN":"植物越夏的休眠策略","definition":"the summer rest of bulbs, tubers or seeds that lie below ground until the dry season passes","definitionCN":"球茎、块茎或种子在地下等到旱季过去才恢复的夏季休眠","example":"Bulb aestivation lets the plant skip the driest months entirely.","exampleCN":"球茎的越夏休眠让植株整个跳过最干的几个月。","why":"Where there is no animal to hide, the plant hides its growing point underground, but the seasonal logic is the same.","whyCN":"没有动物可藏身时，植物把生长点藏到地下，但季节逻辑是一样的。"},{"no":"07","title":"Summer diapause in insects","titleCN":"昆虫的越夏滞育","definition":"the arrested development by which an insect passes the hot season, often compared with winter diapause","definitionCN":"昆虫以停止发育来度过炎热季节，常与冬季滞育相比较","example":"Aestivation in the beetle is a true diapause, not merely a slow week.","exampleCN":"这种甲虫的越夏休眠是真正的滞育，而不只是放慢一周。","why":"Insect physiology distinguishes a programmed arrest from simple quiescence, and uses the summer term for the hot-season case.","whyCN":"昆虫生理学区分程序性停滞与单纯静止，并用这个夏季词指炎热季节的情形。"},{"no":"08","title":"A seasonal shutdown of an institution","titleCN":"机构在淡季的停摆（比喻用法）","definition":"a figurative summer pause in which a business, school or project reduces activity to a minimum","definitionCN":"企业、学校或项目把活动降到最低的比喻性夏季暂停","example":"The factory's aestivation lasts through the hottest month, when demand nearly vanishes.","exampleCN":"工厂的夏休贯穿最热的一个月，那时需求几乎消失。","why":"The metaphor keeps only the season and the pause: activity stops, and everyone waits for the weather to change.","whyCN":"这个比喻只保留季节与暂停：活动停下，所有人等待天气转变。"}],"etymology":{"intro":{"en":"Aestivation comes from Latin aestivare 'to spend the summer', built on aestivus 'of summer' and aestas 'summer'. English took the botanical sense first and the zoological sense later.","cn":"aestivation 来自拉丁 aestivare「度夏」，由 aestivus「夏季的」与 aestas「夏天」构成。英语先接受植物学义，后接受动物学义。"},"items":[{"era":"LATIN AESTAS","en":"Aestas was the Latin noun for summer. It is usually derived from a reconstructed Indo-European root meaning 'to burn', a form written with an asterisk because it is rebuilt, not attested.","cn":"aestas 是拉丁语表示「夏天」的名词，一般追溯到原始印欧语中表示「燃烧」的重构词根；该形式带星号，表示是重建而非有文献佐证。"},{"era":"LATIN AESTIVUS","en":"Aestivus meant 'of summer'. English keeps it as aestival, a formal adjective for summer things or summer flowers.","cn":"aestivus 意为「夏季的」。英语保留为 aestival，正式用来形容夏季事物或夏季开花植物。"},{"era":"LATIN AESTIVARE","en":"Aestivare meant 'to spend or pass the summer'. In classical Latin it could describe troops summering in camp, much as hibernare described wintering.","cn":"aestivare 意为「度夏、过夏天」。古典拉丁中可指部队在营地避暑，正与 hibernare 指越冬相平行。"},{"era":"BOTANICAL ENGLISH","en":"The botanical sense for the arrangement of flower parts appears in the seventeenth century; sources differ on the exact first record, so the date is approximate.","cn":"指花各部分排列的植物学义在十七世纪出现；各家记载的确切首见年代有出入，故为约数。"},{"era":"ZOOLOGICAL ENGLISH","en":"The zoological sense of summer torpor spread in the nineteenth century, when naturalists compared it directly with hibernation.","cn":"指夏季昏睡的动物学义在十九世纪传开，当时博物学家直接把它与冬眠作对照。"},{"era":"SPELLING SPLIT","en":"British usage keeps the Latin digraph in aestivation; American usage simplifies it to estivation. Both spellings name the same state.","cn":"英式保留拉丁二合字母写作 aestivation；美式简化为 estivation。两种拼写指同一状态。"}]},"similar":{"note":{"en":"Group one holds spelling variants and family forms that are often confused; group two holds other words for a life put on hold.","cn":"第一组是常被混淆的拼写变体与同族形式；第二组是其他表示生命暂停的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"estivation","ipa":"/ˌiːstɪˈveɪʃn/","tag":"American spelling","definition":"The same word with the Latin digraph simplified; it is a spelling difference, not a different phenomenon.","definitionCN":"同一个词简化了拉丁二合字母；只是拼写差异，不是不同现象。"},{"word":"aestival","ipa":"/iːˈstiːvl/","tag":"same root, season adjective","definition":"An adjective meaning 'of summer', from aestivus; it describes the season, not the dormancy.","definitionCN":"由 aestivus 来的「夏季的」形容词，描述季节，而非休眠。"},{"word":"aestivate","ipa":"/ˈiːstɪveɪt/","tag":"same root, the verb","definition":"The verb behind the noun; it names the act of passing the hot season in dormancy.","definitionCN":"名词背后的动词，指以休眠度过炎热季节的动作。"},{"word":"aestivating","ipa":"/ˈiːstɪveɪtɪŋ/","tag":"same root, participle","definition":"A participial adjective for an organism currently in summer dormancy, parallel to hibernating.","definitionCN":"分词形容词，指正处夏眠中的生物，与 hibernating 平行。"}]},{"heading":"NEAR MEANING","entries":[{"word":"hibernation","ipa":"/ˌhaɪbəˈneɪʃn/","tag":"winter counterpart","definition":"The cold-season equivalent; the two words name mirror-image dormancies, one for heat and one for cold.","definitionCN":"寒冷季节的对应词；两词指镜像般的休眠，一个对炎热，一个对寒冷。"},{"word":"dormancy","ipa":"/ˈdɔːmənsi/","tag":"general term","definition":"The broad category of suspended growth or activity; aestivation is the summer-specific member of that category.","definitionCN":"生长或活动暂停的广义类别；夏眠是该类别中专属于夏季的成员。"},{"word":"diapause","ipa":"/daɪˈpɔːz/","tag":"programmed arrest","definition":"A genetically timed pause in insect development, triggered by day length or temperature; it can occur in summer or winter.","definitionCN":"昆虫发育中由基因定时、受日照或温度触发的暂停，可发生在夏季或冬季。"},{"word":"quiescence","ipa":"/kwiˈesns/","tag":"passive slowdown","definition":"A simple slowing caused directly by harsh conditions, with no internal programme; the organism resumes as soon as conditions improve.","definitionCN":"由恶劣条件直接引起的简单放慢，没有内部程序；条件一好就恢复。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin aestas 'summer' gives aestivare 'to summer', so aestivation is summer turned into a sleep.","cn":"拉丁 aestas「夏天」生出 aestivare「度夏」，所以 aestivation 是把夏天变成一场睡眠。"},{"en":"The family runs aestivate, aestivation, aestival, aestivating, and the American estivation.","cn":"同族词包括 aestivate、aestivation、aestival、aestivating，以及美式拼写 estivation。"},{"en":"Fixed phrases mark the state: enter aestivation, aestivation period, arouse from aestivation.","cn":"固定搭配标出状态：进入夏眠、夏眠期、从夏眠中苏醒。"},{"en":"Botany uses the same noun for the way petals are folded in a bud, a summer opening seen in miniature.","cn":"植物学用同一个名词指花瓣在花蕾中的折叠方式，像把夏季开放缩到极小。"},{"en":"Aestivation pairs with hibernation: one escapes heat, the other escapes cold.","cn":"aestivation 与 hibernation 成对：一个躲热，一个躲冷。"}],"abstract":[{"en":"Picture a snail sealing its door with glue and sleeping until the rain knocks.","cn":"想象一只蜗牛用胶把门封住，一直睡到雨来敲门。"},{"en":"Picture a flower holding its petals folded like hands in prayer until the sun opens them.","cn":"想象一朵花把花瓣合得像祈祷的手，等太阳把它们打开。"},{"en":"Picture a whole town closing its shutters at noon and opening them at dusk.","cn":"想象整座小镇正午关上窗板，黄昏才重新打开。"}]},"examples":[{"en":"Snails enter aestivation when the pond dries and the mud hardens.","cn":"池塘干涸、泥巴变硬时，蜗牛进入夏眠。"},{"en":"Aestivation relies on a mucus seal that cuts water loss almost to zero.","cn":"夏眠依靠黏液封口，把失水几乎降到零。"},{"en":"The botanist keyed the species by its twisted floral aestivation.","cn":"植物学家按它旋转状的花被卷叠式来鉴定这个物种。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「爱死它，为神」——天太热，只好封上门去避暑 → 夏眠","word":"aestivation"},"root":"拉丁 aestivare「度夏」，由 aestivus「夏季的」构成，源于 aestas「夏天」；更早一般追溯到原始印欧语表示「燃烧」的重构词根（星号形式为重构），确切音形存疑。英语 aestivation（美式 estivation）。","sensesIntro":{"en":"Eight senses follow one gesture: a living thing closes itself against the hot season and waits. The gesture runs from animals to plants, to insects, to flower buds, and finally to institutions.","cn":"八个义项沿同一个动作展开：生物把自己封闭起来对抗炎热季节，然后等待。这个动作从动物到植物、到昆虫、到花蕾，最后到机构。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed shell in cracked mud, waiting for rain.","cn":"核心意象：龟裂泥土里一只封了口的壳，等待雨水。"},"chain":["SUMMER","DRYNESS","SEAL","LOW METABOLISM","WAIT","REOPEN"],"branches":[{"senses":"S1 · S3","en":"THE SUMMER STATE: heat and drought are met by a water-tight seal and a slowed body.","cn":"夏季状态：用不透水的封口与放慢的身体来应对炎热和干旱。"},{"senses":"S2 · S4","en":"TIME AND GROUP: the noun measures the wait and marks how a particular animal performs it.","cn":"时间与类群：这个名词计量等待的长度，并标出某类动物的具体做法。"},{"senses":"S5","en":"FOLDED PETALS: botany keeps the summer word for the pattern packed inside a bud.","cn":"折叠的花瓣：植物学把这个夏季词保留给花蕾内部打包的排列方式。"},{"senses":"S6 · S7","en":"PLANT AND INSECT: bulbs hide underground and insects stop development, both repeating the same seasonal logic.","cn":"植物与昆虫：球茎藏到地下，昆虫停止发育，两者重复同一季节逻辑。"},{"senses":"S8","en":"INSTITUTIONAL SHUTDOWN: a business copies the shutters and waits out the slow month.","cn":"机构停摆：企业复制「关窗板」的动作，熬过淡月。"}]},"affixes":{"intro":{"en":"Aestivation is a Latin summer root plus an action noun suffix, and the same root supplies the season adjective and the verb.","cn":"aestivation 是一个拉丁「夏天」词根加动作名词后缀，同一词根还提供季节形容词与动词。"},"latinIntro":{"en":"Latin aestas 'summer' gives aestivus 'of summer' and aestivare 'to summer'; -atio supplies the state noun. English also keeps the simplified American spelling estivation.","cn":"拉丁 aestas「夏天」生出 aestivus「夏季的」与 aestivare「度夏」；-atio 提供状态名词。英语另有简化的美式拼写 estivation。"},"items":[{"word":"aestas","structure":"aestas, aestatis (Latin noun, third declension)","meaning":"summer","meaningCN":"夏天","example":"Aestas longa et sicca erat.","exampleCN":"那个夏天又长又干。"},{"word":"aestivus","structure":"aestas + -ivus (adjective)","meaning":"of summer","meaningCN":"夏季的","example":"Aestiva flumina siccantur.","exampleCN":"夏季的河流会干涸。"},{"word":"aestivare","structure":"aestivus + -are (verb)","meaning":"to pass the summer","meaningCN":"度夏","example":"Milites aestivaverunt in castris.","exampleCN":"士兵们在营地度夏。"},{"word":"aestivate","structure":"aestivare + English verb ending","meaning":"to pass the hot season dormant","meaningCN":"以休眠度过炎热季节","example":"The snails aestivate under the dry bank.","exampleCN":"蜗牛在干岸下夏眠。"},{"word":"aestivation","structure":"aestivate + -ation (state noun)","meaning":"summer dormancy","meaningCN":"夏季休眠","example":"Aestivation protects the animal from heat.","exampleCN":"夏眠保护动物免受炎热。"},{"word":"estivation","structure":"aestivation with the digraph simplified","meaning":"the American spelling of the same word","meaningCN":"同一词的美式拼写","example":"American textbooks print estivation.","exampleCN":"美国教科书印作 estivation。"},{"word":"aestival","structure":"aestivus + -al (adjective)","meaning":"belonging to summer","meaningCN":"属于夏天的","example":"Aestival rains woke the bulbs.","exampleCN":"夏雨唤醒了球茎。"},{"word":"aestivating","structure":"aestivate + -ing (participle)","meaning":"in summer dormancy","meaningCN":"夏眠中的","example":"An aestivating snail can lose half its water.","exampleCN":"夏眠中的蜗牛可以失去一半的水分。"},{"word":"aestivator","structure":"aestivate + -or (agent, rare)","meaning":"an organism that aestivates","meaningCN":"进行夏眠的生物（较少用）","example":"The mudfish is a well-known aestivator.","exampleCN":"泥鳅是著名的夏眠动物。"}],"latinEntries":[{"word":"aestas","structure":"aestas, aestatis (f., third declension)","meaning":"summer","meaningCN":"夏天"},{"word":"aestivus","structure":"aestivus, aestiva, aestivum (adjective)","meaning":"of summer","meaningCN":"夏季的"},{"word":"aestivare","structure":"aestivare, aestivavi, aestivatum (verb, first conjugation)","meaning":"to pass the summer","meaningCN":"度夏；过夏天"}]}},{"word":"dormancy","ipa_uk":"/ˈdɔːmənsi/","ipa_us":"/ˈdɔːrmənsi/","definition_zh":"休眠；休眠状态；（行业等的）停滞期","definition_en":"a temporary state in which growth, development or activity almost stops and resumes when conditions improve","core_image":"一只上了锁的抽屉里放着一粒种子和一只芽，抽屉外的季节轮转，抽屉里一切暂停","scene":"干土里，一粒种子把外壳收紧，内部的代谢慢到几乎测不出，等到雨水渗下来才重新吸水。Deep dormancy keeps the seeds viable for years in dry soil.","sceneCN":"这里 dormancy 指「生长与代谢近乎停止、条件改善后可恢复的状态」（第 1 个义项：生物休眠状态）；句意为深度休眠使这些种子在干燥土壤中多年仍有活力。图中可辨识物件：土粒、种皮、滴落的水、细小的胚根。","pos":[{"tag":"n.","zh":"休眠；休眠状态（不可数；指具体的休眠期或类型时可数，复数 dormancies）"}],"collocations":[{"phrase":"seed dormancy","zh":"种子休眠"},{"phrase":"break dormancy","zh":"打破休眠"},{"phrase":"deep dormancy","zh":"深度休眠"},{"phrase":"dormancy period","zh":"休眠期"},{"phrase":"bud dormancy","zh":"芽休眠"},{"phrase":"dormancy release","zh":"休眠解除"}],"forms":[{"label":"复数","form":"dormancies"},{"label":"形容词（休眠的）","form":"dormant"},{"label":"副词（休眠地，较少用）","form":"dormantly"},{"label":"相关名词（宿舍）","form":"dormitory"},{"label":"相关名词（屋顶窗）","form":"dormer"},{"label":"相关名词（安息）","form":"dormition"}],"derivatives":[{"word":"dormant","pos":"adj.","zh":"dormant（基础形容词；dormancy 由 dormant + -cy 状态名词后缀构成）→ 处于休眠或不活动状态的"},{"word":"dormition","pos":"n.","zh":"dormitio（拉丁「入睡」）+ -ion（动作名词后缀）→ 安息；被称为安眠的死亡"},{"word":"dormitive","pos":"adj./n.","zh":"dormire + -ive（形容词后缀）→ 使人入睡的（尤指旧时药名）"},{"word":"dormitory","pos":"n.","zh":"dormitorium（拉丁「寝室」）+ -y → 集体宿舍"},{"word":"dormer","pos":"n.","zh":"古法语 dormeor「寝室」→ 屋顶上凸出的采光窗"}],"senses":[{"no":"01","title":"Suspended growth or activity","titleCN":"生长与活动近乎停止的状态","definition":"a temporary condition in which an organism's growth or metabolism slows almost to a stop and later resumes","definitionCN":"生物的生长或代谢几乎停止、之后又能恢复的暂时状态","example":"Deep dormancy keeps the seeds viable for years in dry soil.","exampleCN":"深度休眠使这些种子在干燥土壤中多年仍有活力。","why":"Latin dormire meant 'to sleep', so dormancy is the noun of a sleeping body, applied to seeds and spores that show no movement.","whyCN":"拉丁 dormire 意为「睡」，因此 dormancy 是「睡着的身体」的名词，用于看不出动静的种子与孢子。"},{"no":"02","title":"The period of suspended life","titleCN":"生命暂停的那段时间","definition":"the interval between entering dormancy and the trigger that ends it","definitionCN":"从进入休眠到触发其结束之间的间隔","example":"The dormancy of these acorns lasts until the first wet autumn.","exampleCN":"这些橡子的休眠持续到第一个多雨的秋天。","why":"The noun can measure time as well as name a state, because dormancy is defined by its duration.","whyCN":"这个名词既能量时间也能命名状态，因为休眠正是由持续时长来界定的。"},{"no":"03","title":"Seed dormancy","titleCN":"种子休眠","definition":"the condition in which a ripe seed will not germinate even with water and warmth until cold, light or time breaks the block","definitionCN":"成熟的种子即使有水有温度也不萌发，须经低温、光照或时间才解除阻断的状态","example":"Seed dormancy spreads germination across several seasons instead of one week.","exampleCN":"种子休眠把萌发分散到几个季节，而不是挤在一周内。","why":"A seed that waited for the right season would die in a false spring, so the block is a safety device.","whyCN":"若种子在假春天萌发就会死去，因此这道阻断是一重保险。"},{"no":"04","title":"Bud and tuber dormancy","titleCN":"芽与块茎的休眠","definition":"the winter or storage rest in which buds, tubers and bulbs will not sprout until chilling or warmth releases them","definitionCN":"芽、块茎与球茎在冬季或储藏期不发芽，直到低温或回暖解除的状态","example":"Potato dormancy is broken by storing the tubers in cool, bright conditions.","exampleCN":"把块茎放在凉爽明亮的环境中即可打破马铃薯的休眠。","why":"Here the sleeper is a bud rather than a whole plant, but the same rule holds: no growth until the signal arrives.","whyCN":"这里睡着的是芽而非整株植物，但规则相同：信号不到就不生长。"},{"no":"05","title":"Bacterial and spore dormancy","titleCN":"细菌与孢子的休眠","definition":"the extremely low-activity state of spores and dormant bacteria, which can revive after long storage","definitionCN":"孢子与休眠细菌活动极低、经长期存放仍可复苏的状态","example":"Spore dormancy can outlast the laboratory that first described it.","exampleCN":"孢子的休眠可以比最初描述它的实验室活得更久。","why":"At this scale dormancy means a toughened coat and a nearly stopped metabolism, not sleep in any animal sense.","whyCN":"在这个尺度上，休眠意味着坚硬的外壳与几乎停摆的代谢，而不是动物意义上的睡眠。"},{"no":"06","title":"Latency of a virus","titleCN":"病毒的潜伏","definition":"the quiet phase in which a virus stays inside a cell without producing new particles or symptoms","definitionCN":"病毒留在细胞内、不产生新颗粒也不引起症状的安静阶段","example":"Viral dormancy keeps the infection hidden for years.","exampleCN":"病毒的潜伏让感染隐藏多年。","why":"Medicine borrowed the seed image: the agent is present but not growing, and can wake when conditions change.","whyCN":"医学借用了种子的意象：病原在场却不生长，条件一变就可能醒来。"},{"no":"07","title":"A quiet stretch in a market or field","titleCN":"市场或行业的沉寂期","definition":"a figurative period in which an industry, market or project shows almost no activity but is not finished","definitionCN":"行业、市场或项目几乎无活动、却并未终结的比喻性时期","example":"The dormancy of the housing market ended with a single cut in interest rates.","exampleCN":"房地产市场的一段沉寂，因一次降息而结束。","why":"The metaphor drops the biology and keeps the shape: low activity, preserved capacity, later revival.","whyCN":"这个比喻舍弃生物学内容，只保留外形：低活动、保有能力、日后复苏。"},{"no":"08","title":"The depth of the resting state","titleCN":"休眠的深度（深浅程度）","definition":"the degree to which a resting organism resists waking, measured by how hard the block is to break","definitionCN":"休眠中的生物抗拒苏醒的程度，以阻断有多难打破来衡量","example":"Biologists rate dormancy by the chilling hours needed to release it.","exampleCN":"生物学家按解除休眠所需的低温小时数来划分休眠深度。","why":"Once dormancy can be measured, it acquires a scale, and the noun comes to name a point on that scale.","whyCN":"一旦休眠可以被测量，它就有了刻度，这个名词也就用来指刻度上的某一点。"}],"etymology":{"intro":{"en":"Dormancy is an eighteenth-century English noun from dormant, which descends through French from Latin dormire 'to sleep'. The Latin verb is the source of a whole family of sleeping words.","cn":"dormancy 是十八世纪英语名词，来自 dormant，后者经法语源自拉丁 dormire「睡」。这个拉丁动词是一整族「睡眠」词的源头。"},"items":[{"era":"LATIN DORMIRE","en":"Dormire meant 'to sleep'. Its deeper origin is usually traced to a reconstructed Indo-European root for sleep, marked with an asterisk because it is rebuilt rather than recorded.","cn":"dormire 意为「睡」。其更早来源一般追溯到原始印欧语中表示睡眠的重构词根；因是重建而非有记录，故带星号。"},{"era":"LATIN DORMITORIUM","en":"A dormitorium was a sleeping room. English dormitory descends from it, which is why the word for a hall of beds and the word for a sleeping seed look related.","cn":"dormitorium 是「寝室」。英语 dormitory 由此而来，所以「宿舍」与「休眠的种子」看起来沾亲。"},{"era":"OLD FRENCH DORMANT","en":"Old French used dormant, the present participle of dormir, for 'sleeping'. English borrowed the adjective in the thirteenth century.","cn":"古法语用 dormir 的现在分词 dormant 表示「睡着的」。英语在十三世纪借入这个形容词。"},{"era":"EIGHTEENTH-CENTURY NOUN","en":"The abstract noun dormancy is recorded in the eighteenth century, formed with -cy on the model of other state nouns. The exact first date is uncertain.","cn":"抽象名词 dormancy 见于十八世纪，依照其他状态名词的模式加 -cy 构成。确切首见年代不确定。"},{"era":"BOTANICAL USE","en":"Botany gave the word its modern precision by distinguishing true dormancy, which is internally controlled, from quiescence, which is forced by conditions.","cn":"植物学赋予这个词现代意义上的精确性：真正的休眠由内部控制，而静止状态由外部条件迫使。"},{"era":"EXTENDED USES","en":"Twentieth-century writing extended dormancy to viruses, markets and institutions, always keeping the promise of a later waking.","cn":"二十世纪的写作把 dormancy 扩展到病毒、市场与机构，始终保留「日后会醒来」的许诺。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin sleeping root that are easily confused; group two holds rival terms for a life on hold.","cn":"第一组是同出拉丁「睡」词根、容易混淆的词；第二组是表示生命暂停的竞争性术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dormant","ipa":"/ˈdɔːmənt/","tag":"same root, adjective","definition":"The adjective describing the state; dormancy is the noun, so one says seeds are dormant but seeds show dormancy.","definitionCN":"描述该状态的形容词；dormancy 是名词，因此说种子处于休眠，而不说种子表现出休眠。"},{"word":"dormitory","ipa":"/ˈdɔːmətri/","tag":"same root, a building","definition":"From Latin dormitorium 'sleeping room'; it names a place for sleeping, not a biological pause.","definitionCN":"来自拉丁 dormitorium「寝室」，指睡觉的场所，不是生物性暂停。"},{"word":"dormer","ipa":"/ˈdɔːmə/","tag":"same root, a window","definition":"From Old French dormeor 'sleeping room', applied to the roof window that lights such a room.","definitionCN":"来自古法语 dormeor「寝室」，用来指给该房间采光的屋顶窗。"},{"word":"dormition","ipa":"/dɔːˈmɪʃn/","tag":"same root, a death","definition":"From Latin dormitio 'a sleeping', used in theology for a death described as falling asleep.","definitionCN":"来自拉丁 dormitio「入睡」，神学中用来指被称为「睡着」的死亡。"}]},{"heading":"NEAR MEANING","entries":[{"word":"quiescence","ipa":"/kwiˈesns/","tag":"forced rest","definition":"A slowdown caused directly by external conditions, with no internal clock; the organism resumes the moment conditions improve.","definitionCN":"由外部条件直接造成的放慢，没有内部时钟；条件一好就立刻恢复。"},{"word":"hibernation","ipa":"/ˌhaɪbəˈneɪʃn/","tag":"winter form","definition":"A deep seasonal dormancy of winter; dormancy is the wider category that contains it.","definitionCN":"冬季的深度季节性休眠；dormancy 是包含它的更大类别。"},{"word":"latency","ipa":"/ˈleɪtənsi/","tag":"hidden presence","definition":"The state of being present but not expressed, common for viruses and diseases; it stresses concealment rather than slowed growth.","definitionCN":"存在却不表现的状态，常用于病毒与疾病；强调隐藏而非生长减慢。"},{"word":"stasis","ipa":"/ˈsteɪsɪs/","tag":"no change at all","definition":"A general halt in change or flow, from Greek stasis 'standing'; it need not imply a living thing that can wake.","definitionCN":"变化或流动的总体停止，来自希腊 stasis「站立」；不必然暗示能醒来的活物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Dormire is 'to sleep', so dormancy is the noun of sleep: a sleeping that a seed or spore can perform.","cn":"dormire 是「睡」，所以 dormancy 是「睡」的名词：种子或孢子也能进行的一种睡。"},{"en":"The family runs dormant, dormancy, dormitory, dormer, dormition, dormitive.","cn":"同族词包括 dormant、dormancy、dormitory、dormer、dormition、dormitive。"},{"en":"Fixed phrases mark the biology: seed dormancy, break dormancy, deep dormancy, bud dormancy.","cn":"固定搭配标出生物学用法：种子休眠、打破休眠、深度休眠、芽休眠。"},{"en":"Dormancy is internally controlled; quiescence is forced from outside, a distinction worth memorising as a pair.","cn":"休眠由内部调控，静止由外部迫使；这对区别值得成对记住。"},{"en":"The same root shows up in dormitory: a room for sleep, a seed for sleeping.","cn":"同一词根出现在 dormitory：一间用来睡的房间，一粒用来睡的种子。"}],"abstract":[{"en":"Picture a clock with its pendulum lifted and held, not removed.","cn":"想象一只钟的摆锤被抬起按住，而不是被拆掉。"},{"en":"Picture a letter sealed and put away, still readable when opened.","cn":"想象一封信被密封收起，打开时仍可读。"},{"en":"Picture a shop with the lights off but the stock still on the shelves.","cn":"想象一家关了灯的店，货架上的存货仍在。"}]},"examples":[{"en":"Deep dormancy keeps the seeds viable for years in dry soil.","cn":"深度休眠使这些种子在干燥土壤中多年仍有活力。"},{"en":"Seed dormancy spreads germination across several seasons instead of one week.","cn":"种子休眠把萌发分散到几个季节，而不是挤在一周内。"},{"en":"Viral dormancy keeps the infection hidden for years.","cn":"病毒的潜伏让感染隐藏多年。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「多梦」——睡得多、梦得多，生长也停了 → 休眠","word":"dormancy"},"root":"拉丁 dormire「睡」+ 名词后缀 -ncy（经由 dormant 构成抽象状态名词）；dormire 更早一般追溯到原始印欧语表示睡眠的重构词根（星号形式为重构），确切音形存疑。英语 dormancy。","sensesIntro":{"en":"Eight senses follow one gesture: life is put on hold without being ended. The gesture begins with seeds and buds, widens to spores and viruses, then to markets, and finally becomes a measurable depth.","cn":"八个义项沿同一个动作展开：把生命挂起，却不终结它。这个动作从种子与芽开始，扩到孢子与病毒，再到市场，最后成为一种可测量的深度。"},"semanticMap":{"core":{"en":"CORE IMAGE: a locked drawer holding a seed and a bud while the seasons turn outside.","cn":"核心意象：一只上锁的抽屉里放着种子与芽，抽屉外季节轮转。"},"chain":["LIFE PRESENT","GROWTH STOPPED","HARD COAT","LOW METABOLISM","WAITING","TRIGGER"],"branches":[{"senses":"S1 · S2","en":"THE GENERAL PAUSE: life continues without growth, and the noun also measures how long the pause lasts.","cn":"总体暂停：生命继续却不生长，名词还计量暂停持续多久。"},{"senses":"S3 · S4","en":"SEEDS AND BUDS: the coat or the chilling requirement decides when growth may restart.","cn":"种子与芽：种皮或需冷量决定生长何时可以重启。"},{"senses":"S5 · S6","en":"SMALL AND HIDDEN: spores toughen and viruses go quiet, both present but not multiplying.","cn":"微小而隐蔽：孢子变硬、病毒转静，都在场却不增殖。"},{"senses":"S7","en":"MARKET QUIET: an industry borrows the pause and waits for demand to return.","cn":"市场沉寂：行业借用这个暂停，等待需求回来。"},{"senses":"S8","en":"MEASURED DEPTH: once the block can be timed, dormancy becomes a quantity.","cn":"可测的深度：一旦阻断可以被计时，休眠就成为一个量。"}]},"affixes":{"intro":{"en":"Dormancy is built on a Latin verb of sleeping; the same root reappears in rooms and windows, which makes the family unusually easy to read.","cn":"dormancy 建立在一个表示「睡」的拉丁动词上；同一词根还出现在房间与窗户里，使这个词族格外容易读。"},"latinIntro":{"en":"Latin dormire 'to sleep' gives dormitorium 'sleeping room', dormitio 'a sleeping' and the adjective dormitivus; the English abstract noun adds -cy to dormant.","cn":"拉丁 dormire「睡」生出 dormitorium「寝室」、dormitio「入睡」与形容词 dormitivus；英语抽象名词则在 dormant 后加 -cy。"},"items":[{"word":"dormire","structure":"dormire, dormivi, dormitum (Latin verb, fourth conjugation)","meaning":"to sleep","meaningCN":"睡","example":"Dormire non potest.","exampleCN":"他睡不着。"},{"word":"dormant","structure":"dormire + -ant (present participle)","meaning":"sleeping, inactive","meaningCN":"睡着的；不活动的","example":"The volcano is dormant but not extinct.","exampleCN":"这座火山休眠，但并未熄灭。"},{"word":"dormancy","structure":"dormant + -cy (state noun)","meaning":"the state of being dormant","meaningCN":"休眠状态","example":"Dormancy protects the seed through winter.","exampleCN":"休眠保护种子度过冬天。"},{"word":"dormitory","structure":"dormitorium + -y (English noun)","meaning":"a building or room for sleeping","meaningCN":"宿舍；寝室","example":"The students returned to the dormitory at ten.","exampleCN":"学生十点回到宿舍。"},{"word":"dormer","structure":"Old French dormeor 'sleeping room'","meaning":"a roof window","meaningCN":"屋顶天窗","example":"Light came through the dormer.","exampleCN":"光从屋顶天窗照进来。"},{"word":"dormition","structure":"dormitio + -ion (action noun)","meaning":"a falling asleep; a death so described","meaningCN":"入睡；被称为安息的死亡","example":"The feast commemorates her dormition.","exampleCN":"这个节庆纪念她的安息。"},{"word":"dormitive","structure":"dormire + -ive (adjective)","meaning":"causing sleep","meaningCN":"使人入睡的","example":"Old pharmacopoeias listed dormitive syrups.","exampleCN":"旧药典列有助眠糖浆。"},{"word":"semi-dormancy","structure":"semi- (half) + dormancy","meaning":"a partial rest that can still be broken easily","meaningCN":"半休眠，仍容易被打破","example":"Semi-dormancy lets the buds respond to a warm spell.","exampleCN":"半休眠让芽能对一段暖期作出反应。"},{"word":"dormantly","structure":"dormant + -ly (adverb, rare)","meaning":"in a dormant manner","meaningCN":"以休眠的方式（较少用）","example":"The tubers lay dormantly under the soil.","exampleCN":"块茎以休眠状态躺在土下。"}],"latinEntries":[{"word":"dormire","structure":"dormire, dormivi, dormitum (verb, fourth conjugation)","meaning":"to sleep","meaningCN":"睡"},{"word":"dormitorium","structure":"dormitorium, dormitorii (n., second declension)","meaning":"sleeping room","meaningCN":"寝室"},{"word":"dormitio","structure":"dormitio, dormitionis (f., third declension)","meaning":"a sleeping","meaningCN":"入睡；安眠"}]}},{"word":"dormant","ipa_uk":"/ˈdɔːmənt/","ipa_us":"/ˈdɔːrmənt/","definition_zh":"休眠的；蛰伏的；潜伏的；闲置的","definition_en":"in a state in which growth or activity is temporarily stopped while life or capacity remains","core_image":"一截埋在土里的枝条看上去像枯木，刮开表皮，里面仍是青色","scene":"天冷以后，院子角落的球茎一直不出芽，直到春天温度回升。The bulbs stay dormant in the cold frame until spring warmth returns.","sceneCN":"这里 dormant 指「生长暂停、但仍存活并可恢复的」（第 1 个义项：植物休眠的）；句意为球茎在冷床里保持休眠，直到春天回暖。图中可辨识物件：冷床玻璃、覆土的球茎、枯叶、温度计。","pos":[{"tag":"adj.","zh":"休眠的；蛰伏的；潜伏的；闲置的（作定语或表语）"}],"collocations":[{"phrase":"lie dormant","zh":"处于休眠状态"},{"phrase":"dormant volcano","zh":"休眠火山"},{"phrase":"dormant account","zh":"休眠账户"},{"phrase":"dormant seed","zh":"休眠种子"},{"phrase":"dormant period","zh":"休眠期"},{"phrase":"remain dormant","zh":"保持休眠"}],"forms":[{"label":"比较级（较少用）","form":"more dormant"},{"label":"最高级（较少用）","form":"most dormant"},{"label":"副词（休眠地，较少用）","form":"dormantly"},{"label":"名词（休眠）","form":"dormancy"},{"label":"名词（安息；入睡）","form":"dormition"}],"derivatives":[{"word":"dormancy","pos":"n.","zh":"dormant + -cy（状态名词后缀）→ 休眠这一状态"},{"word":"dormitive","pos":"adj./n.","zh":"dormire（拉丁「睡」）+ -ive → 使人入睡的（旧时药名）"},{"word":"dormitory","pos":"n.","zh":"dormitorium（拉丁「寝室」）+ -y → 集体宿舍"},{"word":"dormer","pos":"n.","zh":"古法语 dormeor「寝室」→ 屋顶采光窗"},{"word":"dormition","pos":"n.","zh":"dormitio（拉丁「入睡」）+ -ion → 安息；被称为安眠的死亡"}],"senses":[{"no":"01","title":"Resting but alive in a plant","titleCN":"植物休眠但仍存活","definition":"describing a seed, bulb or bud that shows no growth yet remains alive until conditions change","definitionCN":"形容种子、球茎或芽暂不生长，却仍然存活，直到条件改变","example":"The bulbs stay dormant in the cold frame until spring warmth returns.","exampleCN":"球茎在冷床里保持休眠，直到春天回暖。","why":"Latin dormire 'to sleep' gives the adjective its picture: alive, unmoving, and able to wake.","whyCN":"拉丁 dormire「睡」给这个形容词一幅图：活着、不动、能醒。"},{"no":"02","title":"In winter torpor, of an animal","titleCN":"动物处于越冬昏睡","definition":"describing an animal whose body temperature and activity have dropped for the cold season","definitionCN":"形容动物在寒冷季节体温与活动都已下降","example":"The frogs lie dormant under the frozen mud for months.","exampleCN":"这些蛙在冻泥下休眠数月。","why":"The adjective does not name the season itself, so it can describe any animal rest, not only winter sleep.","whyCN":"这个形容词不命名季节本身，因此可描述任何动物休息，不限于冬眠。"},{"no":"03","title":"Hidden and not multiplying, of a virus","titleCN":"病毒潜伏、不增殖","definition":"describing a virus or infection that is present in the body without producing symptoms","definitionCN":"形容病毒或感染存在于体内却不产生症状","example":"The virus can remain dormant in nerve cells for decades.","exampleCN":"这种病毒能在神经细胞中潜伏数十年。","why":"Latency is the medical version of the same image: something is there, quiet, and possibly able to wake.","whyCN":"潜伏是同一意象的医学版本：某物在场、安静，且可能醒来。"},{"no":"04","title":"A volcano that is quiet but not extinct","titleCN":"休眠火山（安静但未熄灭）","definition":"describing a volcano that has not erupted for a long time but still has a magma supply","definitionCN":"形容长期未喷发、却仍有岩浆供给的火山","example":"The dormant volcano supports farms on its fertile lower slopes.","exampleCN":"这座休眠火山肥沃的低坡上种着庄稼。","why":"Geology borrows the biological word because the mountain is not dead, only asleep between eruptions.","whyCN":"地质学借用这个生物词，因为山并未死，只是在两次喷发之间睡着。"},{"no":"05","title":"An account or device left unused","titleCN":"账户或设备闲置未用","definition":"describing an account, service or machine that is still valid but has been unused for a long time","definitionCN":"形容账户、服务或机器仍然有效，却长期无人使用","example":"The bank closed the dormant account after five years without a transaction.","exampleCN":"五年没有交易后，银行关闭了这个休眠账户。","why":"Nothing has died: the account still exists, it simply has no activity, exactly like a sleeping body.","whyCN":"并没有东西死去：账户仍然存在，只是没有活动，正像睡着的身体。"},{"no":"06","title":"An economy or market that is not moving","titleCN":"经济或市场不活跃","definition":"describing trade, hiring or construction that has slowed almost to a stop but has not collapsed","definitionCN":"形容贸易、招聘或建设几乎停住却并未崩盘","example":"Construction stayed dormant until the new loan scheme began.","exampleCN":"在新贷款方案启动前，建筑业一直停滞。","why":"The metaphor keeps the contrast between alive and active: the sector is alive, but not moving.","whyCN":"这个比喻保留了「活着」与「活动」的对照：行业活着，却不动。"},{"no":"07","title":"Present but not yet expressed","titleCN":"潜在而未表现出来","definition":"describing a capacity, feeling or talent that exists but has not yet shown itself","definitionCN":"形容某种能力、情感或才华存在却尚未显露","example":"A dormant talent for languages woke when she moved abroad.","exampleCN":"她移居国外后，潜伏的语言才能被唤醒。","why":"The abstract use treats an ability as a seed: it is fully there, waiting for the right condition.","whyCN":"抽象用法把能力当作种子：它完整地在，只等合适的条件。"},{"no":"08","title":"A right or clause not currently enforced","titleCN":"权利或条款暂不执行","definition":"describing a legal right or provision that exists but is not being applied at present","definitionCN":"形容某项法律权利或条款存在，但目前未被施行","example":"The lease keeps a dormant clause that can be revived by written notice.","exampleCN":"这份租约保留一条休眠条款，可经书面通知恢复效力。","why":"Law needs a word for a right that sleeps without dying, and the biological adjective supplies it.","whyCN":"法律需要一个词来形容「睡着却没死」的权利，这个生物形容词正好合用。"}],"etymology":{"intro":{"en":"Dormant comes through Old French dormant, the present participle of dormir, from Latin dormire 'to sleep'. English borrowed it in the thirteenth century, first for sleeping people and later for sleeping nature.","cn":"dormant 经古法语 dormant（dormir 的现在分词）来自拉丁 dormire「睡」。英语在十三世纪借入，先形容睡着的人，后形容沉睡的自然界。"},"items":[{"era":"LATIN DORMIRE","en":"Dormire meant 'to sleep'. Its deeper origin is usually traced to a reconstructed Indo-European root for sleep, a form marked with an asterisk because it is rebuilt rather than attested.","cn":"dormire 意为「睡」。其更早来源一般追溯到原始印欧语中表示睡眠的重构词根；因是重建而非有文献佐证，故带星号。"},{"era":"LATIN DORMITARE","en":"The frequentative dormitare 'to be sleepy, to drowse' also existed; it lies behind words such as dormitive rather than behind dormant itself.","cn":"拉丁还有反复动词 dormitare「困倦、打瞌睡」，它是 dormitive 一类词的来源，而非 dormant 的直接来源。"},{"era":"OLD FRENCH DORMANT","en":"Old French formed the present participle dormant from dormir. English took the whole adjective rather than building it anew.","cn":"古法语由 dormir 构成现在分词 dormant。英语整体借入这个形容词，而不是重新构造。"},{"era":"THIRTEENTH-CENTURY ENGLISH","en":"The first English uses describe sleeping persons or animals; the transferred sense for inactive things appears later.","cn":"英语最早用例描述睡着的人或动物；转指不活动之物的用法出现得更晚。"},{"era":"SCIENTIFIC TRANSFER","en":"Botany and geology extended the word to seeds, buds and volcanoes, where 'asleep' means alive or still capable of acting.","cn":"植物学与地质学把这个词扩展到种子、芽与火山；在这些领域，「睡着」意味着仍活着或仍能发作。"},{"era":"MODERN BUSINESS USE","en":"Banking and commerce added dormant accounts and dormant companies in the nineteenth and twentieth centuries, keeping the same promise of possible revival.","cn":"银行与商业在十九至二十世纪补充了休眠账户、休眠公司等说法，保留同样的「可能复苏」许诺。"}]},"similar":{"note":{"en":"Group one holds members of the Latin sleeping family that differ by suffix; group two holds adjectives for something present but not active.","cn":"第一组是同出拉丁「睡」词族、仅后缀不同的成员；第二组是表示「存在但不活动」的形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"dormancy","ipa":"/ˈdɔːmənsi/","tag":"same root, noun","definition":"The noun of the same state; one says a seed is dormant, or that a seed is in dormancy.","definitionCN":"同一状态的名词；可说种子处于休眠，或说种子处于休眠状态。"},{"word":"dormitory","ipa":"/ˈdɔːmətri/","tag":"same root, building","definition":"From Latin dormitorium 'sleeping room'; it is a place, not a condition.","definitionCN":"来自拉丁 dormitorium「寝室」，是地点而非状态。"},{"word":"dormer","ipa":"/ˈdɔːmə/","tag":"same root, window","definition":"The roof window that lights a sleeping room, from Old French dormeor.","definitionCN":"给寝室采光的屋顶窗，来自古法语 dormeor。"},{"word":"dormition","ipa":"/dɔːˈmɪʃn/","tag":"same root, death","definition":"A theological term for a death described as sleep; the root is the same but the reference is final.","definitionCN":"神学中把死亡说成入睡的术语；词根相同，但所指是终结性的。"}]},{"heading":"NEAR MEANING","entries":[{"word":"latent","ipa":"/ˈleɪtnt/","tag":"hidden, not seasonal","definition":"Present but not yet visible or active, as in latent heat or a latent infection; it has no seasonal rhythm.","definitionCN":"存在却尚未显现或活动，如潜热或潜伏感染；没有季节节律。"},{"word":"inactive","ipa":"/ɪnˈæktɪv/","tag":"plain negation","definition":"Simply not active, with no promise that life or function is preserved; dormant always implies a surviving core.","definitionCN":"只是不活动，不保证生命或功能仍被保存；dormant 总暗示核心仍存活。"},{"word":"quiescent","ipa":"/kwiˈesnt/","tag":"resting under conditions","definition":"Resting because conditions forbid activity, ready to resume at once; dormant often implies an internal brake.","definitionCN":"因条件不允许而休息，条件一好立刻恢复；dormant 常暗示内部制动。"},{"word":"sleeping","ipa":"/ˈsliːpɪŋ/","tag":"everyday word","definition":"The ordinary word for nightly rest; for volcanoes or accounts it is a looser metaphor than dormant.","definitionCN":"日常指夜间休息的词；用于火山或账户时，比喻不如 dormant 严谨。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Dormant is the sleeping adjective: a sleeping seed, a sleeping volcano, a sleeping account.","cn":"dormant 就是「睡着的」形容词：睡着的种子、睡着的火山、睡着的账户。"},{"en":"The family runs dormant, dormancy, dormitory, dormer, dormition, dormitive.","cn":"同族词包括 dormant、dormancy、dormitory、dormer、dormition、dormitive。"},{"en":"Fixed phrases mark the range: lie dormant, dormant volcano, dormant account, dormant seed.","cn":"固定搭配标出范围：处于休眠、休眠火山、休眠账户、休眠种子。"},{"en":"A dormant thing is not dead: that single contrast separates it from extinct or ruined.","cn":"dormant 之物并未死：正是这一点把它与「灭绝」「毁坏」区分开。"},{"en":"The stress is on the first syllable: DOR-mant, like DOR-mant volcano.","cn":"重音在第一音节：DOR-mant，如休眠火山。"}],"abstract":[{"en":"Picture a switch in the off position with the power still connected.","cn":"想象一个处于关闭位置的开关，电源却仍接者。"},{"en":"Picture a bear's slow breath measured against a snowdrift.","cn":"想象熊的缓慢呼吸与雪堆相对照。"},{"en":"Picture a violin kept in its case, tuned and ready.","cn":"想象一把收在琴盒里的提琴，调好了音，随时可拉。"}]},"examples":[{"en":"The bulbs stay dormant in the cold frame until spring warmth returns.","cn":"球茎在冷床里保持休眠，直到春天回暖。"},{"en":"The virus can remain dormant in nerve cells for decades.","cn":"这种病毒能在神经细胞中潜伏数十年。"},{"en":"The bank closed the dormant account after five years without a transaction.","cn":"五年没有交易后，银行关闭了这个休眠账户。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「多梦的」——多梦的人睡得很沉，叫也叫不醒 → 休眠的、蛰伏的","word":"dormant"},"root":"古法语 dormant（dormir 的现在分词）→ 拉丁 dormire「睡」；更早一般追溯到原始印欧语表示睡眠的重构词根（星号形式为重构），确切音形存疑。英语 dormant。","sensesIntro":{"en":"Eight senses follow one contrast: alive but not moving. The adjective starts with plants and animals, moves to viruses and volcanoes, then to accounts, markets, talents and legal clauses.","cn":"八个义项沿同一个对照展开：活着却不动。这个形容词从植物与动物开始，转到病毒与火山，再转到账户、市场、才能与法律条款。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cut stem that looks dead outside but is green under the bark.","cn":"核心意象：一截外表像枯木、刮开树皮却仍是青色的枝条。"},"chain":["ALIVE","NOT GROWING","PROTECTED","WAITING","CAPABLE","WAKING"],"branches":[{"senses":"S1 · S2","en":"LIVING REST: plants and animals keep their core while growth and movement stop.","cn":"活着的休息：植物与动物在生长与活动停止时保住核心。"},{"senses":"S3 · S4","en":"HIDDEN FORCE: a virus waits inside a cell and a volcano waits under a mountain.","cn":"隐藏的力量：病毒在细胞内等待，火山在山体下等待。"},{"senses":"S5 · S6","en":"UNUSED CAPACITY: an account or a market keeps its structure but shows no motion.","cn":"未用的能力：账户或市场保住结构，却不显示运动。"},{"senses":"S7","en":"UNEXPRESSED ABILITY: a talent is fully present before it is ever seen.","cn":"未显露的才能：才华在被看见之前已完整存在。"},{"senses":"S8","en":"SLEEPING RIGHT: a clause stays valid while enforcement waits.","cn":"睡着的权利：条款保持有效，执法暂时等待。"}]},"affixes":{"intro":{"en":"Dormant is a Latin present participle carried into English through French, so its suffix marks an ongoing state rather than an action.","cn":"dormant 是经法语进入英语的拉丁现在分词，因此它的后缀标记的是持续状态，而非动作。"},"latinIntro":{"en":"Latin dormire 'to sleep' builds dormitare 'to drowse', dormitorium 'sleeping room' and dormitio 'a sleeping'; English adds -cy, -y and -ion to make the modern family.","cn":"拉丁 dormire「睡」构成 dormitare「打瞌睡」、dormitorium「寝室」与 dormitio「入睡」；英语再加 -cy、-y、-ion 形成现代词族。"},"items":[{"word":"dormire","structure":"dormire, dormivi, dormitum (Latin verb, fourth conjugation)","meaning":"to sleep","meaningCN":"睡","example":"Dormiunt sub nive.","exampleCN":"它们在雪下睡着。"},{"word":"dormant","structure":"dormire + -ant (present participle)","meaning":"sleeping, inactive","meaningCN":"睡着的；不活动的","example":"The seeds are dormant all winter.","exampleCN":"种子整个冬天都休眠。"},{"word":"dormancy","structure":"dormant + -cy (state)","meaning":"the state of rest","meaningCN":"休眠状态","example":"Cold maintains the dormancy of the bulb.","exampleCN":"低温维持球茎的休眠。"},{"word":"dormitive","structure":"dormire + -ive (adjective)","meaning":"sleep-inducing","meaningCN":"使人入睡的","example":"A dormitive drug was once a common prescription.","exampleCN":"助眠药曾是常见处方。"},{"word":"dormitory","structure":"dormitorium + -y","meaning":"sleeping hall","meaningCN":"宿舍","example":"The dormitory windows face the courtyard.","exampleCN":"宿舍的窗户朝向院子。"},{"word":"dormer","structure":"Old French dormeor","meaning":"roof window","meaningCN":"屋顶窗","example":"A dormer lights the attic room.","exampleCN":"一扇屋顶窗为阁楼房间采光。"},{"word":"dormition","structure":"dormitio + -ion","meaning":"a falling asleep","meaningCN":"入睡；安息","example":"The word appears in liturgical titles.","exampleCN":"这个词出现在礼仪名称中。"},{"word":"semi-dormant","structure":"semi- (half) + dormant","meaning":"only partly asleep","meaningCN":"半休眠的","example":"Semi-dormant buds still respond to warmth.","exampleCN":"半休眠的芽仍会对暖意作出反应。"},{"word":"dormantly","structure":"dormant + -ly (adverb)","meaning":"in a resting manner","meaningCN":"以休眠的方式","example":"The spores waited dormantly in the dust.","exampleCN":"孢子在灰尘中休眠等待。"}],"latinEntries":[{"word":"dormire","structure":"dormire, dormivi, dormitum (verb, fourth conjugation)","meaning":"to sleep","meaningCN":"睡"},{"word":"dormitare","structure":"dormitare, dormitavi, dormitatum (verb, first conjugation)","meaning":"to drowse, be sleepy","meaningCN":"打瞌睡；困倦"},{"word":"dormitorium","structure":"dormitorium, dormitorii (n., second declension)","meaning":"sleeping room","meaningCN":"寝室"}]}},{"word":"seasonal","ipa_uk":"/ˈsiːzənl/","ipa_us":"/ˈsiːzənl/","definition_zh":"季节性的；季节限定的；随季节变化的","definition_en":"happening, appearing or varying at a particular season of the year","core_image":"日历被折成四段，每段只挂一件在该段出现的东西：雨伞、麦穗、落叶、雪铲","scene":"河边的村子靠枣子收获季的短工过日子，其余月份几乎无事可做。Riverside villages depend on seasonal work in the date harvest.","sceneCN":"这里 seasonal 指「只在一年某一季出现或进行的」（第 2 个义项：季节限定的工作）；句意为河边的村子靠枣子收获季的季节性短工维持生计。图中可辨识物件：枣椰树、采果篮、短工的手套、闲置的船。","pos":[{"tag":"adj.","zh":"季节性的；季节限定的；随季节变化的"}],"collocations":[{"phrase":"seasonal work","zh":"季节性工作"},{"phrase":"seasonal variation","zh":"季节性变化"},{"phrase":"seasonal produce","zh":"应季农产品"},{"phrase":"seasonal migration","zh":"季节性迁徙"},{"phrase":"seasonal adjustment","zh":"季节调整"},{"phrase":"seasonal affective disorder","zh":"季节性情感障碍"}],"forms":[{"label":"比较级","form":"more seasonal"},{"label":"最高级","form":"most seasonal"},{"label":"副词（按季节地）","form":"seasonally"},{"label":"名词（季节性）","form":"seasonality"},{"label":"名词（季节）","form":"season"},{"label":"形容词（合时令的）","form":"seasonable"}],"derivatives":[{"word":"seasonally","pos":"adv.","zh":"seasonal + -ly（副词后缀）→ 以随季节的方式"},{"word":"seasonality","pos":"n.","zh":"seasonal + -ity（拉丁 -itas 状态名词后缀）→ 随季节波动的性质"},{"word":"seasonable","pos":"adj.","zh":"season + -able（形容词后缀）→ 合乎时令的（与 seasonal 侧重点不同）"},{"word":"seasoning","pos":"n.","zh":"season（调味义）+ -ing（动名词后缀）→ 调味品；此义与季节义另有来源"},{"word":"off-season","pos":"n./adj.","zh":"off-（离开）+ season → 淡季（的），seasonal 的反向时间带"}],"senses":[{"no":"01","title":"Varying with the time of year","titleCN":"随一年中的时节而变化","definition":"changing in amount or level according to the time of year, as temperature or rainfall does","definitionCN":"数量或水平随一年中的时节改变，如气温或降雨","example":"Seasonal variation in rainfall decides when the river rises.","exampleCN":"降雨的季节性变化决定河水何时上涨。","why":"Season first meant the time for sowing, so anything seasonal is tied to a marked point in the farming year.","whyCN":"season 最初指播种的时节，因此 seasonal 之物都与农事年中某个被标记的时刻相连。"},{"no":"02","title":"Work that lasts only one season","titleCN":"只持续一季的工作","definition":"describing a job, worker or contract that exists only for the busy weeks of a particular season","definitionCN":"形容只存在于某一季繁忙数周内的工作、工人或合同","example":"Riverside villages depend on seasonal work in the date harvest.","exampleCN":"河边的村子靠枣子收获季的季节性短工维持生计。","why":"Harvest arrives and leaves on a calendar, so the labour it needs is hired by the season rather than the year.","whyCN":"收获按日历到来又离开，因此它所需的劳力按季节而非按年雇用。"},{"no":"03","title":"Produce available at its natural time","titleCN":"在自然成熟时节上市的农产品","definition":"describing fruit, vegetables or game that is at its best and most plentiful in a particular part of the year","definitionCN":"形容在一年某一时段最当令、最充足的果蔬或野味","example":"The market sells only seasonal produce, so the menu changes every month.","exampleCN":"这个市场只卖应季农产品，所以菜单每月都变。","why":"Before cold storage and greenhouses, food itself kept the calendar, and the adjective marked that fact.","whyCN":"在冷藏与温室普及之前，食物本身就带着日历，这个形容词标记了这一点。"},{"no":"04","title":"Open or usable only in part of the year","titleCN":"一年中只在一定时段开放或可用的","definition":"describing a road, ferry, park or service that operates only during certain months","definitionCN":"形容只在某些月份运营的道路、渡船、公园或服务","example":"A seasonal ferry links the two villages from May to September.","exampleCN":"一条季节性渡船在五月到九月间连接两个村子。","why":"Ice, snow or demand closes the route for the rest of the year, so the service is seasonal by necessity.","whyCN":"冰雪或需求让这条路线在一年其余时间关闭，因此服务在客观上只能是季节性的。"},{"no":"05","title":"Migrating or breeding at a fixed time","titleCN":"在固定时节迁徙或繁殖","definition":"describing animal movement or reproduction that is triggered by the time of year","definitionCN":"形容由一年中的时节触发的动物移动或繁殖","example":"Seasonal migration brings millions of birds through the delta.","exampleCN":"季节性迁徙让数以百万计的鸟经过这片三角洲。","why":"Day length and food supply change on a schedule, and animals read that schedule as a signal.","whyCN":"昼长与食物供应按时间表变化，动物把这张时间表当作信号来读。"},{"no":"06","title":"The clinical label for winter depression","titleCN":"冬季抑郁的临床名称用法","definition":"naming a form of depression that returns at the same time each year, usually in winter","definitionCN":"指每年同一时段复发、通常在冬季的抑郁类型","example":"Seasonal affective disorder responds to bright morning light.","exampleCN":"季节性情感障碍对清晨强光有反应。","why":"The adjective in the diagnosis points to the calendar as the trigger, not to a lasting personality trait.","whyCN":"诊断中的这个形容词把日历当作触发因素，而不是持久的人格特质。"},{"no":"07","title":"Adjusted for the calendar in statistics","titleCN":"统计中剔除日历影响的用法","definition":"describing figures from which the normal yearly swing has been removed so that real trends can be seen","definitionCN":"形容已剔除常规年度摆动、以便看出真实趋势的数据","example":"Seasonal adjustment showed that sales were actually falling.","exampleCN":"季节调整显示销售额其实在下降。","why":"If every December is high, a December rise says nothing new, so statisticians subtract the seasonal pattern first.","whyCN":"若每个十二月都高，十二月的上升说明不了新情况，因此统计人员先减去季节模式。"},{"no":"08","title":"Arranged according to the calendar","titleCN":"按季节安排的","definition":"describing a schedule, budget or plan that is divided and timed by the seasons","definitionCN":"形容按季节划分并安排时间的日程、预算或计划","example":"The farm keeps a seasonal calendar for sowing, spraying and harvest.","exampleCN":"农场按播种、喷药与收获维护一份季节性日历。","why":"Here the adjective is about organisation rather than nature: the plan itself follows the four divisions of the year.","whyCN":"这里的形容词讲的是组织方式而非自然现象：计划本身依照一年的四个分段。"}],"etymology":{"intro":{"en":"Seasonal is English season plus the Latin adjective suffix -al. Season itself comes through Old French from Latin satio 'a sowing', built on serere 'to sow'; its sense shifted from sowing time to a division of the year.","cn":"seasonal 是英语 season 加拉丁形容词后缀 -al。season 本身经古法语来自拉丁 satio「播种」，由 serere「播种」构成；词义从「播种时节」转为「一年的分段」。"},"items":[{"era":"LATIN SERERE","en":"Serere meant 'to sow, plant'. Its past participle satus supplies many Latin words about sowing and cultivation.","cn":"serere 意为「播种、栽种」。其过去分词 satus 提供了许多与播种、耕作有关的拉丁词。"},{"era":"LATIN SATIO","en":"Satio meant 'a sowing, planting', later also the time of sowing. Old French turned it into seson, the source of English season.","cn":"satio 意为「播种、栽种」，后来也指播种的时节。古法语把它变成 seson，即英语 season 的来源。"},{"era":"OLD FRENCH SESON","en":"Old French seson already carried both 'sowing time' and 'proper time'; English widened it to the four divisions of the year.","cn":"古法语 seson 已同时带有「播种时节」与「合宜时机」两义；英语把它扩展为一年四季。"},{"era":"ENGLISH SEASON","en":"The noun settled into its calendar sense, while a separate culinary sense, 'to season food', came through Old French assaisonner.","cn":"这个名词固定为日历义；而「给食物调味」的烹饪义则经古法语 assaisonner 另成一线。"},{"era":"NINETEENTH-CENTURY ADJECTIVE","en":"Seasonal is recorded in the nineteenth century. Sources differ on the exact year, so the date is approximate.","cn":"seasonal 的书证见于十九世纪。各家记载的确切年份有出入，故为约数。"},{"era":"MODERN EXTENSIONS","en":"Twentieth-century statistics, medicine and tourism each gave the adjective a technical sense, from seasonal adjustment to seasonal affective disorder.","cn":"二十世纪的统计学、医学与旅游业各自赋予这个形容词技术义，从季节调整到季节性情感障碍。"}]},"similar":{"note":{"en":"Group one holds forms built on season that differ by suffix or sense; group two holds words for regular repetition in time.","cn":"第一组是同出 season、仅后缀或词义不同的形式；第二组是表示时间上有规律重复的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seasonable","ipa":"/ˈsiːzənəbl/","tag":"suitable for the season","definition":"Built with -able: 'suitable to the season', as seasonable weather. It judges fitness, while seasonal merely marks the time.","definitionCN":"由 -able 构成，意为「合于时令的」，如合时的天气。它评判合宜与否，seasonal 只标记时间。"},{"word":"seasoned","ipa":"/ˈsiːzənd/","tag":"flavoured or experienced","definition":"The past participle of the verb season, meaning flavoured with salt or spices, or, of a person, made experienced by time.","definitionCN":"动词 season 的过去分词，指加盐或香料调味，或指人经时间磨练而有经验。"},{"word":"seasoning","ipa":"/ˈsiːzənɪŋ/","tag":"flavourings","definition":"The noun from the culinary verb, naming salt, herbs or spices; it has nothing to do with the calendar.","definitionCN":"来自烹饪动词的名词，指盐、香草或香料；与日历无关。"},{"word":"season","ipa":"/ˈsiːzən/","tag":"the base noun","definition":"The base noun can mean a division of the year or a period of activity, as the rainy season or the football season.","definitionCN":"基础名词可指一年的分段，也可指某活动的时期，如雨季或足球赛季。"}]},{"heading":"NEAR MEANING","entries":[{"word":"periodic","ipa":"/ˌpɪəriˈɒdɪk/","tag":"repeats at intervals","definition":"Repeating at regular intervals of any length, from seconds to decades; it does not require a yearly cycle.","definitionCN":"以任意长度的固定间隔重复，从秒到十年皆可；不要求年度周期。"},{"word":"annual","ipa":"/ˈænjuəl/","tag":"once a year","definition":"Happening once every year; a seasonal event may occur in one part of the year without being annual in this strict sense.","definitionCN":"每年发生一次；季节性事件可发生在一年某一时段，却不一定严格地每年一次。"},{"word":"cyclical","ipa":"/ˈsaɪklɪkl/","tag":"returns in cycles","definition":"Moving through a repeating cycle, often economic; the cycle need not match the calendar year.","definitionCN":"沿重复周期运动，常用于经济；周期不必与日历年一致。"},{"word":"intermittent","ipa":"/ˌɪntəˈmɪtənt/","tag":"stops and starts","definition":"Stopping and starting at uneven intervals, with no fixed calendar; seasonal implies a regular yearly rhythm.","definitionCN":"以不均衡的间隔时断时续，没有固定日历；seasonal 则暗示规律的年度节律。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Season first meant sowing time; seasonal still carries that farming calendar inside it.","cn":"season 最初指播种时节；seasonal 至今仍把这张农事日历带在身上。"},{"en":"The family runs season, seasonal, seasonally, seasonality, seasonable, seasoning.","cn":"同族词包括 season、seasonal、seasonally、seasonality、seasonable、seasoning。"},{"en":"Fixed phrases mark the range: seasonal work, seasonal variation, seasonal produce, seasonal adjustment.","cn":"固定搭配标出范围：季节性工作、季节变化、应季农产品、季节调整。"},{"en":"Seasonal answers 'when in the year'; annual answers 'how often'; keep the two questions apart.","cn":"seasonal 回答「一年中的何时」，annual 回答「多久一次」；把两个问题分开。"},{"en":"The suffix -al simply turns the noun season into an adjective, as nation gives national.","cn":"后缀 -al 只是把名词 season 变成形容词，正如 nation 变成 national。"}],"abstract":[{"en":"Picture a shop whose shelves change colour with the months.","cn":"想象一家货架颜色随月份改变的店。"},{"en":"Picture a river that only exists for part of the year and is a road for the rest.","cn":"想象一条一年只有部分时间存在的河，其余时间是路。"},{"en":"Picture a graph with one hill in the same place every year.","cn":"想象一张图，每年同一个位置都有一座山丘。"}]},"examples":[{"en":"Seasonal variation in rainfall decides when the river rises.","cn":"降雨的季节性变化决定河水何时上涨。"},{"en":"A seasonal ferry links the two villages from May to September.","cn":"一条季节性渡船在五月到九月间连接两个村子。"},{"en":"Seasonal adjustment showed that sales were actually falling.","cn":"季节调整显示销售额其实在下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「四季呢」——一年四季都有它自己的安排 → 季节性的","word":"seasonal"},"root":"season 经古法语 seson 来自拉丁 satio「播种」，由 serere「播种」构成；-al 为拉丁形容词后缀。英语 seasonal。","sensesIntro":{"en":"Eight senses follow one gesture: the calendar divides the year and assigns each thing a slot. The gesture runs from weather to jobs, food, transport, animals, illness, statistics and finally to planning.","cn":"八个义项沿同一个动作展开：日历把一年分开，并给每样东西指定一个位置。这个动作从天气到工作、食物、交通、动物、疾病、统计，最后到计划安排。"},"semanticMap":{"core":{"en":"CORE IMAGE: a calendar folded into four panels, each holding one object that belongs to it alone.","cn":"核心意象：折成四段的日历，每段只挂一件属于它的东西。"},"chain":["YEAR DIVIDED","TIME SLOT","APPEARS","PEAKS","DISAPPEARS","RETURNS"],"branches":[{"senses":"S1 · S8","en":"CALENDAR SHAPE: nature varies by the year and people plan by the same divisions.","cn":"日历形状：自然随年份变化，人也按同样的分段做计划。"},{"senses":"S2 · S3","en":"HARVEST WINDOW: work and food both appear in a narrow, dated window.","cn":"收获窗口：工作与食物都在一个狭窄而有日期的窗口里出现。"},{"senses":"S4","en":"OPEN SEASON: a route or service exists only while conditions allow.","cn":"开放季节：路线或服务只在条件允许时存在。"},{"senses":"S5","en":"ANIMAL SIGNAL: migration and breeding read the same calendar.","cn":"动物信号：迁徙与繁殖读的是同一张日历。"},{"senses":"S6 · S7","en":"MEASURED RHYTHM: medicine names the illness and statistics remove the pattern.","cn":"被测量的节律：医学为疾病命名，统计学把这一模式减掉。"}]},"affixes":{"intro":{"en":"Seasonal is a native English noun with a Latin-derived adjective suffix; the noun's farming origin is still visible in its oldest sense.","cn":"seasonal 是英语本族名词加拉丁来源的形容词后缀；这个名词的农事出身在它最古老的义项里仍看得见。"},"latinIntro":{"en":"Latin serere 'to sow' gives satio 'a sowing', which Old French reshaped into seson. The suffix -al comes from Latin -alis, as in national or natural.","cn":"拉丁 serere「播种」生出 satio「播种」，古法语把它改造成 seson。后缀 -al 来自拉丁 -alis，如 national、natural。"},"items":[{"word":"serere","structure":"serere, sevi, satum (Latin verb, third conjugation)","meaning":"to sow, plant","meaningCN":"播种；栽种","example":"Fruges serunt.","exampleCN":"他们播种谷物。"},{"word":"satio","structure":"serere + -tio (action noun)","meaning":"a sowing; sowing time","meaningCN":"播种；播种时节","example":"Satio vere fit.","exampleCN":"播种在春天进行。"},{"word":"season","structure":"Old French seson, from Latin satio","meaning":"a division of the year; a period of activity","meaningCN":"一年的分段；活动时期","example":"The rainy season begins in June.","exampleCN":"雨季在六月开始。"},{"word":"seasonal","structure":"season + -al (adjective)","meaning":"belonging to a season","meaningCN":"属于某一季节的","example":"Seasonal rains refill the wells.","exampleCN":"季节性降雨重新灌满水井。"},{"word":"seasonally","structure":"seasonal + -ly (adverb)","meaning":"in a seasonal way","meaningCN":"以随季节的方式","example":"The lake level varies seasonally.","exampleCN":"湖面随季节变化。"},{"word":"seasonality","structure":"seasonal + -ity (state noun)","meaning":"the quality of varying with seasons","meaningCN":"随季节波动的性质","example":"Seasonality is strong in the tourist trade.","exampleCN":"旅游业的季节性很强。"},{"word":"seasonable","structure":"season + -able (adjective)","meaning":"suitable to the season","meaningCN":"合于时令的","example":"Seasonable weather helped the harvest.","exampleCN":"合时的天气帮了收获。"},{"word":"seasoning","structure":"season (to flavour) + -ing","meaning":"flavourings; the act of flavouring","meaningCN":"调味品；调味","example":"The soup needs more seasoning.","exampleCN":"这汤需要多加调味。"},{"word":"off-season","structure":"off- + season","meaning":"the quiet part of the year","meaningCN":"淡季","example":"Hotels cut prices in the off-season.","exampleCN":"旅馆在淡季降价。"}],"latinEntries":[{"word":"serere","structure":"serere, sevi, satum (verb, third conjugation)","meaning":"to sow, plant","meaningCN":"播种；栽种"},{"word":"satio","structure":"satio, sationis (f., third declension)","meaning":"a sowing; sowing time","meaningCN":"播种；播种时节"},{"word":"sativus","structure":"sativus, sativa, sativum (adjective)","meaning":"sown, cultivated","meaningCN":"播种的；栽培的"}]}},{"word":"seasonality","ipa_uk":"/ˌsiːzəˈnæləti/","ipa_us":"/ˌsiːzəˈnæləti/","definition_zh":"季节性；随季节波动的性质与幅度","definition_en":"the quality or degree to which something varies with the seasons","core_image":"一条折线在十二个月里起落，最高点每年挤在同几个月，像被季节牵着走","scene":"岛上旅馆冬天大多空着，夏天要提前几个月才订得到房。Tourism on the island shows strong seasonality, with empty hotels every winter.","sceneCN":"这里 seasonality 指「随季节起伏的性质与幅度」（第 1 个义项：季节性）；句意为岛上旅游业季节性很强，每到冬天旅馆空空。图中可辨识物件：空荡的泳池、落下的遮阳伞、旅馆前台、结霜的窗。","pos":[{"tag":"n.","zh":"季节性；随季节波动的性质与幅度（不可数；指具体季节型态时可数，复数 seasonalities）"}],"collocations":[{"phrase":"strong seasonality","zh":"强烈的季节性"},{"phrase":"seasonality in demand","zh":"需求的季节性"},{"phrase":"seasonality of tourism","zh":"旅游业的季节性"},{"phrase":"reduce seasonality","zh":"减弱季节性"},{"phrase":"seasonality pattern","zh":"季节型态"},{"phrase":"measure seasonality","zh":"衡量季节性"}],"forms":[{"label":"复数（指不同的季节型态）","form":"seasonalities"},{"label":"形容词（季节性的）","form":"seasonal"},{"label":"副词（按季节地）","form":"seasonally"},{"label":"名词（季节）","form":"season"},{"label":"形容词（合时令的）","form":"seasonable"},{"label":"名词（季节成分，统计）","form":"seasonal component"}],"derivatives":[{"word":"seasonal","pos":"adj.","zh":"seasonal（基础形容词；seasonality 由 seasonal + -ity 状态名词后缀构成）→ 随季节变化的"},{"word":"seasonally","pos":"adv.","zh":"seasonal + -ly（副词后缀）→ 以随季节的方式"},{"word":"season","pos":"n./v.","zh":"satio（拉丁「播种」）经古法语 seson → 季节；另有一条「调味」义线"},{"word":"seasonable","pos":"adj.","zh":"season + -able → 合于时令的"},{"word":"off-season","pos":"n./adj.","zh":"off-（离开）+ season → 淡季（的）"}],"senses":[{"no":"01","title":"The property of varying with the seasons","titleCN":"随季节起伏的性质","definition":"the tendency of a quantity or activity to rise and fall with the time of year","definitionCN":"某一数量或活动随一年中的时节起落的倾向","example":"Tourism on the island shows strong seasonality, with empty hotels every winter.","exampleCN":"岛上旅游业季节性很强，每到冬天旅馆空空。","why":"The suffix -ity turns the adjective seasonal into a named property, just as national becomes nationality.","whyCN":"后缀 -ity 把形容词 seasonal 变成一种被命名的性质，正如 national 变成 nationality。"},{"no":"02","title":"The size of the seasonal swing","titleCN":"季节摆动的幅度","definition":"the measured difference between the busy peak and the quiet trough of the year","definitionCN":"一年中繁忙高峰与冷清低谷之间测得的差值","example":"Seasonality of ten to one makes staffing almost impossible.","exampleCN":"十比一的季节落差让排班几乎无法安排。","why":"Once the property is measured, it becomes a number, and the noun names that number's size.","whyCN":"一旦这种性质被测量，它就变成一个数，而这个名词指这个数的大小。"},{"no":"03","title":"The tourist high and low season","titleCN":"旅游业的旺季与淡季规律","definition":"the pattern in which visitors arrive in a few months and almost vanish in others","definitionCN":"游客在少数几个月涌入、其余月份几乎消失的模式","example":"A second festival was invented to break the seasonality of the coast.","exampleCN":"为了打断海岸的季节性，人们又造了一个节庆。","why":"Holidays follow school terms and weather, so the trade inherits a sharp calendar from its customers.","whyCN":"假期跟随学期与天气，因此这个行业从顾客那里继承了一张陡峭的日历。"},{"no":"04","title":"Seasonal distribution of a disease","titleCN":"疾病在一年中的季节分布","definition":"the tendency of an infection to peak at a particular time of year","definitionCN":"某种感染在一年中特定时段达到高峰的倾向","example":"The seasonality of influenza peaks in cold, dry months.","exampleCN":"流感的季节性在寒冷干燥的月份达到高峰。","why":"Epidemiologists use the word for any repeated calendar pattern in case numbers, whether the cause is climate or behaviour.","whyCN":"流行病学家用这个词指病例数中任何重复的日历模式，无论起因是气候还是行为。"},{"no":"05","title":"The seasonal rhythm of an ecosystem","titleCN":"生态系统的季节节律","definition":"the regular yearly cycle of leafing, flowering, breeding and decay in a community of organisms","definitionCN":"生物群落中长叶、开花、繁殖与分解的年度规律循环","example":"Satellite images reveal the seasonality of green cover across the delta.","exampleCN":"卫星图像显示出三角洲绿色覆盖的季节性。","why":"Ecology measures the pattern as a whole, so the noun suits a community better than a single organism's response.","whyCN":"生态学把这一模式作为整体来测量，因此这个名词更适合群落，而非单个生物的反应。"},{"no":"06","title":"A component in time-series statistics","titleCN":"时间序列统计中的季节成分","definition":"the part of a data series that repeats every year and can be estimated and removed","definitionCN":"数据序列中每年重复、可被估计并剔除的部分","example":"The model separates seasonality from the underlying trend.","exampleCN":"模型把季节性从底层趋势中分离出来。","why":"Statistics treats the calendar swing as one additive or multiplicative component, hence a countable technical sense.","whyCN":"统计学把日历摆动当作一个可加或可乘的成分，因此产生可数的技术义。"},{"no":"07","title":"The harvest calendar of farming","titleCN":"农业收获的季节性","definition":"the concentration of sowing, labour and income into a few weeks of the agricultural year","definitionCN":"把播种、劳力与收入集中在农事年少数几周的情况","example":"Grain seasonality decides the price of farm labour each August.","exampleCN":"谷物的季节性决定每年八月农工的价格。","why":"Farming is the original source of the word, so its calendar is the clearest case of the property.","whyCN":"农业是这个词最古老的来源，因此它的日历是这种性质最清楚的例子。"},{"no":"08","title":"Seasonal demand for energy","titleCN":"能源需求的季节性","definition":"the yearly pattern in which heating or cooling loads rise and fall with temperature","definitionCN":"取暖或制冷负荷随温度起落的年度模式","example":"Gas seasonality forces utilities to buy storage capacity in summer.","exampleCN":"天然气的季节性迫使公用事业在夏季购买储气能力。","why":"Energy demand is driven by the same weather calendar, so the property appears wherever a load is plotted against months.","whyCN":"能源需求受同一张天气日历驱动，因此只要把负荷按月作图，这种性质就会出现。"}],"etymology":{"intro":{"en":"Seasonality is seasonal plus -ity, a Latin state-noun suffix. The base season comes from Latin satio 'a sowing'; the abstract noun itself is a modern formation whose exact first date is uncertain.","cn":"seasonality 是 seasonal 加 -ity（拉丁状态名词后缀）。基础词 season 来自拉丁 satio「播种」；这个抽象名词本身是近代构词，确切首见年代不确定。"},"items":[{"era":"LATIN SERERE / SATIO","en":"Serere 'to sow' gave satio 'a sowing', which passed through Old French as seson and became English season.","cn":"serere「播种」生出 satio「播种」，经古法语 seson 成为英语 season。"},{"era":"ENGLISH SEASON","en":"The noun extended from sowing time to the four divisions of the year, and then to any marked period such as a football season.","cn":"这个名词从播种时节扩展到一年四季，再扩展到任何被标记的时期，如足球赛季。"},{"era":"NINETEENTH-CENTURY SEASONAL","en":"The adjective seasonal is recorded in the nineteenth century, formed with the Latin suffix -alis. Its exact first year varies between sources.","cn":"形容词 seasonal 的书证见于十九世纪，由拉丁后缀 -alis 构成。各家记载的确切年份有出入。"},{"era":"LATIN -ITAS","en":"The suffix -ity descends from Latin -itas, which turns an adjective into a name for a quality, as in nationality or porosity.","cn":"后缀 -ity 来自拉丁 -itas，把形容词变成性质名称，如 nationality、porosity。"},{"era":"TWENTIETH-CENTURY NOUN","en":"Seasonality became common in economics, tourism and epidemiology in the twentieth century; the first written use is not firmly dated.","cn":"seasonality 在二十世纪的经济学、旅游学与流行病学中变得常用；最早书面用例没有确切年代。"},{"era":"TECHNICAL MEASURE","en":"Time-series statistics later defined seasonality as an estimable component, giving the word a quantitative edge.","cn":"时间序列统计学后来把季节性定义为一个可估计的成分，使这个词带上量化色彩。"}]},"similar":{"note":{"en":"Group one holds forms from the same season family that differ by suffix; group two holds nouns for regular variation in time.","cn":"第一组是同出 season 词族、仅后缀不同的形式；第二组是表示时间上有规律变化的名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"seasonal","ipa":"/ˈsiːzənl/","tag":"the adjective","definition":"The adjective describing a thing that varies by season; seasonality is the abstract property, so the two are not interchangeable.","definitionCN":"描述随季节变化之物的形容词；seasonality 是抽象性质，两者不能互换。"},{"word":"seasonable","ipa":"/ˈsiːzənəbl/","tag":"suitable, not cyclical","definition":"From season plus -able: 'fitting the season', as seasonable weather; it judges suitability, not periodicity.","definitionCN":"season 加 -able，意为「合于时令的」，如合时的天气；评判合宜性，而非周期性。"},{"word":"seasoned","ipa":"/ˈsiːzənd/","tag":"flavoured or experienced","definition":"The participle of the culinary or experiential verb season; nothing to do with yearly cycles.","definitionCN":"烹饪或经验动词 season 的分词；与年度周期无关。"},{"word":"seasoning","ipa":"/ˈsiːzənɪŋ/","tag":"flavourings","definition":"The noun for salt, herbs and spices, from the separate 'to flavour' line of season.","definitionCN":"指盐、香草与香料的名词，来自 season 另一条「调味」义线。"}]},{"heading":"NEAR MEANING","entries":[{"word":"periodicity","ipa":"/ˌpɪəriəˈdɪsəti/","tag":"regular repetition","definition":"The property of repeating at fixed intervals of any length; seasonality is the yearly special case.","definitionCN":"以任意固定间隔重复的性质；seasonality 是其中以年为单位的特例。"},{"word":"cyclicality","ipa":"/ˌsaɪklɪˈkæləti/","tag":"cycle-based","definition":"The tendency to move in cycles, often economic; the cycle may be longer or shorter than a year.","definitionCN":"沿周期运动的倾向，常用于经济；周期可长于或短于一年。"},{"word":"variability","ipa":"/ˌveəriəˈbɪləti/","tag":"general change","definition":"The general fact of changing, with no calendar attached; seasonality specifies a yearly pattern.","definitionCN":"变化的一般事实，不附带日历；seasonality 特指年度模式。"},{"word":"fluctuation","ipa":"/ˌflʌktʃuˈeɪʃn/","tag":"irregular rise and fall","definition":"An irregular up-and-down movement, often short-term; seasonality is regular and calendar-bound.","definitionCN":"不规则的上下波动，常为短期；seasonality 是规律且绑定日历的。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Seasonal plus -ity equals the name of the property, as national plus -ity gives nationality.","cn":"seasonal 加 -ity 得到性质名称，正如 national 加 -ity 得到 nationality。"},{"en":"The family runs season, seasonal, seasonally, seasonality, seasonable, off-season.","cn":"同族词包括 season、seasonal、seasonally、seasonality、seasonable、off-season。"},{"en":"Fixed phrases mark the uses: strong seasonality, seasonality of tourism, seasonality in demand.","cn":"固定搭配标出用法：强烈的季节性、旅游业的季节性、需求的季节性。"},{"en":"Seasonality is what a time-series analyst removes to see the true trend.","cn":"seasonality 正是时间序列分析者要减掉、以便看清真实趋势的东西。"},{"en":"The stress falls late: sea-son-AL-i-ty, not SEASON-ality.","cn":"重音靠后：sea-son-AL-i-ty，而非把重音放在 season 上。"}],"abstract":[{"en":"Picture a wave that repeats its shape every twelve months.","cn":"想象一道每十二个月重复同一形状的波。"},{"en":"Picture a shop with two doors, one open in summer and one in winter.","cn":"想象一家有两扇门的店，夏天开一扇，冬天开另一扇。"},{"en":"Picture a graph stripped of its hills to show the slow climb beneath.","cn":"想象一张被削去山丘的图，露出底下缓慢的爬升。"}]},"examples":[{"en":"Tourism on the island shows strong seasonality, with empty hotels every winter.","cn":"岛上旅游业季节性很强，每到冬天旅馆空空。"},{"en":"The model separates seasonality from the underlying trend.","cn":"模型把季节性从底层趋势中分离出来。"},{"en":"Gas seasonality forces utilities to buy storage capacity in summer.","cn":"天然气的季节性迫使公用事业在夏季购买储气能力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「四季呢，累题」——四季轮着来，题目年年重复 → 季节性","word":"seasonality"},"root":"season 经古法语 seson 来自拉丁 satio「播种」，由 serere「播种」构成；-al 为形容词后缀，-ity 来自拉丁 -itas 性质名词后缀。英语 seasonality。","sensesIntro":{"en":"Eight senses follow one shape: a line that rises and falls on a yearly clock. The shape is named as a property, then measured, then found in tourism, disease, ecology, statistics, farming and energy.","cn":"八个义项沿同一个形状展开：一条随年度时钟起落的线。这个形状先被命名为性质，再被测量，然后在旅游、疾病、生态、统计、农业与能源中出现。"},"semanticMap":{"core":{"en":"CORE IMAGE: a graph whose hill sits in the same months every year.","cn":"核心意象：一张每年山丘都落在同样几个月的图。"},"chain":["YEAR","RISE","PEAK","FALL","TROUGH","REPEAT"],"branches":[{"senses":"S1 · S2","en":"NAMED AND MEASURED: the property is first a quality, then a size on a scale.","cn":"命名与测量：这种性质先是一种品质，再成为刻度上的大小。"},{"senses":"S3 · S8","en":"DEMAND CALENDAR: tourists and power loads both follow the same yearly hill.","cn":"需求日历：游客与电力负荷都追随同一座年度山丘。"},{"senses":"S4","en":"DISEASE CALENDAR: infections also peak on a yearly schedule.","cn":"疾病日历：感染也按年度时间表达到高峰。"},{"senses":"S5","en":"ECOSYSTEM RHYTHM: green cover and breeding repeat as a whole-community pattern.","cn":"生态节律：绿色覆盖与繁殖作为群落整体模式重复。"},{"senses":"S6 · S7","en":"COMPONENT AND HARVEST: statistics isolates it, farming lives by it.","cn":"成分与收获：统计学把它分离出来，农业则靠它生活。"}]},"affixes":{"intro":{"en":"Seasonality stacks two Latin suffixes on a French-shaped English noun, so each layer can be peeled off and named.","cn":"seasonality 在一个法语外形的英语名词上叠了两层拉丁后缀，因此每一层都能剥开命名。"},"latinIntro":{"en":"Satio 'a sowing' becomes English season; -alis makes seasonal; -itas makes the abstract noun. No Latin word seasonality itself existed.","cn":"satio「播种」成为英语 season；-alis 构成 seasonal；-itas 构成抽象名词。拉丁语中并无 seasonality 这个词本身。"},"items":[{"word":"serere","structure":"serere, sevi, satum (Latin verb)","meaning":"to sow","meaningCN":"播种","example":"Serunt frumentum.","exampleCN":"他们播种小麦。"},{"word":"satio","structure":"serere + -tio (action noun)","meaning":"a sowing; sowing time","meaningCN":"播种；播种时节","example":"Satio matura est.","exampleCN":"播种期已到。"},{"word":"season","structure":"Old French seson, from Latin satio","meaning":"a period of the year","meaningCN":"一年中的某段时期","example":"The dry season lasts four months.","exampleCN":"旱季持续四个月。"},{"word":"seasonal","structure":"season + -al","meaning":"of a season","meaningCN":"季节的","example":"Seasonal winds reverse in spring.","exampleCN":"季节风在春季反向。"},{"word":"seasonally","structure":"seasonal + -ly","meaning":"in a seasonal manner","meaningCN":"以随季节的方式","example":"The road is seasonally closed.","exampleCN":"这条路按季节关闭。"},{"word":"seasonality","structure":"seasonal + -ity (Latin -itas)","meaning":"the quality of being seasonal","meaningCN":"季节性的性质","example":"Seasonality complicates the forecast.","exampleCN":"季节性使预测复杂化。"},{"word":"seasonable","structure":"season + -able","meaning":"suitable to the season","meaningCN":"合于时令的","example":"Seasonable rain saved the crop.","exampleCN":"合时的雨救了庄稼。"},{"word":"off-season","structure":"off- + season","meaning":"the quiet season","meaningCN":"淡季","example":"The resort closes in the off-season.","exampleCN":"度假村在淡季关闭。"},{"word":"-ity","structure":"Latin -itas, -itatis (suffix)","meaning":"forms nouns of quality","meaningCN":"构成性质名词","example":"Nationality and porosity follow the same pattern.","exampleCN":"nationality 与 porosity 遵循同一模式。"}],"latinEntries":[{"word":"satio","structure":"satio, sationis (f., third declension)","meaning":"a sowing; sowing time","meaningCN":"播种；播种时节"},{"word":"serere","structure":"serere, sevi, satum (verb, third conjugation)","meaning":"to sow, plant","meaningCN":"播种；栽种"},{"word":"-itas","structure":"-itas, -itatis (f., third declension suffix)","meaning":"quality, state","meaningCN":"性质；状态"}]}},{"word":"photoperiod","ipa_uk":"/ˈfəʊtəʊpɪəriəd/","ipa_us":"/ˈfoʊtoʊpɪriəd/","definition_zh":"光周期；一昼夜中光照的时长","definition_en":"the length of the light period in a daily cycle, especially as a signal for seasonal biological responses","core_image":"一扇天窗的开合时间被刻在一把尺上，刻度从夏到冬逐日变短","scene":"温室里，种植者傍晚开灯把日照拉长，让菊花开得晚一些。Growers extend the photoperiod with lamps to keep chrysanthemums from flowering.","sceneCN":"这里 photoperiod 指「一昼夜中光照持续的时间」（第 1 个义项：每日光照时长）；句意为种植者用灯延长光周期，让菊花不开花。图中可辨识物件：温室灯带、菊花盆、定时器、遮光帘。","pos":[{"tag":"n.","zh":"光周期；一昼夜中的光照时长（可数，复数 photoperiods）"}],"collocations":[{"phrase":"long photoperiod","zh":"长光周期"},{"phrase":"short photoperiod","zh":"短光周期"},{"phrase":"critical photoperiod","zh":"临界光周期"},{"phrase":"photoperiod response","zh":"光周期反应"},{"phrase":"extend the photoperiod","zh":"延长光周期"},{"phrase":"photoperiod sensitivity","zh":"光周期敏感性"}],"forms":[{"label":"复数","form":"photoperiods"},{"label":"形容词（光周期的）","form":"photoperiodic"},{"label":"名词（光周期现象）","form":"photoperiodism"},{"label":"副词（按光周期地，较少用）","form":"photoperiodically"},{"label":"形容词（光周期的，变体）","form":"photoperiodical"},{"label":"相关名词（周期）","form":"period"}],"derivatives":[{"word":"photoperiodic","pos":"adj.","zh":"photoperiod + -ic（形容词后缀）→ 与光周期有关的"},{"word":"photoperiodism","pos":"n.","zh":"photoperiod + -ism（现象或体系后缀）→ 生物对日照长度作出反应的现象"},{"word":"photoperiodically","pos":"adv.","zh":"photoperiodic + -ally（副词后缀）→ 以光周期方式（较少用）"},{"word":"photoperiodical","pos":"adj.","zh":"photoperiod + -ical（形容词后缀变体）→ 光周期的"},{"word":"period","pos":"n.","zh":"希腊 periodos「回路」→ 一段时间；photoperiod 的后半部分"}],"senses":[{"no":"01","title":"The daily length of daylight","titleCN":"一昼夜中的光照时长","definition":"the number of hours of light in a twenty-four-hour cycle at a given place and date","definitionCN":"在特定地点与日期，二十四小时循环中光照的小时数","example":"Growers extend the photoperiod with lamps to keep chrysanthemums from flowering.","exampleCN":"种植者用灯延长光周期，让菊花不开花。","why":"Photo- is Greek for light and period comes from Greek periodos 'a circuit', so the word literally names the light stretch of the daily circuit.","whyCN":"photo- 是希腊语「光」，period 来自希腊 periodos「回路」，因此这个词字面上就是一昼夜循环中光照那一段。"},{"no":"02","title":"Day length used as a biological cue","titleCN":"被当作生物信号使用的日照长度","definition":"the light span treated by an organism as information about the time of year","definitionCN":"被生物当作一年中时节信息的那个光照跨度","example":"The photoperiod tells the tree when to stop growing.","exampleCN":"光周期告诉这棵树何时停止生长。","why":"Because day length changes predictably with the calendar, it becomes a reliable clock that no cloud can reset.","whyCN":"因为昼长随日历可预测地变化，它成了一只云层无法重置的可靠时钟。"},{"no":"03","title":"The threshold that triggers a response","titleCN":"触发反应的临界日照长度","definition":"the specific day length above or below which flowering, dormancy or migration is switched on","definitionCN":"高于或低于它便启动开花、休眠或迁徙的那个特定昼长","example":"The critical photoperiod for this variety is about fourteen hours.","exampleCN":"这个品种的临界光周期约为十四小时。","why":"A response needs a switch, not a gradual scale, so physiologists single out the crossing point and call it critical.","whyCN":"反应需要一个开关而非渐进刻度，因此生理学家挑出那个交叉点，称之为临界。"},{"no":"04","title":"Artificial day length in a greenhouse","titleCN":"温室或实验中的人为光照时长","definition":"a light schedule supplied by lamps and shutters rather than by the sun","definitionCN":"由灯与遮光帘而非太阳提供的光照时间表","example":"The experiment used a twelve-hour photoperiod in every chamber.","exampleCN":"实验在每个培养箱里都采用十二小时光周期。","why":"Once the cue can be supplied artificially, the word shifts from a natural fact to a controlled variable.","whyCN":"一旦这个信号可以人为提供，这个词就从自然事实变成受控变量。"},{"no":"05","title":"The day-length control of flowering","titleCN":"日照长度对开花的控制","definition":"the use of long or short days to decide when a plant produces flowers","definitionCN":"用长日照或短日照决定植物何时开花","example":"Short-day plants flower only when the photoperiod falls below a set length.","exampleCN":"短日照植物只在光周期低于某一长度时才开花。","why":"Flowering is expensive, so plants time it by the most reliable seasonal signal they have, which is day length.","whyCN":"开花代价高昂，因此植物用最可靠的季节信号来安排，而那个信号就是昼长。"},{"no":"06","title":"The day-length control of insect diapause","titleCN":"日照长度对昆虫滞育的控制","definition":"the light span that tells an insect whether to continue developing or to enter winter arrest","definitionCN":"告诉昆虫继续发育还是进入冬季停滞的那个光照跨度","example":"A shortening photoperiod sends the aphid into winter diapause.","exampleCN":"渐短的光周期让蚜虫进入冬季滞育。","why":"An insect cannot see the thermometer far ahead, but it can count the hours of light and prepare for winter.","whyCN":"昆虫看不见远处的温度计，却能数光照的小时数，为冬天做准备。"},{"no":"07","title":"The day-length control of breeding and moult","titleCN":"日照长度对繁殖与换羽的控制","definition":"the light span that switches on courtship, egg laying, moult or migration in animals","definitionCN":"在动物身上启动求偶、产卵、换羽或迁徙的那个光照跨度","example":"A longer photoperiod brings the finches into breeding condition.","exampleCN":"较长的光周期使这些雀进入繁殖状态。","why":"Reproduction must coincide with food, and day length is the most dependable predictor of the season ahead.","whyCN":"繁殖必须与食物同步，而昼长是前方季节最可靠的预兆。"},{"no":"08","title":"A recorded light measurement","titleCN":"被记录的光照时长数据","definition":"the measured light span logged by an instrument or station for comparison across sites and years","definitionCN":"仪器或站点记录下来的光照跨度，用于跨地点、跨年份比较","example":"The station's photoperiod records go back forty years.","exampleCN":"这个站点的光周期记录可追溯到四十年前。","why":"When the light span is logged, the word names a data value as well as a natural event.","whyCN":"当光照跨度被记录下来，这个词既指自然事件，也指一个数据值。"}],"etymology":{"intro":{"en":"Photoperiod is a modern scientific compound of Greek elements: phōs, phōtos 'light' and periodos 'a going around, circuit', from peri- 'around' plus hodos 'way'. It was coined in the early twentieth century and has no classical Latin original.","cn":"photoperiod 是用希腊成分构成的近代科学术语：phōs、phōtos「光」，以及 periodos「绕行、回路」（peri-「环绕」+ hodos「道路」）。它造于二十世纪初，古典拉丁中并无原词。"},"items":[{"era":"GREEK PHOS","en":"Phōs, genitive phōtos, meant 'light'. It is the source of the combining form photo-, seen in photograph and photosynthesis.","cn":"phōs（属格 phōtos）意为「光」，是构词成分 photo- 的来源，见于 photograph 与 photosynthesis。"},{"era":"GREEK PERIODOS","en":"Periodos meant 'a going around, a circuit', from peri- 'around' and hodos 'way, journey'; it gave Latin periodus and English period.","cn":"periodos 意为「绕行、回路」，由 peri-「环绕」与 hodos「道路、行程」构成；它生出拉丁 periodus 与英语 period。"},{"era":"EARLY TWENTIETH-CENTURY COINAGE","en":"Botanists studying flowering time coined photoperiod and photoperiodism around the 1920s. Sources differ on the exact first year, so the date is approximate.","cn":"研究开花时间的植物学家在二十世纪二十年代前后造出 photoperiod 与 photoperiodism。各家记载的确切年份有出入，故为约数。"},{"era":"PHYSIOLOGICAL SPREAD","en":"The term moved from flowering to insect diapause, bird migration and mammalian reproduction as physiologists found the same cue in group after group.","cn":"随着生理学家在一个又一个类群中发现同一信号，这个术语从开花扩展到昆虫滞育、鸟类迁徙与哺乳动物繁殖。"},{"era":"LABORATORY TERM","en":"Controlled chambers made photoperiod an experimental variable, and the word acquired the sense of a set light schedule.","cn":"受控培养箱使光周期成为实验变量，这个词也因此获得「设定好的光照时间表」这一义。"},{"era":"DATA TERM","en":"Twentieth-century field stations began logging day length as a routine measurement, adding the recorded-value sense.","cn":"二十世纪的野外观测站开始把昼长作为常规测量记录下来，于是又添了「记录值」这一义。"}]},"similar":{"note":{"en":"Group one holds words built on the same light or period elements that are easy to mix up; group two holds terms for the light and dark parts of a daily cycle.","cn":"第一组是同出「光」或「周期」成分、容易混淆的词；第二组是表示一昼夜明暗两段的术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"photoperiodism","ipa":"/ˌfəʊtəʊˈpɪəriədɪzəm/","tag":"the phenomenon","definition":"The phenomenon or system of responding to day length, formed with -ism; photoperiod is the cue itself.","definitionCN":"由 -ism 构成，指对昼长作出反应的现象或体系；photoperiod 指那个信号本身。"},{"word":"photoperiodic","ipa":"/ˌfəʊtəʊpɪəˈrɒdɪk/","tag":"the adjective","definition":"The adjective meaning 'relating to photoperiod', as a photoperiodic response; it cannot stand for the noun.","definitionCN":"意为「与光周期有关的」形容词，如光周期反应；不能代替名词。"},{"word":"period","ipa":"/ˈpɪəriəd/","tag":"the second element","definition":"From Greek periodos 'circuit': any stretch of time, not necessarily a light span.","definitionCN":"来自希腊 periodos「回路」，指任意一段时间，不必然是光照跨度。"},{"word":"photograph","ipa":"/ˈfəʊtəɡrɑːf/","tag":"same photo-, different second element","definition":"Photo- plus Greek graphein 'to write': light writing, with no connection to periodic time.","definitionCN":"photo- 加希腊 graphein「写」：光写成的图像，与周期性时间无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"daylength","ipa":"/ˈdeɪleŋθ/","tag":"plain synonym","definition":"The everyday compound for the same measurement; photoperiod is its technical name in biology.","definitionCN":"指同一测量的日常复合词；photoperiod 是它在生物学中的技术名称。"},{"word":"photophase","ipa":"/ˈfəʊtəfeɪz/","tag":"the lit part","definition":"The light portion of a daily cycle, as opposed to the dark portion; photoperiod is its length.","definitionCN":"一昼夜循环中的光照部分，与黑暗部分相对；photoperiod 指这一部分的长度。"},{"word":"scotoperiod","ipa":"/ˈskɒtəʊpɪəriəd/","tag":"the dark part","definition":"The dark portion of a daily cycle, from Greek skotos 'darkness'; it is the mirror term of photoperiod.","definitionCN":"一昼夜循环中的黑暗部分，来自希腊 skotos「黑暗」；是 photoperiod 的镜像术语。"},{"word":"circadian","ipa":"/sɜːˈkeɪdiən/","tag":"internal rhythm","definition":"Relating to an internal rhythm of about a day; photoperiod is the external light signal that sets it.","definitionCN":"指约一日的内部节律；photoperiod 是校准它的外部光照信号。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Photo- is 'light' and period is 'circuit': the light stretch of the daily circuit.","cn":"photo- 是「光」，period 是「回路」：一昼夜回路中的光照那一段。"},{"en":"The family runs photoperiod, photoperiodic, photoperiodism, photoperiodically, photoperiodical.","cn":"同族词包括 photoperiod、photoperiodic、photoperiodism、photoperiodically、photoperiodical。"},{"en":"Fixed phrases mark the science: long photoperiod, short photoperiod, critical photoperiod.","cn":"固定搭配标出科学用法：长光周期、短光周期、临界光周期。"},{"en":"Day length is a calendar no cloud can reset, which is why plants and insects trust it.","cn":"昼长是一张云层无法重置的日历，因此植物与昆虫信任它。"},{"en":"Photoperiod is the cue; photoperiodism is the response; keep cue and response apart.","cn":"photoperiod 是信号，photoperiodism 是反应；把信号与反应分开。"}],"abstract":[{"en":"Picture a ruler laid over the sky, measuring how long the lamp stays on.","cn":"想象一把尺子横在天上，量灯亮着的时间。"},{"en":"Picture a curtain that closes a little earlier each evening as autumn arrives.","cn":"想象一块帘子，秋天来时每晚早一点拉上。"},{"en":"Picture a plant counting hours instead of watching the thermometer.","cn":"想象一株植物数小时，而不去看温度计。"}]},"examples":[{"en":"Growers extend the photoperiod with lamps to keep chrysanthemums from flowering.","cn":"种植者用灯延长光周期，让菊花不开花。"},{"en":"The critical photoperiod for this variety is about fourteen hours.","cn":"这个品种的临界光周期约为十四小时。"},{"en":"A shortening photoperiod sends the aphid into winter diapause.","cn":"渐短的光周期让蚜虫进入冬季滞育。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「光头陪儿熬的」——天一亮就数着光照多久 → 光周期","word":"photoperiod"},"root":"photo- 来自希腊 phōs、phōtos「光」；period 来自希腊 periodos「回路」，由 peri-「环绕」与 hodos「道路」构成。英语 photoperiod 为二十世纪初新造术语，无古典拉丁原词，故 latinEntries 留空。","sensesIntro":{"en":"Eight senses follow one measure: how many hours of light a day contains. The measure is first a fact, then a signal, then a threshold, a laboratory setting, and at last a logged value.","cn":"八个义项沿同一个度量展开：一天里有多少小时的光。这个度量先是事实，再是信号、阈值、实验室设定，最后成为被记录的数据。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruler laid over the sky, marking the lit stretch of the daily circuit.","cn":"核心意象：一把横在天上的尺，标出一昼夜回路中光照的那一段。"},"chain":["LIGHT","CIRCUIT","HOURS","SIGNAL","THRESHOLD","RESPONSE"],"branches":[{"senses":"S1 · S2","en":"MEASURE AND MESSAGE: the same number of hours is both a fact and a cue.","cn":"度量与讯息：同一个小时数既是事实，也是信号。"},{"senses":"S3","en":"SWITCH POINT: a crossing value turns a gradual change into a yes-or-no response.","cn":"开关点：一个交叉值把渐变变成是或否的反应。"},{"senses":"S4","en":"CONTROLLED LIGHT: lamps and shutters turn the cue into a dial.","cn":"受控光照：灯与遮光帘把这个信号变成可旋转的旋钮。"},{"senses":"S5 · S6 · S7","en":"LIFE-STAGE TIMING: flowering, diapause and breeding are all scheduled by the same clock.","cn":"生命阶段计时：开花、滞育与繁殖都由同一只钟安排。"},{"senses":"S8","en":"LOGGED NUMBER: once recorded, the light span becomes data.","cn":"被记录的数字：一旦记下，光照跨度就成为数据。"}]},"affixes":{"intro":{"en":"Photoperiod is a compound of two Greek elements, each of which also lives independently in English science.","cn":"photoperiod 由两个希腊成分复合而成，每个成分在英语科学词汇中也独立存在。"},"latinIntro":{"en":"Both halves are Greek: phōs 'light' and periodos 'circuit'. Latin borrowed periodus from Greek, but the compound photoperiod itself is modern and has no classical Latin source, so latinEntries is left empty.","cn":"两半都是希腊语：phōs「光」与 periodos「回路」。拉丁语从希腊借入 periodus，但 photoperiod 这一复合词本身是近代造词，古典拉丁无对应来源，因此 latinEntries 留空。"},"items":[{"word":"phōs","structure":"phōs, phōtos (Greek noun, third declension)","meaning":"light","meaningCN":"光","example":"Phōs en skotei lamphei.","exampleCN":"光在黑暗中照耀。"},{"word":"periodos","structure":"peri- 'around' + hodos 'way' (Greek compound)","meaning":"a going around, circuit","meaningCN":"绕行；回路","example":"Ho periodos tou hēliou.","exampleCN":"太阳的运行回路。"},{"word":"photo-","structure":"Greek combining form from phōs","meaning":"light","meaningCN":"光","example":"Photosynthesis needs light.","exampleCN":"光合作用需要光。"},{"word":"period","structure":"Greek periodos, through Latin periodus","meaning":"a stretch of time","meaningCN":"一段时间","example":"The dry period lasted weeks.","exampleCN":"干旱期持续了数周。"},{"word":"photoperiod","structure":"photo- + period","meaning":"the light span of a day","meaningCN":"一昼夜的光照跨度","example":"The photoperiod shortens in autumn.","exampleCN":"光周期在秋季变短。"},{"word":"photoperiodic","structure":"photoperiod + -ic (adjective)","meaning":"relating to day length","meaningCN":"与昼长有关的","example":"A photoperiodic signal starts the moult.","exampleCN":"光周期信号启动换羽。"},{"word":"photoperiodism","structure":"photoperiod + -ism (phenomenon)","meaning":"response to day length","meaningCN":"对昼长的反应现象","example":"Photoperiodism explains why some plants flower only when nights are long.","exampleCN":"光周期现象解释了为何有些植物只在夜间较长时开花。"},{"word":"photoperiodically","structure":"photoperiodic + -ally (adverb)","meaning":"by means of day length","meaningCN":"以光周期方式","example":"The buds open photoperiodically.","exampleCN":"芽按光周期开放。"},{"word":"photoperiodical","structure":"photoperiod + -ical (adjective variant)","meaning":"of day length","meaningCN":"光周期的","example":"The paper uses the photoperiodical terminology.","exampleCN":"这篇论文使用光周期术语。"}],"latinEntries":[]}},{"word":"circadian","ipa_uk":"/sɜːˈkeɪdiən/","ipa_us":"/sɝːˈkeɪdiən/","definition_zh":"昼夜节律的；约一日周期的","definition_en":"relating to biological rhythms that repeat about once every twenty-four hours","core_image":"一只看不见的钟嵌在细胞里，指针不由太阳直接推动，却每天与日出对一次表","scene":"夜班护士换了几轮班，身体仍按旧时间表在凌晨犯困。Night-shift nurses often fight a circadian rhythm that never settles.","sceneCN":"这里 circadian 指「约一日重复的生物节律」（第 1 个义项：昼夜节律的）；句意为夜班护士常与一套始终无法安定的昼夜节律较劲。图中可辨识物件：护士站台灯、遮光窗帘、墙上的钟、打哈欠的侧脸。","pos":[{"tag":"adj.","zh":"昼夜节律的；约一日周期的（通常作定语，如 circadian rhythm）"}],"collocations":[{"phrase":"circadian rhythm","zh":"昼夜节律"},{"phrase":"circadian clock","zh":"昼夜节律钟"},{"phrase":"circadian disruption","zh":"昼夜节律紊乱"},{"phrase":"circadian phase","zh":"昼夜节律时相"},{"phrase":"circadian gene","zh":"昼夜节律基因"},{"phrase":"circadian misalignment","zh":"昼夜节律错位"}],"forms":[{"label":"副词（按昼夜节律地，较少用）","form":"circadianly"},{"label":"相关名词（昼夜节律）","form":"circadian rhythm"},{"label":"相关名词（昼夜节律钟）","form":"circadian clock"},{"label":"同前缀形容词（约年周期的）","form":"circannual"},{"label":"同前缀形容词（约潮汐周期的）","form":"circatidal"},{"label":"相关名词（昼夜节律紊乱）","form":"circadian disruption"}],"derivatives":[{"word":"circannual","pos":"adj.","zh":"circa（拉丁「大约」）+ annus（拉丁「年」）→ 约以一年为周期的"},{"word":"circatidal","pos":"adj.","zh":"circa + tidal（潮汐的）→ 约以潮汐周期为节律的"},{"word":"circalunar","pos":"adj.","zh":"circa + lunar（月亮的）→ 约以月相周期为节律的"},{"word":"circaseptan","pos":"adj.","zh":"circa + septan（七的，拉丁 septem）→ 约以七日为周期的"},{"word":"circasemidian","pos":"adj.","zh":"circa + semidian（半日的）→ 约以十二小时为周期的"}],"senses":[{"no":"01","title":"Repeating about once a day","titleCN":"约一日重复一次的","definition":"describing a biological rhythm whose cycle length is close to twenty-four hours","definitionCN":"形容周期长度接近二十四小时的生物节律","example":"Night-shift nurses often fight a circadian rhythm that never settles.","exampleCN":"夜班护士常与一套始终无法安定的昼夜节律较劲。","why":"Circa is Latin for 'around' and dies for 'day', so circadian literally means 'about a day'.","whyCN":"circa 是拉丁语「大约」，dies 是「日」，因此 circadian 字面就是「约一日」。"},{"no":"02","title":"Belonging to the internal pacemaker","titleCN":"属于体内起搏系统的","definition":"describing the internal clock tissue or circuit that generates the daily rhythm without outside help","definitionCN":"形容在没有外界帮助时自行产生日节律的体内钟组织或回路","example":"The suprachiasmatic nucleus is the main circadian pacemaker in mammals.","exampleCN":"视交叉上核是哺乳动物主要的昼夜节律起搏器。","why":"The rhythm persists in constant darkness, which shows that the clock is inside the body and not merely a response to sunrise.","whyCN":"即使处于持续黑暗，节律仍然存在，这说明钟在体内，而不只是对日出的反应。"},{"no":"03","title":"Relating to clock genes and molecules","titleCN":"与生物钟基因及分子回路有关的","definition":"describing the genes and proteins that form the feedback loop of the daily clock","definitionCN":"形容构成日钟反馈回路的基因与蛋白质","example":"Circadian gene expression rises and falls in almost every tissue.","exampleCN":"昼夜节律基因的表达在几乎所有组织中都起落。","why":"Once the clock was traced to molecules, the adjective attached itself to genes and proteins rather than to behaviour.","whyCN":"一旦钟被追溯到分子，这个形容词就附着于基因与蛋白质，而非行为。"},{"no":"04","title":"Of a phase within the daily cycle","titleCN":"处于日循环某一时相的","definition":"describing a particular point in the cycle, such as the circadian phase of peak alertness","definitionCN":"形容循环中的某一特定时点，如警觉高峰的昼夜节律时相","example":"Light in the evening shifts the circadian phase later.","exampleCN":"傍晚的光把昼夜节律时相往后推。","why":"A cycle needs a reference point, so the adjective marks where on the dial an event happens.","whyCN":"循环需要一个参照点，因此这个形容词标记事件发生在表盘上的哪个位置。"},{"no":"05","title":"Describing a disrupted rhythm","titleCN":"形容节律被打乱的状态","definition":"describing the mismatch between an internal rhythm and the required schedule, as in shift work or jet lag","definitionCN":"形容内部节律与所需日程之间的错配，如轮班或跨时区飞行","example":"Circadian disruption raises the risk of metabolic disease.","exampleCN":"昼夜节律紊乱会提高代谢疾病的风险。","why":"Medicine uses the adjective for the harmful gap between body time and social time.","whyCN":"医学用这个形容词指「身体时间」与「社会时间」之间有害的落差。"},{"no":"06","title":"Running free under constant conditions","titleCN":"在恒定条件下自由运行的","definition":"describing a rhythm that continues in constant darkness or constant light without daily resetting","definitionCN":"形容在持续黑暗或持续光照中、不经每日重置仍继续的节律","example":"In constant darkness the circadian period drifts to about twenty-five hours.","exampleCN":"在持续黑暗中，昼夜节律周期会漂移到约二十五小时。","why":"A free-running rhythm reveals the clock's own period, before the environment corrects it each day.","whyCN":"自由运行节律显露钟自身的周期，也就是在被环境每天校正之前的样子。"},{"no":"07","title":"Rhythmic in hormone release or expression","titleCN":"激素分泌或基因表达呈昼夜节律的","definition":"describing a substance or process that rises and falls on a daily schedule, as cortisol does","definitionCN":"形容某种物质或过程按日节律起落，如皮质醇","example":"The circadian release of cortisol peaks just before waking.","exampleCN":"皮质醇的昼夜节律释放会在醒来前达到高峰。","why":"The clock controls output, so the adjective can describe the rhythm of a hormone rather than the clock itself.","whyCN":"钟控制输出，因此这个形容词可以描述激素的节律，而不只是钟本身。"},{"no":"08","title":"Mismatched after crossing time zones","titleCN":"跨时区后节律错位的","definition":"describing the temporary misalignment between body time and local time after rapid travel","definitionCN":"形容快速旅行后身体时间与当地时间暂时错位","example":"Circadian misalignment after a long flight leaves travellers groggy for days.","exampleCN":"长途飞行后的昼夜节律错位让旅客迷糊好几天。","why":"The clock resets slowly, while the aircraft moves quickly, and the gap between them is what we feel as jet lag.","whyCN":"钟重置得慢，飞机却移动得快，两者之间的落差就是我们感到的时差反应。"}],"etymology":{"intro":{"en":"Circadian was coined in 1959 by the chronobiologist Franz Halberg from Latin circa 'around, about' and dies 'day'. Both parts are Latin, but the compound itself is a modern scientific creation.","cn":"circadian 由时间生物学家弗朗茨·哈尔伯格于一九五九年用拉丁 circa「大约、围绕」与 dies「日」造出。两部分都是拉丁语，但复合词本身是近代科学新造。"},"items":[{"era":"LATIN CIRCA","en":"Circa meant 'around, about', both as a preposition and as an approximation marker. It is related to circum 'around' and circus 'ring'.","cn":"circa 意为「围绕、大约」，既作介词，也用来表示约数。它与 circum「环绕」、circus「圆圈」同源。"},{"era":"LATIN DIES","en":"Dies meant 'day'. It survives in English in expressions such as per diem and in the Romance names for day.","cn":"dies 意为「日、天」，在英语 per diem 等表达与罗曼语族表示「日」的词中留存。"},{"era":"MODERN COINAGE","en":"Halberg proposed circadian in 1959 to name rhythms that cycle about once a day. The exact first publication date is well attested for this coinage.","cn":"哈尔伯格在一九五九年提出 circadian，用来命名约一日循环一次的节律。这一新造词的最早发表年代有明确记载。"},{"era":"PHYSIOLOGICAL SPREAD","en":"The adjective spread from human rhythms to plants, insects and fungi as the same clock machinery was found across life.","cn":"随着同样的钟机制在各类生命中被发现，这个形容词从人体节律扩展到植物、昆虫与真菌。"},{"era":"MOLECULAR ERA","en":"Late twentieth-century genetics attached the word to clock genes and protein feedback loops.","cn":"二十世纪后期的遗传学把这个词附着于钟基因与蛋白质反馈回路。"},{"era":"CLINICAL USE","en":"Sleep medicine and shift-work research made circadian disruption a standard clinical and occupational term.","cn":"睡眠医学与轮班研究使 circadian disruption 成为标准的临床与职业术语。"}]},"similar":{"note":{"en":"Group one holds words built on the same Latin circa element that are easy to confuse; group two holds words for regular time patterns.","cn":"第一组是同出拉丁 circa 成分、容易混淆的词；第二组是表示规律时间模式的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"circa","ipa":"/ˈsɜːkə/","tag":"the Latin source","definition":"A Latin preposition meaning 'around, approximately', still used in English before dates; it is not an adjective for rhythms.","definitionCN":"拉丁介词，意为「大约、围绕」，英语中仍用于年代前；不是描述节律的形容词。"},{"word":"circannual","ipa":"/sɜːˈkænjuəl/","tag":"same circa, year cycle","definition":"Circa plus annus 'year': a rhythm of about a year, such as seasonal breeding.","definitionCN":"circa 加 annus「年」：约以一年为周期的节律，如季节性繁殖。"},{"word":"circatidal","ipa":"/sɜːˈtaɪdl/","tag":"same circa, tide cycle","definition":"Circa plus tidal: a rhythm of about twelve and a half hours, set by the tide rather than the sun.","definitionCN":"circa 加 tidal：约十二个半小时的节律，由潮汐而非太阳设定。"},{"word":"circuit","ipa":"/ˈsɜːkɪt/","tag":"same circum family","definition":"From Latin circuitus 'a going around', built on circumire; it names a path or an electrical loop, not a daily rhythm.","definitionCN":"来自拉丁 circuitus「绕行」，由 circumire 构成；指路径或电路回路，而非日节律。"}]},{"heading":"NEAR MEANING","entries":[{"word":"diurnal","ipa":"/daɪˈɜːnl/","tag":"active by day","definition":"Active or happening in daylight hours; a diurnal animal may still have a circadian clock that runs at night.","definitionCN":"在白天活动或发生；昼行动物仍可能有一套夜间运行的昼夜节律钟。"},{"word":"daily","ipa":"/ˈdeɪli/","tag":"everyday word","definition":"The plain word for 'every day'; it carries no claim about an internal clock.","definitionCN":"「每天」的日常用词，不声称存在内部时钟。"},{"word":"rhythmic","ipa":"/ˈrɪðmɪk/","tag":"any repeated pattern","definition":"Repeating in a regular pattern of any period, from seconds to seasons; circadian specifies about a day.","definitionCN":"以任意周期规律重复，从秒到季节；circadian 特指约一日。"},{"word":"periodic","ipa":"/ˌpɪəriˈɒdɪk/","tag":"regular intervals","definition":"Occurring at regular intervals of any length; it does not imply a biological clock.","definitionCN":"以任意长度的固定间隔发生；不暗示生物钟。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Circa 'about' plus dies 'day' gives 'about a day', which is exactly what the rhythm is.","cn":"circa「大约」加 dies「日」得出「约一日」，正是这种节律的样子。"},{"en":"The family runs circadian, circannual, circatidal, circalunar, circaseptan, circasemidian.","cn":"同族词包括 circadian、circannual、circatidal、circalunar、circaseptan、circasemidian。"},{"en":"Fixed phrases mark the field: circadian rhythm, circadian clock, circadian disruption, circadian phase.","cn":"固定搭配标出领域：昼夜节律、昼夜节律钟、节律紊乱、节律时相。"},{"en":"A circadian rhythm survives in constant darkness, which proves the clock is internal.","cn":"昼夜节律在持续黑暗中仍存在，这证明钟在体内。"},{"en":"The word was coined as recently as 1959, so it has no ancient Latin original.","cn":"这个词迟至一九五九年才被造出，因此没有古代拉丁原词。"}],"abstract":[{"en":"Picture a pocket watch sealed in a dark box that still keeps time.","cn":"想象一只封在暗盒里的怀表仍在走时。"},{"en":"Picture a plant lifting its leaves before sunrise, as if it had looked at a clock.","cn":"想象一株植物在日出前抬起叶子，仿佛看过钟。"},{"en":"Picture two clocks in one room set twenty minutes apart.","cn":"想象同一房间里两只钟差了二十分钟。"}]},"examples":[{"en":"Night-shift nurses often fight a circadian rhythm that never settles.","cn":"夜班护士常与一套始终无法安定的昼夜节律较劲。"},{"en":"Light in the evening shifts the circadian phase later.","cn":"傍晚的光把昼夜节律时相往后推。"},{"en":"In constant darkness the circadian period drifts to about twenty-five hours.","cn":"在持续黑暗中，昼夜节律周期会漂移到约二十五小时。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「circa 大约 + di 日」——大约一日一轮回 → 昼夜节律的","word":"circadian"},"root":"拉丁 circa「大约、围绕」+ 拉丁 dies「日」，字面即「约一日」；该词由哈尔伯格于一九五九年新造，无古代拉丁原词。英语 circadian。","sensesIntro":{"en":"Eight senses follow one loop: a body keeps its own roughly daily time. The loop is first the rhythm, then the pacemaker, its genes, its phase, its failures and its misalignment with the world.","cn":"八个义项沿同一个回路展开：身体自带一套约一日的计时。这个回路先是节律，再是起搏器、其基因、其时相、其失灵，以及它与外部世界的错位。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unseen clock inside a cell, checked daily against sunrise.","cn":"核心意象：细胞里一只看不见的钟，每天与日出对表。"},"chain":["ABOUT A DAY","INNER CLOCK","GENE LOOP","PHASE","OUTPUT","RESET"],"branches":[{"senses":"S1 · S2","en":"THE RHYTHM AND ITS SOURCE: the daily cycle and the tissue that generates it.","cn":"节律与来源：日循环本身，以及产生它的组织。"},{"senses":"S3","en":"MOLECULAR CLOCK: genes and proteins form the loop that keeps the beat.","cn":"分子钟：基因与蛋白质构成维持节拍的回路。"},{"senses":"S4 · S7","en":"POSITION AND OUTPUT: the adjective marks where on the dial an event sits and which hormone follows it.","cn":"位置与输出：这个形容词标记事件在表盘上的位置，以及随之分泌的激素。"},{"senses":"S5 · S8","en":"BROKEN ALIGNMENT: disruption and jet lag are the same gap between body time and required time.","cn":"错位：节律紊乱与时差反应，都是身体时间与要求时间之间的同一道落差。"},{"senses":"S6","en":"FREE RUNNING: constant conditions reveal the clock's own period.","cn":"自由运行：恒定条件显露钟自身的周期。"}]},"affixes":{"intro":{"en":"Circadian is a modern Latin compound; its first element also builds a small family of rhythm words, while the second element is simply the Latin word for day.","cn":"circadian 是近代拉丁复合词；前一成分还构成一小族节律词，后一成分就是拉丁语「日」。"},"latinIntro":{"en":"Latin circa 'around' and dies 'day' make the adjective; circa also combines with annus, lunar and septem to name other biological cycles.","cn":"拉丁 circa「大约」与 dies「日」构成这个形容词；circa 还与 annus、lunar、septem 组合，命名其他生物周期。"},"items":[{"word":"circa","structure":"circa (Latin preposition/adverb)","meaning":"around, approximately","meaningCN":"围绕；大约","example":"Circa meridiem advenit.","exampleCN":"他在正午前后到达。"},{"word":"dies","structure":"dies, diei (Latin noun, fifth declension)","meaning":"day","meaningCN":"日；天","example":"Dies longa erat.","exampleCN":"白天很长。"},{"word":"circadian","structure":"circa + dies + -an (adjective)","meaning":"about a day","meaningCN":"约一日的","example":"The circadian cycle is about twenty-four hours.","exampleCN":"昼夜节律周期约为二十四小时。"},{"word":"circadianly","structure":"circadian + -ly (adverb, rare)","meaning":"in a circadian manner","meaningCN":"以昼夜节律方式（较少用）","example":"The tissue responds circadianly to light.","exampleCN":"该组织以昼夜节律方式对光作出反应。"},{"word":"circannual","structure":"circa + annus 'year'","meaning":"about a year in period","meaningCN":"约以一年为周期的","example":"Circannual clocks time the breeding season.","exampleCN":"约年周期的钟安排繁殖季。"},{"word":"circatidal","structure":"circa + tidal","meaning":"about a tide cycle","meaningCN":"约以潮汐为周期的","example":"Crabs show a circatidal activity pattern.","exampleCN":"螃蟹表现出约潮汐周期的活动模式。"},{"word":"circalunar","structure":"circa + lunar","meaning":"about a month in period","meaningCN":"约以月相为周期的","example":"Corals spawn on a circalunar rhythm.","exampleCN":"珊瑚按约月相节律产卵。"},{"word":"circaseptan","structure":"circa + septan 'seven'","meaning":"about a week in period","meaningCN":"约以七日为周期的","example":"A circaseptan rhythm appears in some patients.","exampleCN":"某些病人身上出现约七日的节律。"},{"word":"circasemidian","structure":"circa + semidian 'half-day'","meaning":"about twelve hours in period","meaningCN":"约以十二小时为周期的","example":"A circasemidian rest break splits the day.","exampleCN":"一次约半日的休息把一天分成两段。"}],"latinEntries":[{"word":"circa","structure":"circa (preposition/adverb)","meaning":"around, approximately","meaningCN":"围绕；大约"},{"word":"dies","structure":"dies, diei (m./f., fifth declension)","meaning":"day","meaningCN":"日；天"},{"word":"annus","structure":"annus, anni (m., second declension)","meaning":"year","meaningCN":"年"}]}},{"word":"biological clock","ipa_uk":"/baɪəˈlɒdʒɪkl ˈklɒk/","ipa_us":"/baɪəˈlɑːdʒɪkl ˈklɑːk/","definition_zh":"生物钟；生物体内在计时系统；（通俗）生育时钟","definition_en":"the internal timing system that coordinates daily and seasonal biological rhythms","core_image":"一枚嵌在身体深处的旧怀表，没人上弦，它自己走，还每天按窗外的光对一次时","scene":"换班工人的作息一周一变，身体却仍按旧时间表醒来。A shift worker's biological clock rarely adjusts to a changing roster.","sceneCN":"这里 biological clock 指「体内自行计时的节律系统」（第 1 个义项：生物体内在计时机制）；句意为换班工人的生物钟很难适应不断变动的排班。图中可辨识物件：轮班表、遮光帘、床头闹钟、窗外天色。","pos":[{"tag":"n.","zh":"生物钟；生物体内在计时系统（可数，复数 biological clocks）"},{"tag":"n.","zh":"（通俗）生育时钟；生育年龄的时限感"}],"collocations":[{"phrase":"reset the biological clock","zh":"重置生物钟"},{"phrase":"the biological clock is ticking","zh":"生育时钟在走（年龄压力）"},{"phrase":"biological clock gene","zh":"生物钟基因"},{"phrase":"internal biological clock","zh":"内在生物钟"},{"phrase":"biological clock disruption","zh":"生物钟紊乱"},{"phrase":"follow one's biological clock","zh":"遵循自己的生物钟"}],"forms":[{"label":"复数","form":"biological clocks"},{"label":"形容词（生物的）","form":"biological"},{"label":"名词（生物学）","form":"biology"},{"label":"名词（钟）","form":"clock"},{"label":"同义短语（体内钟）","form":"body clock"},{"label":"同义短语（昼夜节律钟）","form":"circadian clock"}],"derivatives":[{"word":"biology","pos":"n.","zh":"bios（希腊「生命」）+ -logia（学问）→ 研究生命的学科"},{"word":"biological","pos":"adj.","zh":"biology + -ical（形容词后缀）→ 生物学的；生物的"},{"word":"clock","pos":"n./v.","zh":"中世纪拉丁 clocca「钟」→ 计时器；动词义为记录时间"},{"word":"clockwork","pos":"n.","zh":"clock + work → 钟表机构；像钟表一样规律运转的东西"},{"word":"biochronometry","pos":"n.","zh":"bio-（生命）+ chronometry（测时）→ 生物计时测量"}],"senses":[{"no":"01","title":"The body's internal timekeeper","titleCN":"身体内部的计时系统","definition":"the set of internal mechanisms by which an organism times daily and seasonal changes","definitionCN":"生物用来计时昼夜与季节变化的一整套内部机制","example":"A shift worker's biological clock rarely adjusts to a changing roster.","exampleCN":"换班工人的生物钟很难适应不断变动的排班。","why":"The phrase joins a living body to a machine that keeps time: biology supplies the body, clock supplies the regular beat.","whyCN":"这个短语把活的躯体与计时的机械连在一起：biology 提供身体，clock 提供规律的节拍。"},{"no":"02","title":"The circadian pacemaker tissue","titleCN":"昼夜节律起搏组织","definition":"the specific group of cells, such as the suprachiasmatic nucleus, that generates the daily rhythm","definitionCN":"产生日节律的特定细胞群，如视交叉上核","example":"The biological clock sits in a tiny cluster of cells above the optic chiasm.","exampleCN":"生物钟位于视交叉上方一小簇细胞里。","why":"Once the general system was located, the phrase could name the tissue itself rather than the whole capacity.","whyCN":"一旦这套总体系统被定位，这个短语就能指组织本身，而非整体能力。"},{"no":"03","title":"The fertility deadline in everyday speech","titleCN":"日常口语中的生育年龄时限","definition":"the informal sense of the age-related limit on a person's ability to have children","definitionCN":"通俗义：与年龄相关的生育能力时限","example":"She felt her biological clock ticking and changed her plans.","exampleCN":"她感觉自己的生育时钟在走，于是改变了计划。","why":"The metaphor treats reproductive capacity as a clock running down, which is why the phrase sounds urgent rather than scientific.","whyCN":"这个比喻把生育能力当作一只走慢的钟，因此这个短语听起来紧迫而非科学。"},{"no":"04","title":"The gene and protein loop behind it","titleCN":"支撑生物钟的基因与蛋白质回路","definition":"the molecular feedback circuit that produces a roughly daily cycle inside cells","definitionCN":"在细胞内产生约日循环的分子反馈回路","example":"Researchers mapped the biological clock gene network in fruit flies.","exampleCN":"研究人员在果蝇中绘制了生物钟基因网络。","why":"A clock needs an oscillator, and the gene loop is the oscillator that keeps the hands moving.","whyCN":"钟需要一个振荡器，而基因回路就是让指针继续走的振荡器。"},{"no":"05","title":"Synchronisation with the environment","titleCN":"与环境授时因子的同步","definition":"the process by which light, temperature or social cues reset the internal clock each day","definitionCN":"光、温度或社会线索每天重置内部钟的过程","example":"Morning light resets the biological clock after a late night.","exampleCN":"清晨的光在熬夜之后重置生物钟。","why":"An internal clock drifts, so it needs a daily hand-setting from the outside world.","whyCN":"内部钟会漂移，因此需要外部世界每天替它对一次表。"},{"no":"06","title":"Clock disruption and health risk","titleCN":"生物钟紊乱与健康风险","definition":"the state in which the internal clock is out of step with sleep, work or daylight, with effects on health","definitionCN":"内部钟与睡眠、工作或日光脱节、并影响健康的状态","example":"Long-term biological clock disruption is linked to metabolic problems.","exampleCN":"长期的生物钟紊乱与代谢问题相关。","why":"When the clock and the schedule disagree, every daily process fires at the wrong hour.","whyCN":"当钟与日程不一致时，每一项日常过程都在错误的时刻启动。"},{"no":"07","title":"The sense of time running out","titleCN":"时限流逝的比喻用法","definition":"a figurative use for the pressure of a deadline, especially an age-related one","definitionCN":"比喻用法，指截止期限带来的压力，尤指与年龄相关的期限","example":"The biological clock of the whole project was ticking loudly.","exampleCN":"整个项目的生物钟在滴答作响。","why":"The metaphor borrows the body only to express urgency: something living cannot wait forever.","whyCN":"这个比喻借身体只为表达紧迫：活的东西不能无限期等待。"},{"no":"08","title":"The seasonal timer for migration or breeding","titleCN":"安排迁徙或繁殖的季节计时器","definition":"the internal calendar that tells an organism when a season is approaching","definitionCN":"告诉生物某一季节正在临近的内部日历","example":"A biological clock tells the bird when to fatten for migration.","exampleCN":"生物钟告诉这只鸟何时为迁徙囤积脂肪。","why":"Daily clocks can also be read across the year, so the phrase covers seasonal timing as well as nightly timing.","whyCN":"日钟也能跨年读取，因此这个短语既涵盖夜间计时，也涵盖季节计时。"}],"etymology":{"intro":{"en":"Biological clock joins biology, coined from Greek bios 'life' and -logia 'study', to clock, which comes through Middle Dutch and Medieval Latin clocca 'bell'. The phrase itself is a modern English combination whose first date is uncertain.","cn":"biological clock 把 biology（由希腊 bios「生命」与 -logia「学问」构成）与 clock（经中古荷兰语与中世纪拉丁 clocca「钟」而来）组合起来。这个短语本身是近代英语组合，确切首见年代不确定。"},"items":[{"era":"GREEK BIOS","en":"Bios meant 'life'. It supplies the bio- element in biology, biography and biodiversity.","cn":"bios 意为「生命」，提供 biology、biography、biodiversity 中的 bio- 成分。"},{"era":"GREEK -LOGIA","en":"-Logia meant 'the study of', from logos 'word, reason'. Modern Latin turned bios and -logia into biologia in the early nineteenth century.","cn":"-logia 意为「……的学问」，来自 logos「言词、理性」。近代拉丁在十九世纪初把 bios 与 -logia 合为 biologia。"},{"era":"MEDIEVAL LATIN CLOCCA","en":"Clocca meant 'bell' in Medieval Latin, probably borrowed from a Celtic word. It passed through Middle Dutch into English as clock, first for a bell struck to mark hours.","cn":"中世纪拉丁 clocca 意为「钟」，可能借自凯尔特语。它经中古荷兰语进入英语作 clock，最初指报时的钟铃。"},{"era":"MECHANICAL CLOCK","en":"When clocks became machines rather than bells, clock came to mean the instrument itself, and later any regular timer.","cn":"当钟从钟铃变成机械装置后，clock 开始指仪器本身，后来指任何规律计时器。"},{"era":"MODERN PHRASE","en":"The phrase biological clock appears in twentieth-century physiology and then in popular writing about fertility. The exact first use is not firmly dated.","cn":"biological clock 这一短语出现于二十世纪生理学，随后进入关于生育的通俗写作。确切最早用例没有可靠年代。"},{"era":"POPULAR METAPHOR","en":"The fertility sense spread in the later twentieth century and gave the phrase its familiar urgency outside science.","cn":"生育义在二十世纪后期传开，使这个短语在科学之外获得人们熟悉的紧迫感。"}]},"similar":{"note":{"en":"Group one holds closely related clock phrases that differ in scope; group two holds other names for the body's timing system.","cn":"第一组是范围不同、关系极近的「钟」短语；第二组是身体计时系统的其他名称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"body clock","ipa":"/ˈbɒdi klɒk/","tag":"informal synonym","definition":"The everyday equivalent of biological clock in its rhythm sense; it never carries the fertility meaning.","definitionCN":"在节律义上与 biological clock 对应的日常说法；从不带生育义。"},{"word":"circadian clock","ipa":"/sɜːˈkeɪdiən klɒk/","tag":"daily clock only","definition":"The technical name for the roughly daily oscillator; it excludes seasonal timers that biological clock can cover.","definitionCN":"约日振荡器的技术名称；不包含 biological clock 可涵盖的季节计时器。"},{"word":"biological rhythm","ipa":"/baɪəˈlɒdʒɪkl ˈrɪðəm/","tag":"the output, not the clock","definition":"The observable cycle itself rather than the mechanism that generates it.","definitionCN":"可观察到的循环本身，而非产生它的机制。"},{"word":"chronobiology","ipa":"/ˌkrɒnəbaɪˈɒlədʒi/","tag":"the study, not the organ","definition":"The scientific field that studies clocks and rhythms; it is a discipline, not a body part.","definitionCN":"研究钟与节律的科学领域；是学科，不是身体部件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"internal clock","ipa":"/ɪnˈtɜːnl klɒk/","tag":"general phrase","definition":"A broad phrase for any inner timing sense, used of animals and even of machines.","definitionCN":"泛指任何内部计时感，可用于动物，甚至机器。"},{"word":"pacemaker","ipa":"/ˈpeɪsmeɪkə/","tag":"the driving tissue","definition":"The structure that sets the rhythm, especially the suprachiasmatic nucleus or the heart's sinoatrial node.","definitionCN":"设定节律的结构，尤指视交叉上核或心脏窦房结。"},{"word":"timekeeper","ipa":"/ˈtaɪmkiːpə/","tag":"agent noun","definition":"A person or mechanism that records time; in biology it names the clock component that sets the pace.","definitionCN":"记录时间的人或装置；在生物学中指设定节拍的钟组件。"},{"word":"biorhythm","ipa":"/ˈbaɪəʊrɪðəm/","tag":"often pseudo-scientific","definition":"A popular term for supposed regular cycles in mood or energy; it lacks the precision of biological clock.","definitionCN":"通俗术语，指情绪或精力上被认为存在的规律周期；不如 biological clock 精确。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Biology is Greek for 'life-study'; clock is a time machine: a time machine built into a living body.","cn":"biology 是希腊语「研究生命」；clock 是计时机器：一台装进活身体里的计时机器。"},{"en":"The family runs biology, biological, clock, clockwork, and the phrase body clock.","cn":"同族词包括 biology、biological、clock、clockwork，以及短语 body clock。"},{"en":"Fixed phrases mark the range: reset the biological clock, biological clock gene, the clock is ticking.","cn":"固定搭配标出范围：重置生物钟、生物钟基因、时钟在走。"},{"en":"Morning light is the daily hand that winds the clock back to local time.","cn":"清晨的光就是每天把钟拨回当地时间的那只手。"},{"en":"The fertility sense is a metaphor, not physiology: the clock that ticks here is a deadline.","cn":"生育义是比喻而非生理学：这里滴答走的钟是一个截止期限。"}],"abstract":[{"en":"Picture a watch buried in the body, still ticking with no one to wind it.","cn":"想象一只埋进身体的表，无人上弦却仍在走。"},{"en":"Picture a sundial indoors, corrected every morning by a window.","cn":"想象一只放在室内的日晷，每天早晨靠一扇窗来校正。"},{"en":"Picture an hourglass in the blood, its sand always falling.","cn":"想象血液里有一只沙漏，沙一直在落。"}]},"examples":[{"en":"A shift worker's biological clock rarely adjusts to a changing roster.","cn":"换班工人的生物钟很难适应不断变动的排班。"},{"en":"Morning light resets the biological clock after a late night.","cn":"清晨的光在熬夜之后重置生物钟。"},{"en":"She felt her biological clock ticking and changed her plans.","cn":"她感觉自己的生育时钟在走，于是改变了计划。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「生物 + 钟」——身体里装着一只不用上弦的钟 → 生物钟","word":"biological clock"},"root":"biological 由希腊 bios「生命」+ -logia「学问」构成；clock 经中古荷兰语来自中世纪拉丁 clocca「钟」。英语短语 biological clock。","sensesIntro":{"en":"Eight senses follow one object: a timepiece inside a living body. The object is first the whole system, then the tissue, its genes, its setting, its failures, and finally the popular deadline it resembles.","cn":"八个义项沿同一个物件展开：活身体里的一只计时器。这个物件先是整套系统，再是组织、基因、对时、失灵，最后是它所比拟的通俗期限。"},"semanticMap":{"core":{"en":"CORE IMAGE: an old pocket watch embedded in the body, running without a key and corrected by daylight.","cn":"核心意象：嵌在身体里的一只旧怀表，不用钥匙上弦，靠日光校正。"},"chain":["LIVING BODY","TIMEPIECE","OSCILLATOR","SETTING","OUTPUT","DEADLINE"],"branches":[{"senses":"S1 · S2","en":"SYSTEM AND SEAT: the whole capacity and the small tissue that generates it.","cn":"系统与座位：整体能力，以及产生它的那一小簇组织。"},{"senses":"S3 · S7","en":"SOCIAL MEANING: the same phrase names a fertility deadline and a sense of urgency.","cn":"社会含义：同一短语既指生育期限，也指紧迫感。"},{"senses":"S4","en":"MOLECULAR GEAR: genes and proteins are the gears of the timepiece.","cn":"分子齿轮：基因与蛋白质是这只表的齿轮。"},{"senses":"S5 · S6","en":"SETTING AND BREAKING: daylight resets it, and a mismatched schedule breaks it.","cn":"对表与损坏：日光重置它，错配的日程弄坏它。"},{"senses":"S8","en":"SEASONAL CALENDAR: the same system can be read across a year, not only a day.","cn":"季节日历：同一套系统不仅能读一天，也能读一年。"}]},"affixes":{"intro":{"en":"The phrase mixes a Greek-derived scientific word with a Germanic everyday noun, which is why it feels both technical and familiar.","cn":"这个短语把希腊来源的科学词与日耳曼语系的日常名词混在一起，因此既技术又亲切。"},"latinIntro":{"en":"Biology is Greek in both parts, with no Latin root. Clock descends from Medieval Latin clocca 'bell', probably of Celtic origin; that is the only Latin element in the phrase.","cn":"biology 两部分都是希腊语，没有拉丁词根。clock 来自中世纪拉丁 clocca「钟」，可能源出凯尔特语；这是短语中唯一的拉丁成分。"},"items":[{"word":"bios","structure":"bios (Greek noun, second declension)","meaning":"life","meaningCN":"生命","example":"Bios brachys est.","exampleCN":"生命短暂。"},{"word":"-logia","structure":"Greek suffix from logos 'word, reason'","meaning":"the study of","meaningCN":"……的学问","example":"Biologia et geologia eandem suffixionem habent.","exampleCN":"生物学与地质学有同一后缀。"},{"word":"biology","structure":"bios + -logia (Modern Latin biologia)","meaning":"the study of life","meaningCN":"研究生命的学问","example":"Biology became a school subject in the nineteenth century.","exampleCN":"生物学在十九世纪成为学校科目。"},{"word":"biological","structure":"biology + -ical (adjective)","meaning":"relating to life or biology","meaningCN":"与生命或生物学有关的","example":"The biological samples were kept cold.","exampleCN":"生物样本被冷藏保存。"},{"word":"clocca","structure":"clocca, cloccae (Medieval Latin noun)","meaning":"bell","meaningCN":"钟；铃","example":"Clocca ad horas pulsabatur.","exampleCN":"钟被敲响以报时。"},{"word":"clock","structure":"Medieval Latin clocca through Middle Dutch","meaning":"a timekeeping instrument","meaningCN":"计时仪器","example":"The clock on the wall runs fast.","exampleCN":"墙上的钟走快了。"},{"word":"clockwork","structure":"clock + work","meaning":"the mechanism of a clock","meaningCN":"钟表机构","example":"The toy moves by clockwork.","exampleCN":"这个玩具靠钟表机构运动。"},{"word":"body clock","structure":"body + clock (informal compound)","meaning":"the internal timing sense","meaningCN":"体内计时感","example":"His body clock was still on another time zone.","exampleCN":"他的体内钟还停在另一个时区。"},{"word":"biochronometry","structure":"bio- + chronometry 'time measurement'","meaning":"the measurement of biological time","meaningCN":"生物时间的测量","example":"Biochronometry uses constant-condition experiments.","exampleCN":"生物计时测量使用恒定条件实验。"}],"latinEntries":[{"word":"clocca","structure":"clocca, cloccae (f., first declension, Medieval Latin)","meaning":"bell","meaningCN":"钟；铃"}]}},{"word":"chronobiology","ipa_uk":"/ˌkrɒnəbaɪˈɒlədʒi/","ipa_us":"/ˌkrɑːnəbaɪˈɑːlədʒi/","definition_zh":"时间生物学（研究生物节律与计时机制的学科）","definition_en":"the branch of biology that studies biological rhythms and how living things keep time","core_image":"实验室墙上并排许多钟，有的指向黎明，有的指向正午，每个笼子按自己的时区走","scene":"实验室里，不同物种的节律被放在同一张图上比较，看它们各自如何对光对时。Researchers in chronobiology compare how different species keep time.","sceneCN":"这里 chronobiology 指「研究生物节律与计时机制的学科」（第 1 个义项：时间生物学）；句意为时间生物学研究者比较不同物种如何计时。图中可辨识物件：并排的记录仪、笼子、光照计时器、贴标签的图表。","pos":[{"tag":"n.","zh":"时间生物学；生物节律学（通常不可数）"}],"collocations":[{"phrase":"the field of chronobiology","zh":"时间生物学领域"},{"phrase":"chronobiology research","zh":"时间生物学研究"},{"phrase":"clinical chronobiology","zh":"临床时间生物学"},{"phrase":"comparative chronobiology","zh":"比较时间生物学"},{"phrase":"chronobiology laboratory","zh":"时间生物学实验室"},{"phrase":"a course in chronobiology","zh":"时间生物学课程"}],"forms":[{"label":"形容词（时间生物学的）","form":"chronobiological"},{"label":"名词（时间生物学家）","form":"chronobiologist"},{"label":"副词（按时间生物学方式，较少用）","form":"chronobiologically"},{"label":"相关名词（时间生物学现象）","form":"chronobiological rhythm"},{"label":"同义学科名（生物节律学）","form":"biological rhythm research"},{"label":"相关名词（时间类型）","form":"chronotype"}],"derivatives":[{"word":"chronobiological","pos":"adj.","zh":"chronobiology 去掉 -y 加 -ical（形容词后缀）→ 时间生物学的"},{"word":"chronobiologist","pos":"n.","zh":"chronobiology + -ist（从事者后缀）→ 研究时间生物学的学者"},{"word":"chronotherapy","pos":"n.","zh":"chrono-（希腊「时间」）+ therapy → 按生物节律安排给药或光照的治疗"},{"word":"chronopharmacology","pos":"n.","zh":"chrono- + pharmacology → 研究药物效应随时相变化的学科"},{"word":"chronotype","pos":"n.","zh":"chrono- + type → 个体在早睡或晚睡上的节律类型"}],"senses":[{"no":"01","title":"The discipline itself","titleCN":"学科名称：时间生物学","definition":"the scientific field that studies biological rhythms, their mechanisms and their timing","definitionCN":"研究生物节律、其机制及其时间安排的科学领域","example":"Researchers in chronobiology compare how different species keep time.","exampleCN":"时间生物学研究者比较不同物种如何计时。","why":"Chronos is Greek for time and biology is the study of life, so the word names the study of time in living systems.","whyCN":"chronos 是希腊语「时间」，biology 是研究生命，因此这个词命名的是「生命系统中的时间研究」。"},{"no":"02","title":"The rhythms taken as a research object","titleCN":"作为研究对象的生物节律总体","definition":"the whole set of periodic biological phenomena studied as one subject matter","definitionCN":"被当作一个研究对象来研究的全部周期性生物现象","example":"Chronobiology treats sleep, body temperature and hormone release as one system.","exampleCN":"时间生物学把睡眠、体温与激素释放当作一个系统来研究。","why":"A field needs an object, and here the object is any biological process that repeats on a clock.","whyCN":"一个领域需要研究对象，而这里的研究对象是任何按钟重复的生物过程。"},{"no":"03","title":"The laboratory method of the field","titleCN":"该学科的实验室方法","definition":"the use of constant conditions, time-lapse recording and phase shifts to expose internal clocks","definitionCN":"用恒定条件、延时记录与时相移动来显露内部钟的方法","example":"Chronobiology relies on keeping subjects in constant darkness for weeks.","exampleCN":"时间生物学依靠让实验对象在持续黑暗中待数周。","why":"The field's method is inseparable from its name: to see a clock, you must remove the sun.","whyCN":"这个领域的方法与名称不可分：要看钟，就得先移走太阳。"},{"no":"04","title":"A course or degree subject","titleCN":"课程或学位专业","definition":"an taught programme in which students learn rhythm measurement and clock physiology","definitionCN":"教授节律测量与钟生理学的教学项目","example":"She took a course in chronobiology during her physiology degree.","exampleCN":"她在生理学学位课程中修了一门时间生物学。","why":"Like any discipline, the name also labels what is taught and examined.","whyCN":"与任何学科一样，这个名称也标记被教授与被考核的内容。"},{"no":"05","title":"The clinical branch","titleCN":"临床时间生物学","definition":"the application of rhythm science to diagnosis, drug timing and light therapy in patients","definitionCN":"把节律科学应用于病人的诊断、给药时间与光照治疗","example":"Clinical chronobiology adjusts chemotherapy to the patient's daily rhythm.","exampleCN":"临床时间生物学按病人的日节律调整化疗时间。","why":"Once rhythms affect treatment, the discipline acquires a hospital-facing branch with its own name.","whyCN":"一旦节律影响治疗，这门学科就派生出面向医院的分支，并有自己的名称。"},{"no":"06","title":"Comparison across species","titleCN":"跨物种的比较研究","definition":"the comparative study of clocks in animals, plants, fungi and microbes","definitionCN":"对动物、植物、真菌与微生物的钟进行比较的研究","example":"Comparative chronobiology traces the same clock genes from flies to mice.","exampleCN":"比较时间生物学追溯从果蝇到小鼠的同一批钟基因。","why":"Because the clock is ancient, comparing species reveals which parts have been conserved.","whyCN":"因为钟很古老，比较物种就能看出哪些部分是保守的。"},{"no":"07","title":"Overlap with sleep and shift-work research","titleCN":"与睡眠及轮班研究的交叉","definition":"the shared ground between rhythm science, sleep medicine and occupational scheduling","definitionCN":"节律科学、睡眠医学与职业排班之间的共同领域","example":"Chronobiology and sleep medicine share clinics in several hospitals.","exampleCN":"在好几家医院，时间生物学与睡眠医学共用门诊。","why":"Sleep is the most visible rhythm, so the two fields grew into each other.","whyCN":"睡眠是最显眼的节律，因此两个领域彼此长进对方。"},{"no":"08","title":"Applications to lighting and dosing schedules","titleCN":"在照明与给药时间表上的应用","definition":"the practical use of rhythm findings to design light exposure, work rosters and dosing times","definitionCN":"用节律研究结果设计光照、排班与给药时间","example":"Chronobiology guided the design of lamps that suppress melatonin in the morning.","exampleCN":"时间生物学指导了清晨抑制褪黑素的灯具设计。","why":"A science of timing naturally produces technologies of timing.","whyCN":"一门关于时间的科学，自然会产出关于时间的技术。"}],"etymology":{"intro":{"en":"Chronobiology joins Greek khronos 'time' to biology, itself from Greek bios 'life' and -logia 'study'. The term is a twentieth-century coinage, formed when rhythm research became a recognised field.","cn":"chronobiology 把希腊 khronos「时间」与 biology（由希腊 bios「生命」与 -logia「学问」构成）组合起来。这个术语是二十世纪新造，形成于节律研究成为公认领域之时。"},"items":[{"era":"GREEK KHRONOS","en":"Khronos meant 'time'. It supplies chrono- in chronology, chronometer and synchronise, and also lies behind the medical word chronic.","cn":"khronos 意为「时间」，提供 chronology、chronometer、synchronise 中的 chrono-，也是医学词 chronic 的来源。"},{"era":"GREEK BIOS","en":"Bios meant 'life'. With -logia 'study', it formed Modern Latin biologia in the early nineteenth century.","cn":"bios 意为「生命」，与 -logia「学问」在十九世纪初构成近代拉丁 biologia。"},{"era":"MID-TWENTIETH-CENTURY COINAGE","en":"Chronobiology appears as a field name in the mid-twentieth century, after circadian rhythms were measured in many organisms. The exact first use is uncertain.","cn":"chronobiology 作为领域名称出现于二十世纪中叶，此前昼夜节律已在许多生物中被测量。确切最早用例不确定。"},{"era":"INSTITUTIONAL GROWTH","en":"Laboratories, journals and societies adopted the name in the 1960s and 1970s, fixing it as the discipline's label.","cn":"实验室、期刊与学会在二十世纪六七十年代采用这个名称，把它固定为学科标签。"},{"era":"CLINICAL BRANCH","en":"Later in the century, clinical chronobiology split off to apply rhythm data to treatment timing.","cn":"到该世纪后期，临床时间生物学分离出来，把节律数据应用于治疗时间安排。"},{"era":"MODERN SCOPE","en":"Today the term covers molecular clocks, seasonal timing, sleep, shift work and the design of lighting.","cn":"今天这个术语涵盖分子钟、季节计时、睡眠、轮班与照明设计。"}]},"similar":{"note":{"en":"Group one holds words built on the same Greek time element that are easily confused; group two holds neighbouring disciplines and applications.","cn":"第一组是同出希腊「时间」成分、容易混淆的词；第二组是相邻的学科与应用。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chronology","ipa":"/krəˈnɒlədʒi/","tag":"ordering of events","definition":"From khronos plus -logia: the arrangement of past events in time order, not the study of living clocks.","definitionCN":"由 khronos 加 -logia 构成：把过去事件按时间排序，而非研究活的钟。"},{"word":"chronometer","ipa":"/krəˈnɒmɪtə/","tag":"time measurer","definition":"Khronos plus metron 'measure': a precise instrument for measuring time, with no biological reference.","definitionCN":"khronos 加 metron「测量」：精确测时的仪器，与生物学无关。"},{"word":"chronic","ipa":"/ˈkrɒnɪk/","tag":"long-lasting, medical","definition":"From Greek khronikos 'of time': lasting a long time, said of illness; it does not mean rhythmic.","definitionCN":"来自希腊 khronikos「时间的」：形容疾病持续很久；不表示有节律。"},{"word":"biology","ipa":"/baɪˈɒlədʒi/","tag":"the parent field","definition":"The general study of life; chronobiology is one branch of it, not a synonym.","definitionCN":"研究生命的总学科；chronobiology 是其中一个分支，不是同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"chronotherapy","ipa":"/ˌkrɒnəʊˈθerəpi/","tag":"treatment by timing","definition":"The clinical application of rhythm science to the timing of drugs or light; it is a practice, not the discipline.","definitionCN":"把节律科学用于药物或光照时间的临床实践；是做法，不是学科。"},{"word":"chronopharmacology","ipa":"/ˌkrɒnəʊfɑːməˈkɒlədʒi/","tag":"drug timing study","definition":"The study of how drug effects vary with biological time; a subfield rather than the whole field.","definitionCN":"研究药效如何随生物时间变化；是子领域而非整个领域。"},{"word":"chronomedicine","ipa":"/ˌkrɒnəʊˈmedɪsɪn/","tag":"clinical umbrella","definition":"An umbrella term for medical practice that takes biological timing into account.","definitionCN":"考虑生物时间的医疗实践的总称。"},{"word":"chronotype","ipa":"/ˈkrɒnətaɪp/","tag":"personal pattern","definition":"An individual's characteristic timing of sleep and activity, such as morning or evening type.","definitionCN":"个体睡眠与活动的特征时间型，如早型或晚型。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Khronos is 'time' and biology is 'life-study': the study of time in living things.","cn":"khronos 是「时间」，biology 是「研究生命」：研究生命中的时间。"},{"en":"The family runs chronobiology, chronobiological, chronobiologist, chronotherapy, chronotype.","cn":"同族词包括 chronobiology、chronobiological、chronobiologist、chronotherapy、chronotype。"},{"en":"Fixed phrases mark the field: clinical chronobiology, comparative chronobiology, chronobiology laboratory.","cn":"固定搭配标出领域：临床时间生物学、比较时间生物学、时间生物学实验室。"},{"en":"The same chrono- appears in chronology and chronometer, so the family is easy to spot.","cn":"同一个 chrono- 出现在 chronology 与 chronometer 中，词族很容易辨认。"},{"en":"To see a clock, remove the sun: constant darkness is the field's signature method.","cn":"要看钟，先移走太阳：持续黑暗是这门学科的标志性方法。"}],"abstract":[{"en":"Picture a row of clocks on a wall, each set to a different animal's day.","cn":"想象墙上一排钟，每只按一种动物的日长设定。"},{"en":"Picture a laboratory with no windows, only timers.","cn":"想象一间没有窗、只有计时器的实验室。"},{"en":"Picture a timetable that lists hormones instead of trains.","cn":"想象一张时间表，列的是激素而不是列车。"}]},"examples":[{"en":"Researchers in chronobiology compare how different species keep time.","cn":"时间生物学研究者比较不同物种如何计时。"},{"en":"Clinical chronobiology adjusts chemotherapy to the patient's daily rhythm.","cn":"临床时间生物学按病人的日节律调整化疗时间。"},{"en":"Chronobiology guided the design of lamps that suppress melatonin in the morning.","cn":"时间生物学指导了清晨抑制褪黑素的灯具设计。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「克罗诺 + 生物学」——把时间挪进生物学 → 时间生物学","word":"chronobiology"},"root":"chrono- 来自希腊 khronos「时间」；biology 来自希腊 bios「生命」+ -logia「学问」。英语 chronobiology 为二十世纪中叶新造学科名，无古典拉丁原词。","sensesIntro":{"en":"Eight senses follow one move: time is made an object of biological study. The move starts as a discipline, then an object, a method, a course, a clinic, a comparison, an overlap and a technology.","cn":"八个义项沿同一个动作展开：把时间变成生物学的研究对象。这个动作先是学科，再是对象、方法、课程、门诊、比较、交叉与技术。"},"semanticMap":{"core":{"en":"CORE IMAGE: many clocks on one wall, each keeping a different organism's day.","cn":"核心意象：一面墙上许多钟，各自守着不同生物的日长。"},"chain":["TIME","LIFE","RHYTHM","MEASURE","COMPARE","APPLY"],"branches":[{"senses":"S1 · S2","en":"FIELD AND OBJECT: a discipline and the class of rhythms it studies.","cn":"领域与对象：一门学科，以及它所研究的那类节律。"},{"senses":"S3 · S4","en":"METHOD AND TEACHING: constant conditions are the signature method, and courses pass it on.","cn":"方法与教学：恒定条件是标志性方法，课程把它传下去。"},{"senses":"S5 · S8","en":"CLINIC AND DESIGN: rhythm data reshape drug timing and lighting.","cn":"临床与设计：节律数据重塑给药时间与照明。"},{"senses":"S6","en":"CROSS-SPECIES VIEW: comparing clocks shows what evolution conserved.","cn":"跨物种视角：比较钟能看出演化保守了什么。"},{"senses":"S7","en":"SHARED GROUND: sleep medicine and shift-work research meet the field halfway.","cn":"共同地带：睡眠医学与轮班研究各走一半，与这门学科相遇。"}]},"affixes":{"intro":{"en":"Chronobiology joins two Greek roots, and each root also builds a large family of English scientific words.","cn":"chronobiology 连接两个希腊词根，每个词根又各自构成一大族英语科学词。"},"latinIntro":{"en":"Both halves are Greek: khronos 'time' and bios 'life' plus -logia. There is no classical Latin source for the compound, so latinEntries is left empty.","cn":"两半都是希腊语：khronos「时间」，以及 bios「生命」加 -logia。这个复合词没有古典拉丁来源，因此 latinEntries 留空。"},"items":[{"word":"khronos","structure":"khronos (Greek noun, second declension)","meaning":"time","meaningCN":"时间","example":"Khronos panta dēloi.","exampleCN":"时间揭示一切。"},{"word":"chrono-","structure":"Greek combining form from khronos","meaning":"time","meaningCN":"时间","example":"Chronology arranges events by time.","exampleCN":"年代学按时间排列事件。"},{"word":"bios","structure":"bios (Greek noun)","meaning":"life","meaningCN":"生命","example":"Bios kai thanatos.","exampleCN":"生与死。"},{"word":"biology","structure":"bios + -logia","meaning":"study of life","meaningCN":"研究生命","example":"Biology is the parent discipline.","exampleCN":"生物学是母学科。"},{"word":"chronobiology","structure":"chrono- + biology","meaning":"study of biological time","meaningCN":"研究生物时间","example":"Chronobiology grew out of rhythm research.","exampleCN":"时间生物学由节律研究发展而来。"},{"word":"chronobiological","structure":"chronobiology + -ical","meaning":"relating to biological timing","meaningCN":"与生物计时有关的","example":"Chronobiological studies need strict light control.","exampleCN":"时间生物学研究需要严格的光照控制。"},{"word":"chronobiologist","structure":"chronobiology + -ist","meaning":"a specialist in the field","meaningCN":"该领域的专家","example":"A chronobiologist designed the light schedule.","exampleCN":"一位时间生物学家设计了光照时间表。"},{"word":"chronotherapy","structure":"chrono- + therapy","meaning":"treatment timed to rhythms","meaningCN":"按节律定时的治疗","example":"Chronotherapy lowers the dose needed.","exampleCN":"时间治疗降低了所需剂量。"},{"word":"chronotype","structure":"chrono- + type","meaning":"a personal timing pattern","meaningCN":"个人的时间型","example":"Her chronotype is strongly evening.","exampleCN":"她的时间型明显偏晚。"}],"latinEntries":[]}},{"word":"geologic","ipa_uk":"/ˌdʒiːəˈlɒdʒɪk/","ipa_us":"/ˌdʒiːəˈlɑːdʒɪk/","definition_zh":"地质的；地质学的；地质年代的","definition_en":"relating to the study of the earth's structure, rocks and history","core_image":"一叠切开的岩层像翻开的书页，每页夹着一枚不同年代的化石","scene":"峡谷两壁一层层岩石从下往上排开，像一段被切开的年表。The canyon exposes a geologic record spanning two billion years.","sceneCN":"这里 geologic 指「属于地质记录或地质年代的」（第 2 个义项：地质年代的）；句意为这座峡谷露出一段跨越二十亿年的地质记录。图中可辨识物件：层状岩壁、化石、测量锤、峡谷底部的河。","pos":[{"tag":"adj.","zh":"地质的；地质学的；地质年代的（常作定语，如 geologic time）"}],"collocations":[{"phrase":"geologic time","zh":"地质年代"},{"phrase":"geologic record","zh":"地质记录"},{"phrase":"geologic structure","zh":"地质构造"},{"phrase":"geologic map","zh":"地质图"},{"phrase":"geologic hazard","zh":"地质灾害"},{"phrase":"geologic formation","zh":"地质建造；地质体"}],"forms":[{"label":"比较级（较少用）","form":"more geologic"},{"label":"最高级（较少用）","form":"most geologic"},{"label":"副词（在地质上）","form":"geologically"},{"label":"变体形容词（同义，更常用）","form":"geological"},{"label":"名词（地质学）","form":"geology"},{"label":"名词（地质学家）","form":"geologist"}],"derivatives":[{"word":"geological","pos":"adj.","zh":"geologic 的 -al 变体 → 地质的（英式与学术写作更常用）"},{"word":"geologically","pos":"adv.","zh":"geological + -ly（副词后缀）→ 从地质角度；在地质上"},{"word":"geology","pos":"n.","zh":"gē（希腊「大地」）+ -logia（学问）→ 研究地球岩石与历史的学科"},{"word":"geologist","pos":"n.","zh":"geology + -ist（从事者后缀）→ 地质学家"},{"word":"geophysics","pos":"n.","zh":"geo-（大地）+ physics → 用物理方法研究地球的学科"}],"senses":[{"no":"01","title":"Belonging to the science of geology","titleCN":"属于地质学这一学科的","definition":"describing evidence, methods or ideas that belong to the scientific study of rocks and the earth","definitionCN":"形容属于研究岩石与地球的科学领域的证据、方法或观点","example":"The team published a geologic study of the fault zone.","exampleCN":"这个团队发表了一份关于断裂带的地质研究。","why":"Geology is Greek gē 'earth' plus -logia 'study', and -ic simply makes the adjective: of or belonging to that study.","whyCN":"geology 是希腊 gē「大地」加 -logia「学问」，-ic 只是把名词变成形容词：属于这门学问的。"},{"no":"02","title":"Of the long spans of earth history","titleCN":"属于地球历史的漫长年代的","definition":"describing time measured in millions or billions of years rather than human units","definitionCN":"形容以百万年或十亿年而非人类单位衡量的时间","example":"The canyon exposes a geologic record spanning two billion years.","exampleCN":"这座峡谷露出一段跨越二十亿年的地质记录。","why":"Once geology established deep time, the adjective came to mark that scale, where a century is an instant.","whyCN":"当地质学确立了「深时」概念，这个形容词就标记那种尺度：一百年只是一瞬。"},{"no":"03","title":"Explaining how rocks or landforms came to be","titleCN":"说明岩石或地貌成因的","definition":"describing the origin of a feature in terms of earth processes rather than living or human action","definitionCN":"从地球过程而非生物或人类行为来解释某一特征的起源","example":"The arch has a purely geologic origin, with no river involved.","exampleCN":"这座拱门的成因纯属地质作用，与河流无关。","why":"Calling an origin geologic is a way of assigning cause to pressure, heat and water acting over long time.","whyCN":"把起源称为地质的，就是把原因归于压力、热与水在长时间里的作用。"},{"no":"04","title":"Of folds, faults and layered rock","titleCN":"属于褶皱、断层与层状岩体的","definition":"describing the arrangement of rock bodies, faults, folds and strata","definitionCN":"形容岩体、断层、褶皱与地层的排列方式","example":"A geologic structure map shows the folds hidden under the soil.","exampleCN":"地质构造图显示出埋在土下的褶皱。","why":"Structure is the skeleton of a rock mass, so the adjective marks how the parts are arranged, not what they are made of.","whyCN":"构造是岩体的骨架，因此这个形容词标记各部分的排列方式，而非材质。"},{"no":"05","title":"Of mapping and field survey","titleCN":"属于地质测绘与野外调查的","definition":"describing maps, cross-sections and surveys that record rock units at the surface","definitionCN":"形容记录地表岩石单元的地图、剖面与调查","example":"The geologic map was redrawn after the landslide.","exampleCN":"滑坡之后，这张地质图被重新绘制。","why":"Field geology works by mapping, so the adjective attaches to the map as much as to the rock.","whyCN":"野外地质学靠制图工作，因此这个形容词既附着于岩石，也附着于地图。"},{"no":"06","title":"Of mineral and energy resources","titleCN":"属于矿产与能源资源的","definition":"describing deposits, reservoirs or conditions that control where useful materials are found","definitionCN":"形容决定有用物质分布在何处的矿床、储层或条件","example":"Geologic surveys locate the shale layers that hold gas.","exampleCN":"地质调查定位储存天然气的页岩层。","why":"Resources are where geology put them, so exploration speaks of geologic potential rather than chance.","whyCN":"资源所在的位置是地质作用安排的，因此勘探说的是地质潜力，而非偶然。"},{"no":"07","title":"Of earthquakes, landslides and volcanic risk","titleCN":"属于地震、滑坡与火山风险的","definition":"describing hazards whose cause and likelihood are assessed from rock and fault evidence","definitionCN":"形容其成因与可能性由岩石和断层证据评估的危险","example":"Geologic hazard maps guide where new houses may be built.","exampleCN":"地质灾害图指导新房屋可以建在哪里。","why":"Hazards become geologic when they are read from the ground's own record rather than from recent weather.","whyCN":"当危险是从大地自身的记录而非近期天气读出时，它就属于地质范畴。"},{"no":"08","title":"Happening at an extremely slow pace","titleCN":"以极慢速度发生的（引申用法）","definition":"describing a process so slow that its results are visible only across ages","definitionCN":"形容过程极慢，其结果要跨越漫长年代才看得见","example":"The river's shift was geologic in its patience, a few metres each century.","exampleCN":"这条河的改道有地质般的耐心，每世纪只挪几米。","why":"The adjective becomes a metaphor for patience, because geology's characteristic speed is almost no speed at all.","whyCN":"这个形容词成了耐心的比喻，因为地质学的典型速度几乎是「没有速度」。"}],"etymology":{"intro":{"en":"Geologic is geology plus -ic. Geology was coined in Modern Latin as geologia from Greek gē 'earth' and -logia 'study'; its exact first date and coiner are debated among historians.","cn":"geologic 是 geology 加 -ic。geology 在近代拉丁中作 geologia，由希腊 gē「大地」与 -logia「学问」构成；其确切首见年份与首创者在史学界有争议。"},"items":[{"era":"GREEK GE","en":"Gē meant 'earth, land'. It supplies geo- in geography, geometry and geophysics. Its deeper origin is usually traced to a reconstructed Indo-European root for earth, written with an asterisk.","cn":"gē 意为「大地、土地」，提供 geography、geometry、geophysics 中的 geo-。其更早来源一般追溯到原始印欧语中表示大地的重构词根，带星号表示重建形式。"},{"era":"GREEK -LOGIA","en":"-Logia meant 'the study of', from logos 'word, reason'. Joined to gē it produced the Modern Latin word geologia.","cn":"-logia 意为「……的学问」，来自 logos「言词、理性」。与 gē 结合产生近代拉丁 geologia。"},{"era":"MODERN LATIN GEOLOGIA","en":"Geologia appears in the seventeenth and eighteenth centuries for the study of the earth. Historians disagree about who first used it, so no single coiner should be asserted.","cn":"geologia 在十七、十八世纪用来指对地球的研究。史家对其首创者有分歧，因此不应断言某一个人首创。"},{"era":"ENGLISH GEOLOGY","en":"English geology settled in the eighteenth century, and the adjective geologic followed in the early nineteenth; sources differ on the exact year.","cn":"英语 geology 在十八世纪固定下来，形容词 geologic 随后在十九世纪早期出现；各家记载的年份有出入。"},{"era":"DEEP TIME","en":"Nineteenth-century geology established that the earth is far older than human history, and the adjective acquired its sense of immense duration.","cn":"十九世纪地质学确立了地球远比人类历史古老，这个形容词因此获得「极长时段」的含义。"},{"era":"APPLIED FIELDS","en":"Resource exploration and hazard mapping in the twentieth century gave the adjective its technical senses in mining, engineering and insurance.","cn":"二十世纪的资源勘探与灾害制图，使这个形容词在采矿、工程与保险中获得技术义。"}]},"similar":{"note":{"en":"Group one holds words built on the Greek earth element that are easily confused; group two holds neighbouring adjectives from other earth-science methods.","cn":"第一组是同出希腊「大地」成分、容易混淆的词；第二组是其他地球科学方法产生的相邻形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geological","ipa":"/ˌdʒiːəˈlɒdʒɪkl/","tag":"same adjective, longer form","definition":"A variant formed with -ical; it means the same thing and is preferred in British and academic writing.","definitionCN":"由 -ical 构成的变体，意思相同，英式与学术写作更常用。"},{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"the noun","definition":"The discipline itself, from gē plus -logia; it cannot replace the adjective in phrases such as geologic time.","definitionCN":"学科本身，由 gē 加 -logia 构成；不能在地质年代这类短语中替代形容词。"},{"word":"geologist","ipa":"/dʒiˈɒlədʒɪst/","tag":"the person","definition":"The practitioner, formed with -ist; a geologist studies rocks, but a geologic fact is not a person.","definitionCN":"从业者，由 -ist 构成；地质学家研究岩石，但地质事实不是人。"},{"word":"geometry","ipa":"/dʒiˈɒmətri/","tag":"same geo-, different second element","definition":"Gē plus metron 'measure': earth measurement, the old art of surveying land; it has no link to rock history.","definitionCN":"gē 加 metron「测量」：大地测量，古代丈量土地之术；与岩石历史无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stratigraphic","ipa":"/ˌstrætɪˈɡræfɪk/","tag":"layers only","definition":"Relating to the order and correlation of rock layers; a narrower term than geologic.","definitionCN":"与岩层顺序及对比有关；比 geologic 范围更窄。"},{"word":"geophysical","ipa":"/ˌdʒiːəʊˈfɪzɪkl/","tag":"physics methods","definition":"Relating to the physics of the earth, such as seismic or magnetic measurements; it names a method, not the whole field.","definitionCN":"与地球物理有关，如地震或磁测；它命名一种方法，而非整个领域。"},{"word":"geomorphological","ipa":"/ˌdʒiːəʊmɔːfəˈlɒdʒɪkl/","tag":"landforms","definition":"Relating to the origin and shape of landforms; it is a subfield of geology rather than a synonym of geologic.","definitionCN":"与地貌的成因和形态有关；是地质学的子领域，而非 geologic 的同义词。"},{"word":"lithological","ipa":"/ˌlɪθəˈlɒdʒɪkl/","tag":"rock type","definition":"Relating to rock types and their description, from Greek lithos 'stone'; it does not cover time or structure.","definitionCN":"与岩石类型及其描述有关，来自希腊 lithos「石」；不涵盖时间或构造。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Gē is 'earth' and -logia is 'study': geology, then geologic as its adjective.","cn":"gē 是「大地」，-logia 是「学问」：geology，再加 -ic 成为 geologic。"},{"en":"The family runs geology, geologic, geological, geologically, geologist, geophysics.","cn":"同族词包括 geology、geologic、geological、geologically、geologist、geophysics。"},{"en":"Fixed phrases mark the field: geologic time, geologic record, geologic structure, geologic hazard.","cn":"固定搭配标出领域：地质年代、地质记录、地质构造、地质灾害。"},{"en":"Geologic time is deep time: a century is an instant on that clock.","cn":"地质年代是深时：在那个钟上，一百年只是一瞬。"},{"en":"The same geo- appears in geography and geometry, so the first element is easy to spot.","cn":"同一个 geo- 出现在 geography 与 geometry 中，因此第一个成分很容易认出。"}],"abstract":[{"en":"Picture a stack of stone pages, each with a fossil pressed between them.","cn":"想象一叠石页，每一页之间压着一枚化石。"},{"en":"Picture a clock whose second hand takes a thousand years to move.","cn":"想象一只秒针一千年才动一格的钟。"},{"en":"Picture a map drawn in rock colours instead of ink.","cn":"想象一张用岩石颜色而非墨水画成的地图。"}]},"examples":[{"en":"The canyon exposes a geologic record spanning two billion years.","cn":"这座峡谷露出一段跨越二十亿年的地质记录。"},{"en":"A geologic structure map shows the folds hidden under the soil.","cn":"地质构造图显示出埋在土下的褶皱。"},{"en":"Geologic hazard maps guide where new houses may be built.","cn":"地质灾害图指导新房屋可以建在哪里。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「地壳逻辑」——研究大地那套慢逻辑 → 地质的","word":"geologic"},"root":"geo- 来自希腊 gē「大地」；-logic 经近代拉丁 geologia（gē + -logia「学问」）与英语 -ic 构成。英语 geologic 为十八至十九世纪形成的学科形容词，无古典拉丁原词。","sensesIntro":{"en":"Eight senses follow one scale: the earth is read as a record written in stone. The scale runs from the discipline, to deep time, origins, structures, maps, resources, hazards, and finally to patience itself.","cn":"八个义项沿同一个尺度展开：地球被当作一部石头写成的记录来读。这个尺度从学科，到深时、成因、构造、地图、资源、灾害，最后到耐心本身。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cut bank of rock layers like open pages, each holding a fossil.","cn":"核心意象：切开的岩层像翻开的书页，每页夹着一枚化石。"},"chain":["EARTH","STUDY","DEEP TIME","LAYERS","RESOURCES","SLOW CHANGE"],"branches":[{"senses":"S1 · S2","en":"DISCIPLINE AND DURATION: the adjective belongs to geology and to its enormous clock.","cn":"学科与时长：这个形容词既属于地质学，也属于它那只巨大的钟。"},{"senses":"S3 · S4","en":"CAUSE AND SKELETON: origins are assigned to earth processes, and structures describe how rock is arranged.","cn":"成因与骨架：起源被归于地球过程，构造描述岩石如何排列。"},{"senses":"S5","en":"THE MAP: field geology turns rock into paper.","cn":"地图：野外地质学把岩石变成纸上的图。"},{"senses":"S6 · S7","en":"VALUE AND DANGER: the same ground holds resources and hazards.","cn":"价值与危险：同一片大地既藏资源，也藏危险。"},{"senses":"S8","en":"GEOLOGIC PATIENCE: slowness becomes a metaphor for how change actually happens.","cn":"地质般的耐心：缓慢成为「变化究竟如何发生」的比喻。"}]},"affixes":{"intro":{"en":"Geologic is a Greek earth root plus two suffixes; the family shows how the same geo- element spreads across the sciences.","cn":"geologic 是希腊「大地」词根加两层后缀；词族展示了同一个 geo- 成分如何散布到各门科学。"},"latinIntro":{"en":"The element gē is Greek, and the compound geologia is Modern Latin scientific coinage, not classical Latin. English earth is a Germanic word with no Latin root, so latinEntries is left empty.","cn":"gē 这一成分是希腊语，复合词 geologia 是近代拉丁科学新造，而非古典拉丁。英语 earth 是日耳曼语词，没有拉丁词根，因此 latinEntries 留空。"},"items":[{"word":"gē","structure":"gē (Greek noun, first declension)","meaning":"earth, land","meaningCN":"大地；土地","example":"Gē kai ouranos.","exampleCN":"大地与天空。"},{"word":"geo-","structure":"Greek combining form from gē","meaning":"earth","meaningCN":"大地","example":"Geography maps the earth's surface.","exampleCN":"地理学绘制地球表面。"},{"word":"-logia","structure":"Greek suffix from logos","meaning":"the study of","meaningCN":"……的学问","example":"Biologia and geologia share the suffix.","exampleCN":"生物学与地质学共用这一后缀。"},{"word":"geology","structure":"gē + -logia","meaning":"the study of the earth","meaningCN":"研究地球的学问","example":"Geology explains the folds in the cliff.","exampleCN":"地质学解释崖壁上的褶皱。"},{"word":"geologic","structure":"geology + -ic","meaning":"relating to geology","meaningCN":"与地质学有关的","example":"The geologic record is read layer by layer.","exampleCN":"地质记录要一层层地读。"},{"word":"geological","structure":"geologic + -al","meaning":"the longer adjective variant","meaningCN":"较长的形容词变体","example":"A geological survey began last spring.","exampleCN":"一项地质调查去年春天开始。"},{"word":"geologically","structure":"geological + -ly","meaning":"from a geological point of view","meaningCN":"从地质角度","example":"The two hills are geologically distinct.","exampleCN":"这两座山在地质上不同。"},{"word":"geologist","structure":"geology + -ist","meaning":"a person who studies rocks","meaningCN":"研究岩石的人","example":"The geologist dated the ash layer.","exampleCN":"地质学家测定了火山灰层的年代。"},{"word":"geophysics","structure":"geo- + physics","meaning":"the physics of the earth","meaningCN":"地球的物理学","example":"Geophysics maps the mantle by sound waves.","exampleCN":"地球物理学用声波绘制地幔。"}],"latinEntries":[]}},{"word":"earth science","ipa_uk":"/ˈɜːθ ˌsaɪəns/","ipa_us":"/ˈɝːθ ˌsaɪəns/","definition_zh":"地球科学（研究地球系统及其岩石、水、大气与生命的学科群）","definition_en":"the sciences that study the earth as a system, including its rocks, water, air and life","core_image":"一颗星球被切成剖面：岩石、水、空气与生物各占一圈，旁边摆着测量仪器","scene":"一门课把学生带到河边，用流速仪和卫星图测量暴雨后的水量变化。A course in earth science sends students to measure stream flow after every storm.","sceneCN":"这里 earth science 指「研究地球各圈层的学科」（第 1 个义项：地球科学总称）；句意为一门地球科学课程让学生每次暴雨后去测量河流流量。图中可辨识物件：流速仪、河岸标尺、卫星图、雨后的浑水。","pos":[{"tag":"n.","zh":"地球科学（学科群总称；指具体学科领域或课程时可数，复数 earth sciences）"}],"collocations":[{"phrase":"earth science course","zh":"地球科学课程"},{"phrase":"earth science data","zh":"地球科学数据"},{"phrase":"earth science education","zh":"地球科学教育"},{"phrase":"earth science department","zh":"地球科学系"},{"phrase":"earth system science","zh":"地球系统科学"},{"phrase":"branches of earth science","zh":"地球科学的分支"}],"forms":[{"label":"复数（指多个学科领域）","form":"earth sciences"},{"label":"定语形式（作前置定语）","form":"earth-science"},{"label":"相关名词（地球科学家）","form":"earth scientist"},{"label":"相关名词（地球）","form":"earth"},{"label":"相关名词（科学）","form":"science"},{"label":"同义学科名（地球科学）","form":"geoscience"}],"derivatives":[{"word":"earth scientist","pos":"n.","zh":"earth science + -ist（从事者后缀）→ 从事地球科学研究的人"},{"word":"geoscience","pos":"n.","zh":"geo-（希腊「大地」）+ science → 地球科学的同义学科名"},{"word":"scientific","pos":"adj.","zh":"science + -ific（拉丁 -ficus 构成形容词）→ 科学的"},{"word":"scientist","pos":"n.","zh":"science + -ist（从事者后缀）→ 科学家"},{"word":"earthly","pos":"adj.","zh":"earth + -ly（形容词后缀）→ 尘世的；地球上的"}],"senses":[{"no":"01","title":"The family of sciences about the earth","titleCN":"研究地球的学科群总称","definition":"the group of disciplines that study the solid earth, its water, air, climate and living cover","definitionCN":"研究固体地球、其水体、大气、气候与生命覆盖层的学科群","example":"A course in earth science sends students to measure stream flow after every storm.","exampleCN":"一门地球科学课程让学生每次暴雨后去测量河流流量。","why":"Earth is the native English word for the planet and science is the Latin-derived word for organised knowledge, so the phrase simply names knowledge about the earth.","whyCN":"earth 是英语本族词「地球」，science 是拉丁来源的「系统知识」，因此这个短语就是「关于地球的知识」。"},{"no":"02","title":"A school or university subject","titleCN":"中小学或大学的课程科目","definition":"a taught subject that combines geology, weather, oceans and space science for students","definitionCN":"为学生把地质、气象、海洋与空间科学结合起来的教学科目","example":"Earth science is required for graduation in this district.","exampleCN":"在这个学区，地球科学是毕业必修课。","why":"Schools group the branches into one timetable slot, so the phrase also names a course rather than a research field.","whyCN":"学校把各分支合并进一个课表位置，因此这个短语也指课程，而不只是研究领域。"},{"no":"03","title":"The set of its branches","titleCN":"其分支学科的集合","definition":"the collection of fields such as geology, meteorology, oceanography and hydrology","definitionCN":"地质学、气象学、海洋学与水文学等领域的集合","example":"The department lists four branches of earth science in its catalogue.","exampleCN":"该系在课程目录中列出地球科学的四个分支。","why":"Because the phrase is plural in meaning, it can stand for the list of disciplines it contains.","whyCN":"因为这个短语在意义上是复数，它可以指它所包含的那一串学科。"},{"no":"04","title":"Its field and laboratory methods","titleCN":"其野外与实验室方法","definition":"the practices of observation, sampling, remote sensing and modelling used to study the earth","definitionCN":"研究地球所用的观测、采样、遥感与建模等做法","example":"Earth science methods now depend heavily on satellite data.","exampleCN":"地球科学方法如今严重依赖卫星数据。","why":"A science is also a set of methods, and the phrase can name those methods as a body of practice.","whyCN":"一门科学也是一套方法，这个短语可以指作为一整套实践的那些方法。"},{"no":"05","title":"Pre-college earth science education","titleCN":"中小学地球科学教育","definition":"the teaching of earth processes to young students as part of general science","definitionCN":"作为普通科学的一部分，向低龄学生教授地球过程","example":"Earth science education now includes local flood history.","exampleCN":"地球科学教育如今纳入本地的洪水史。","why":"The phrase labels a curriculum area as well as a research discipline, and teaching is the clearest example.","whyCN":"这个短语既标记研究学科，也标记课程领域，而教学是最清楚的例子。"},{"no":"06","title":"Data about the earth system","titleCN":"关于地球系统的数据与资料","definition":"measurements and archives of the earth's surface, interior, oceans and atmosphere","definitionCN":"关于地球表面、内部、海洋与大气的测量与档案","example":"Open earth science data let schools run their own climate projects.","exampleCN":"开放的地球科学数据让学校开展自己的气候项目。","why":"Modern fields are identified by their data as much as their questions, so the phrase attaches to datasets.","whyCN":"现代领域既由问题定义，也由数据定义，因此这个短语附着于数据集。"},{"no":"07","title":"An academic department or agency","titleCN":"院系或机构名称","definition":"an institutional unit that groups earth-focused researchers and teaching","definitionCN":"把以地球为对象的研究者与教学集中在一起的机构单位","example":"The earth science department shares a building with the chemistry lab.","exampleCN":"地球科学系与化学实验室共用一栋楼。","why":"Institutions need a collective label, and this phrase is the usual one for a department or survey agency.","whyCN":"机构需要一个集体标签，而这个短语就是院系或调查机构常用的那一个。"},{"no":"08","title":"The integrated view of the earth as a system","titleCN":"把地球当作系统的整合视角","definition":"the approach that treats rock, water, air, ice and life as one interacting system rather than separate subjects","definitionCN":"把岩石、水、空气、冰与生命当作一个相互作用系统、而非分开科目的取向","example":"Earth science treats rock, water, air, ice and life as one interacting system.","exampleCN":"地球科学把岩石、水、空气、冰与生命视为一个相互作用的系统。","why":"The plural branches were later reunified under a systems view, which the phrase can also carry.","whyCN":"原本分开的各分支后来在系统视角下重新统一，这个短语也能承载这一层。"}],"etymology":{"intro":{"en":"Earth science is a modern English compound of two very different words: earth, from Old English eorþe, and science, from Latin scientia 'knowledge'. The phrase has no single coiner and its first date is uncertain.","cn":"earth science 是近代英语复合词，由两个来源很不同的词构成：earth 来自古英语 eorþe，science 来自拉丁 scientia「知识」。这个短语没有单一首创者，确切首见年代不确定。"},"items":[{"era":"OLD ENGLISH EORTHE","en":"Eorþe meant 'earth, ground, soil'. It descends from a reconstructed Proto-Germanic form and has no Latin root; the deeper Indo-European origin is debated.","cn":"eorþe 意为「大地、地面、土壤」，来自重构的原始日耳曼语形式，没有拉丁词根；更深的印欧来源有争议。"},{"era":"LATIN SCIENTIA","en":"Scientia meant 'knowledge', from scire 'to know'. English science entered through Old French in the Middle Ages.","cn":"scientia 意为「知识」，来自 scire「知道」。英语 science 在中世纪经古法语进入。"},{"era":"EARLY MODERN SCIENCE","en":"In the seventeenth century science narrowed from 'knowledge' in general to organised, methodical study of nature.","cn":"十七世纪，science 从泛指的「知识」收窄为对自然的有组织、有方法的研究。"},{"era":"MODERN COMPOUND","en":"Earth science as a collective label for geology, meteorology, oceanography and related fields is a nineteenth- and twentieth-century usage; the exact first record is uncertain.","cn":"earth science 作为地质学、气象学、海洋学及相关领域的集合标签，是十九至二十世纪的用法；确切最早记载不确定。"},{"era":"SCHOOL SUBJECT","en":"In the twentieth century the phrase became a standard school and university subject name, grouping the branches for teaching.","cn":"二十世纪，这个短语成为标准的中学与大学科目名，为教学把各分支归并起来。"},{"era":"SYSTEMS ERA","en":"Late twentieth-century earth system science reunited the branches under one model of interacting spheres.","cn":"二十世纪后期的地球系统科学把各分支重新统一到一个「圈层相互作用」的模型中。"}]},"similar":{"note":{"en":"Group one holds near-identical labels that differ in breadth or structure; group two holds neighbouring fields that study only part of the earth.","cn":"第一组是范围或结构不同、名称极近的标签；第二组是只研究地球某一部分的相邻领域。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"geoscience","ipa":"/ˈdʒiːəʊsaɪəns/","tag":"near synonym","definition":"A learned synonym built on Greek gē; it overlaps heavily with earth science but is commoner in research than in schools.","definitionCN":"以希腊 gē 构成的书面对应词；与 earth science 高度重叠，但在研究界比在学校更常用。"},{"word":"earth scientist","ipa":"/ˈɜːθ ˌsaɪəntɪst/","tag":"the person","definition":"The practitioner, formed with -ist; the field is earth science, the person is an earth scientist.","definitionCN":"从业者，由 -ist 构成；领域是 earth science，人是 earth scientist。"},{"word":"environmental science","ipa":"/ɪnˌvaɪrənˈmentl ˈsaɪəns/","tag":"different centre","definition":"The study of human impact and ecosystems; it borrows earth data but focuses on pollution and policy.","definitionCN":"研究人类影响与生态系统；借用地球数据，但聚焦污染与政策。"},{"word":"earthen","ipa":"/ˈɜːθn/","tag":"same base, adjective","definition":"An adjective meaning 'made of earth or clay', from earth plus -en; it describes material, not a field of study.","definitionCN":"由 earth 加 -en 构成的形容词，意为「土制的」；描述材料，而非研究领域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"geology","ipa":"/dʒiˈɒlədʒi/","tag":"solid earth only","definition":"The study of rocks and earth history; it is one branch of earth science, not the whole.","definitionCN":"研究岩石与地球历史；是地球科学的一个分支，而非全部。"},{"word":"physical geography","ipa":"/ˈfɪzɪkl dʒiˈɒɡrəfi/","tag":"surface and climate","definition":"The study of landforms, climate and water at the surface; it overlaps earth science but keeps a spatial focus.","definitionCN":"研究地表地貌、气候与水；与地球科学重叠，但保持空间视角。"},{"word":"earth system science","ipa":"/ˈɜːθ ˈsɪstəm ˈsaɪəns/","tag":"integrated branch","definition":"The systems-oriented branch that models the interactions of rock, water, air, ice and life.","definitionCN":"以系统为取向的分支，建模岩石、水、空气、冰与生命的相互作用。"},{"word":"planetology","ipa":"/plænɪˈtɒlədʒi/","tag":"other planets too","definition":"The study of planets including the earth; it extends beyond the earth, so it is wider in one direction.","definitionCN":"研究包括地球在内的行星；范围向地球之外延伸，因此在另一个方向上更宽。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Earth is the planet and science is organised knowledge: knowledge about the planet.","cn":"earth 是行星，science 是有系统的知识：关于这颗行星的知识。"},{"en":"The family runs earth, earthly, earth scientist, science, scientific, scientist, geoscience.","cn":"同族词包括 earth、earthly、earth scientist、science、scientific、scientist、geoscience。"},{"en":"Fixed phrases mark the uses: earth science course, earth science data, earth science department.","cn":"固定搭配标出用法：地球科学课程、地球科学数据、地球科学系。"},{"en":"The plural earth sciences names the branches, while earth science names the whole group.","cn":"复数 earth sciences 指各分支，earth science 则指整个学科群。"},{"en":"Earth system science is the integrated view of the same material.","cn":"地球系统科学是对同一批材料的整合视角。"}],"abstract":[{"en":"Picture a planet cut open like an orange, each layer labelled.","cn":"想象一颗像橙子一样被切开的行星，每层都贴了标签。"},{"en":"Picture a classroom whose windows look onto a river gauge.","cn":"想象一间教室，窗外正对着一条河的水位尺。"},{"en":"Picture four maps of the same place stacked into one.","cn":"想象同一地方的四张地图叠成一张。"}]},"examples":[{"en":"A course in earth science sends students to measure stream flow after every storm.","cn":"一门地球科学课程让学生每次暴雨后去测量河流流量。"},{"en":"Earth science methods now depend heavily on satellite data.","cn":"地球科学方法如今严重依赖卫星数据。"},{"en":"Earth system science asks how melting ice changes the solid ground beneath it.","cn":"地球系统科学追问融冰如何改变其下的大地。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「地球 + 科学」——把整颗星球当成一门课来研究 → 地球科学","word":"earth science"},"root":"earth 来自古英语 eorþe（原始日耳曼语来源，无拉丁词根）；science 来自拉丁 scientia「知识」，由 scire「知道」构成。英语短语 earth science 为近代组合，确切首见年代不确定。","sensesIntro":{"en":"Eight senses follow one object: the planet taken as a subject. The object is first the family of fields, then a course, a list of branches, a set of methods, a curriculum, a dataset, a department, and finally a system.","cn":"八个义项沿同一个对象展开：把整颗行星当作一门学问。这个对象先是学科群，再是课程、分支清单、方法、课程领域、数据集、院系，最后是一个系统。"},"semanticMap":{"core":{"en":"CORE IMAGE: a planet sliced into layers, each labelled and measured.","cn":"核心意象：一颗被切成若干层、每层都标注并测量的行星。"},"chain":["PLANET","KNOWLEDGE","BRANCHES","METHODS","TEACHING","SYSTEM"],"branches":[{"senses":"S1 · S3","en":"WHOLE AND PARTS: the collective name and the list of branches it contains.","cn":"整体与部分：集合名称，以及它所包含的分支清单。"},{"senses":"S2 · S5","en":"CLASSROOM: the same label marks a school subject and a curriculum area.","cn":"课堂：同一标签既标记学校科目，也标记课程领域。"},{"senses":"S4 · S6","en":"PRACTICE AND DATA: observation, remote sensing and archives define the field in use.","cn":"实践与数据：观测、遥感与档案在使用中定义这门领域。"},{"senses":"S7","en":"INSTITUTION: a department or agency carries the name.","cn":"机构：院系或机构以此命名。"},{"senses":"S8","en":"SYSTEM VIEW: the separate branches reunite into one interacting whole.","cn":"系统视角：分开的各分支重新合成一个相互作用的整体。"}]},"affixes":{"intro":{"en":"The phrase joins an Old English noun of the planet to a Latin noun of knowledge, which is why one half feels plain and the other learned.","cn":"这个短语把古英语的「行星」名词与拉丁的「知识」名词连在一起，因此一半朴素，一半书卷。"},"latinIntro":{"en":"Only the second half is Latin: scientia from scire. Earth is Germanic and has no Latin cognate, so the Latin entries below cover just the science element.","cn":"只有后半部分是拉丁语：scientia 来自 scire。earth 是日耳曼语词，没有拉丁同源词，因此下列拉丁条目只涵盖 science 这一成分。"},"items":[{"word":"eorþe","structure":"Old English eorþe (noun)","meaning":"earth, ground, soil","meaningCN":"大地；地面；土壤","example":"Seo eorþe wæs wēt.","exampleCN":"土地是湿的。"},{"word":"earth","structure":"Old English eorþe + Modern English spelling","meaning":"the planet; soil","meaningCN":"地球；泥土","example":"The earth turns once a day.","exampleCN":"地球每天自转一次。"},{"word":"earthly","structure":"earth + -ly (adjective)","meaning":"of this world","meaningCN":"尘世的；地球上的","example":"Earthly concerns seemed small from orbit.","exampleCN":"从轨道上看，尘世的牵挂显得很小。"},{"word":"scientia","structure":"scientia, scientiae (Latin noun)","meaning":"knowledge","meaningCN":"知识","example":"Scientia potentia est.","exampleCN":"知识就是力量。"},{"word":"science","structure":"Latin scientia through Old French","meaning":"organised knowledge","meaningCN":"有系统的知识","example":"Science tests its claims against evidence.","exampleCN":"科学用证据检验其主张。"},{"word":"scientific","structure":"science + -ific (Latin -ficus)","meaning":"relating to science","meaningCN":"与科学有关的","example":"The claim lacks scientific support.","exampleCN":"这一主张缺乏科学支持。"},{"word":"scientist","structure":"science + -ist (agent)","meaning":"one who practises science","meaningCN":"从事科学的人","example":"The scientist repeated the measurement.","exampleCN":"这位科学家重复了测量。"},{"word":"earth science","structure":"earth + science (compound)","meaning":"the sciences of the earth","meaningCN":"研究地球的诸学科","example":"Earth science covers rock, water and air.","exampleCN":"地球科学涵盖岩石、水与空气。"},{"word":"geoscience","structure":"geo- + science","meaning":"the learned synonym","meaningCN":"书面对应同义词","example":"Geoscience departments often include hydrology.","exampleCN":"地球科学系常包含水文学。"}],"latinEntries":[{"word":"scientia","structure":"scientia, scientiae (f., first declension)","meaning":"knowledge","meaningCN":"知识"},{"word":"scire","structure":"scire, scivi, scitum (verb, fourth conjugation)","meaning":"to know","meaningCN":"知道；了解"},{"word":"sciens","structure":"sciens, scientis (present participle)","meaning":"knowing","meaningCN":"知道的；有知识的"}]}},{"word":"crust","ipa_uk":"/krʌst/","ipa_us":"/krʌst/","definition_zh":"面包等食物的硬外皮；地壳；硬外壳；结痂","definition_en":"the hard outer layer of something, such as bread, the earth, or a wound","core_image":"一只手掰开刚出炉的面包，外壳裂开发出脆响，里面是柔软的白瓤","scene":"面包出炉后在架子上凉下来，表皮发出细碎的脆响。The bread's crust crackles when the loaf cools on the rack.","sceneCN":"这里 crust 指「面包烤成的硬外皮」（第 1 个义项：食物外皮）；句意为面包在架上放凉时，外皮发出脆响。图中可辨识物件：面包架、切开的面包、掉落的面包屑、冒出的热气。","pos":[{"tag":"n.","zh":"硬外皮；外壳；地壳；结痂（可数，复数 crusts）"},{"tag":"vi.","zh":"结壳；形成硬层"}],"collocations":[{"phrase":"bread crust","zh":"面包外皮"},{"phrase":"earth's crust","zh":"地壳"},{"phrase":"oceanic crust","zh":"洋壳"},{"phrase":"continental crust","zh":"陆壳"},{"phrase":"salt crust","zh":"盐壳"},{"phrase":"earn a crust","zh":"谋生；挣口饭吃"}],"forms":[{"label":"复数","form":"crusts"},{"label":"三单（he/she/it）","form":"crusts"},{"label":"过去式","form":"crusted"},{"label":"过去分词","form":"crusted"},{"label":"现在分词","form":"crusting"},{"label":"形容词（有硬壳的；易怒的）","form":"crusty"}],"derivatives":[{"word":"crusty","pos":"adj.","zh":"crust + -y（形容词后缀）→ 有硬外皮的；引申为脾气粗硬的"},{"word":"crusted","pos":"adj.","zh":"crust + -ed（过去分词形容词）→ 表面结了硬壳的"},{"word":"crustal","pos":"adj.","zh":"crust + -al（形容词后缀）→ 与地壳有关的"},{"word":"crustacean","pos":"n./adj.","zh":"crusta（拉丁「壳」）+ -acean（属于……的）→ 甲壳类动物"},{"word":"encrust","pos":"v.","zh":"en-（使进入）+ crust → 使表面结壳；覆上一层硬物"}],"senses":[{"no":"01","title":"The baked outer layer of bread","titleCN":"面包烤成的硬外皮","definition":"the hard, browned outer surface of a loaf or pie, formed by heat","definitionCN":"经高温形成的面包或馅饼外层，色深而硬","example":"The bread's crust crackles when the loaf cools on the rack.","exampleCN":"面包在架上放凉时，外皮发出脆响。","why":"Latin crusta named a rind or shell, and the first English sense was this edible shell around soft food.","whyCN":"拉丁 crusta 指果皮或外壳，英语最早的义项就是包在软食外面的这层可食外壳。"},{"no":"02","title":"The rocky outer shell of the earth","titleCN":"地球的岩石外壳（地壳）","definition":"the thin, solid outer layer of the planet above the mantle","definitionCN":"行星地幔之上那层薄而坚固的外壳","example":"The drill never reached the boundary of the earth's crust.","exampleCN":"钻头始终没有到达地壳的边界。","why":"Geology reused the food image on a planetary scale: a thin hard shell around a hotter interior.","whyCN":"地质学把食物的意象放大到行星尺度：一层薄硬外壳包着更热的内部。"},{"no":"03","title":"Continental or oceanic crust","titleCN":"陆壳或洋壳（地壳类型）","definition":"one of the two kinds of crust, thick and granitic or thin and basaltic","definitionCN":"两种地壳之一，或厚而花岗质，或薄而玄武质","example":"Oceanic crust is denser than continental crust and sinks beneath it.","exampleCN":"洋壳比陆壳致密，会俯冲到陆壳之下。","why":"Once the shell was studied, geologists needed names for its two compositions, and crust supplied the head noun.","whyCN":"一旦研究这层壳，地质学家就需要为它的两种成分命名，而 crust 提供了中心名词。"},{"no":"04","title":"A hard layer on snow or ice","titleCN":"雪面或冰面的硬壳","definition":"a frozen or wind-packed surface layer that can bear weight while the snow below stays soft","definitionCN":"冻结或被风压实的表层，能承重而其下雪仍松软","example":"A thin crust on the snow let the sled run without sinking.","exampleCN":"雪面一层薄壳让雪橇不陷下去。","why":"Freezing and wind do to snow what baking does to dough: they make a firm skin over something soft.","whyCN":"冻结与风对雪做的事，正如烘烤对面团做的事：在柔软之物上结一层硬皮。"},{"no":"05","title":"A salt or soil surface layer","titleCN":"盐壳或土壤结皮","definition":"a hardened surface formed when salts or fine particles dry and cement together","definitionCN":"盐分或细颗粒干后胶结成的硬化表层","example":"A white salt crust had formed along the drying shore.","exampleCN":"干涸的岸边已经结出一层白色盐壳。","why":"Evaporation leaves dissolved material at the surface, where it hardens into the same kind of skin.","whyCN":"蒸发把溶解物留在表面，那里便硬结成同一类表皮。"},{"no":"06","title":"The scab over a healing wound","titleCN":"伤口愈合时结成的痂","definition":"the dry hardened layer of blood and tissue that covers a healing cut","definitionCN":"覆盖愈合中伤口的干硬血与组织层","example":"A crust formed over the scrape within a day.","exampleCN":"擦伤在一天之内就结了痂。","why":"The body builds a temporary shell to protect the repair underneath, exactly the shape the word describes.","whyCN":"身体造出一层临时外壳来保护下面的修复，正是这个词所描述的形状。"},{"no":"07","title":"Any hard outer covering","titleCN":"泛指坚硬的覆盖层","definition":"a hard casing or coating on an object, as on a rock, a pipe or a mineral","definitionCN":"物体外面坚硬的壳或覆层，如岩石、管道或矿物上的","example":"A crust of lichen and grit covered the old wall.","exampleCN":"一层地衣与砂砾结成的硬壳覆在旧墙上。","why":"The core idea is simply an outer skin that has hardened, whatever material it is made of.","whyCN":"核心意思只是一个硬化了的外层表皮，无论由什么材料构成。"},{"no":"08","title":"A living earned from bread","titleCN":"习语「挣口饭吃」中的生计义","definition":"in the phrase earn a crust, a modest living or the money needed to survive","definitionCN":"在习语 earn a crust 中，指微薄的生计或维持生活所需的钱","example":"He earns a crust driving a delivery van at night.","exampleCN":"他靠夜间开送货车挣口饭吃。","why":"Bread is the plainest food, so its outer layer stands for the minimum a person needs to live on.","whyCN":"面包是最朴素的食物，因此它的外层就代表一个人维持生活所需的最低限度。"}],"etymology":{"intro":{"en":"Crust comes through Old French crouste from Latin crusta 'rind, shell, bark'. The food sense is the oldest; the geological sense was added in the sixteenth century.","cn":"crust 经古法语 crouste 来自拉丁 crusta「果皮、壳、树皮」。食物义最古老，地质义约在十六世纪加入。"},"items":[{"era":"CLASSICAL LATIN (1st c. BCE - 1st c. CE)","en":"Latin crusta is well attested with the meaning 'rind, shell, hard outer covering, bark'. Its deeper origin is uncertain: no reconstructed Indo-European root is securely agreed on, and the word is best treated as an isolated Latin item rather than as a derived formation.","cn":"拉丁 crusta 有充分书证，意为「果皮、壳、硬外层、树皮」。其更深来源不确定：学界没有一致认可的原始印欧语词根，因此宜把它看作拉丁语中的独立词，而非由某个词根派生而来。"},{"era":"LATE LATIN AND ROMANCE (c. 5th - 9th c.)","en":"The Latin noun passed into the spoken Romance languages; the regular sound changes produced forms such as Old Provencal crosta and Old French crouste. The exact first date of each local form is uncertain.","cn":"这个拉丁名词进入罗曼语口语；规律音变产生古普罗旺斯语 crosta、古法语 crouste 等形式。各方言形式的最早记录年代不确定。"},{"era":"OLD FRENCH (c. 12th - 13th c.)","en":"Old French crouste is generally regarded as the regular reflex of Latin crusta, with the same range of meanings: a crust of bread, a rind, a hard surface. The form is attested in texts of the twelfth and thirteenth centuries.","cn":"古法语 crouste 一般被认为是拉丁 crusta 的规律演变形式，义域相同：面包硬皮、果皮、硬表面。该形式见于十二、十三世纪文本。"},{"era":"MIDDLE ENGLISH (c. 13th - 14th c.)","en":"English borrowed the word as crust (also crouste) from Old French. The food sense is the earliest attested; the exact date of the first English record is uncertain and varies between reference works.","cn":"英语从中古法语借入 crust（也写作 crouste）。食物义是最早的书证义；英语首次记录的准确年代不确定，各家辞书给出的时间并不一致。"},{"era":"EARLY MODERN ENGLISH (c. 16th c.)","en":"The geological sense 'the outer solid layer of the earth' appears in the sixteenth century. This dating is approximate: the metaphor of a bread crust applied to the globe is old, but the technical use becomes common only in this period.","cn":"「地球外部固体层」这一地质义在十六世纪出现。此年代为约数：把面包硬皮比作地球外壳的比喻由来已久，但技术用法在此时期才通行。"},{"era":"MODERN ENGLISH (19th - 20th c.)","en":"Derived forms multiply: crustal for the earth's crust, crustacean for shelled animals, encrust for covering with a hard layer, and crustose for flat, crust-like growth. These formations follow Latin and French patterns rather than a single inherited root.","cn":"派生形式大量增加：crustal 指地壳的，crustacean 指有壳的动物，encrust 指覆上硬层，crustose 指平贴如壳的生长。这些构词沿拉丁与法语模式形成，并非来自单一继承词根。"}]},"similar":{"note":{"en":"Group one holds words from the same Latin shell root that are easily confused; group two holds other words for an outer covering.","cn":"第一组是同出拉丁「壳」词根、容易混淆的词；第二组是表示外层覆盖物的其他词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"crustacean","ipa":"/krʌˈsteɪʃn/","tag":"same root, an animal","definition":"From crusta plus -aceus 'having a shell': the shellfish group, named for its hard casing.","definitionCN":"由 crusta 加 -aceus「有壳的」构成：因硬壳而得名的甲壳类动物。"},{"word":"crustal","ipa":"/ˈkrʌstl/","tag":"same root, adjective","definition":"The adjective for 'of the crust', used almost only of the earth's outer shell.","definitionCN":"意为「地壳的」形容词，几乎只用于地球外壳。"},{"word":"crusty","ipa":"/ˈkrʌsti/","tag":"same root, texture","definition":"Having a hard outer layer, and by extension a rough manner; it describes texture or temper.","definitionCN":"有硬外层的，引申指脾气粗硬；描述质地或性情。"},{"word":"encrust","ipa":"/ɪnˈkrʌst/","tag":"same root, verb","definition":"En- 'in' plus crust: to cover a surface with a hard layer, as salt encrusts a pipe.","definitionCN":"en-「进入」加 crust：使表面覆上硬层，如盐在管子上结壳。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rind","ipa":"/rɪnd/","tag":"fruit or cheese","definition":"The tough outer skin of fruit, cheese or bacon; it is usually softer or thinner than a crust.","definitionCN":"水果、奶酪或培根的坚韧外皮；通常比 crust 更软或更薄。"},{"word":"shell","ipa":"/ʃel/","tag":"hard case","definition":"A hard case built by an animal or made as a container, such as an eggshell or a crab shell.","definitionCN":"动物长成或制成容器的硬壳，如蛋壳或蟹壳。"},{"word":"scab","ipa":"/skæb/","tag":"wound only","definition":"The dry covering over a healing wound; it is the medical member of the crust family.","definitionCN":"愈合伤口上的干硬覆盖物；是 crust 词族中属于医学的那一个。"},{"word":"layer","ipa":"/ˈleɪə/","tag":"neutral term","definition":"A general word for any thickness of material lying over another; it carries no claim that the surface is hard.","definitionCN":"泛指覆盖在另一层之上的任何厚度材料；不声称表面坚硬。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin crusta is a rind or shell, and every sense is a hardened outer skin.","cn":"拉丁 crusta 是果皮或壳，每个义项都是一层硬化的外皮。"},{"en":"The family runs crust, crusty, crusted, crustal, crustacean, encrust.","cn":"同族词包括 crust、crusty、crusted、crustal、crustacean、encrust。"},{"en":"Fixed phrases mark the senses: bread crust, earth's crust, salt crust, earn a crust.","cn":"固定搭配标出义项：面包外皮、地壳、盐壳、挣口饭吃。"},{"en":"The same crusta gives crustacean, an animal named for its shell.","cn":"同一个 crusta 生出 crustacean，一种因壳得名的动物。"},{"en":"Bread crust, earth's crust and a scab are three sizes of the same idea.","cn":"面包皮、地壳与痂，是同一想法在三个尺度上的表现。"}],"abstract":[{"en":"Picture a soft thing wearing a hard coat it baked for itself.","cn":"想象一个柔软之物给自己烤了一件硬外套。"},{"en":"Picture a planet with a thin shell like the skin on cooled pudding.","cn":"想象一颗行星，外壳薄得像凉透的布丁表面那层皮。"},{"en":"Picture a wound closing its door with a dry brown lock.","cn":"想象伤口用一把干褐色的锁把门关上。"}]},"examples":[{"en":"The bread's crust crackles when the loaf cools on the rack.","cn":"面包在架上放凉时，外皮发出脆响。"},{"en":"Oceanic crust is denser than continental crust and sinks beneath it.","cn":"洋壳比陆壳致密，会俯冲到陆壳之下。"},{"en":"A thin crust on the snow let the sled run without sinking.","cn":"雪面一层薄壳让雪橇不陷下去。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「咔嚓」——咬面包外皮时那声脆响 → 硬外皮、外壳","word":"crust"},"root":"拉丁 crusta「果皮、壳、树皮」，经古法语 crouste 进入英语；其更深来源不确定，学界没有一致认可的原始印欧语词根，不宜强行归入某一词根。英语 crust。","sensesIntro":{"en":"Eight senses follow one shape: a hard skin over something softer. The shape runs from bread to the planet, to its two rock types, to snow, salt, wounds, any casing, and finally to the bread a living is earned by.","cn":"八个义项沿同一个形状展开：柔软之物外面的一层硬皮。这个形状从面包到行星，到两种岩石类型，到雪、盐、伤口、任何外壳，最后到用来谋生的那块面包。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hand breaking a fresh loaf, the shell cracking and the soft inside showing.","cn":"核心意象：一只手掰开新出炉的面包，外壳裂开，露出柔软的内里。"},"chain":["SOFT INSIDE","HEAT","HARD SKIN","PROTECTION","SCALE UP","LIVELIHOOD"],"branches":[{"senses":"S1 · S8","en":"BREAD: the edible shell and the modest living it stands for.","cn":"面包：可食的外壳，以及它所代表的微薄生计。"},{"senses":"S2 · S3","en":"PLANET: the earth's shell and its two compositions.","cn":"行星：地球的外壳及其两种成分。"},{"senses":"S4 · S5","en":"FROZEN AND DRIED SURFACES: snow packs and salt cements into the same skin.","cn":"冻硬与干硬的表面：雪被压实、盐被胶结，形成同一层皮。"},{"senses":"S6","en":"WOUND: the body builds its own temporary shell.","cn":"伤口：身体自己造出一层临时外壳。"},{"senses":"S7","en":"ANY CASING: rock, pipe or wall wears the same hard coat.","cn":"任何外壳：岩石、管道或墙壁都穿同样的硬外套。"}]},"affixes":{"intro":{"en":"Crust is a Latin noun carried through French, and its root also names shellfish, a geological adjective and a verb of encasing.","cn":"crust 是经法语进入英语的拉丁名词，其词根还构成甲壳类、地质形容词与「包壳」动词。"},"latinIntro":{"en":"Latin crusta 'rind, shell' gives crust, crustal and crustacean; the verb encrust adds the prefix en-. The deeper Indo-European origin is uncertain, with no generally agreed reconstruction.","cn":"拉丁 crusta「果皮、壳」生出 crust、crustal 与 crustacean；动词 encrust 加了前缀 en-。更深的印欧来源没有一致认可的重构形式，存疑。"},"items":[{"word":"crusta","structure":"crusta, crustae (Latin noun, first declension)","meaning":"rind, shell, bark","meaningCN":"果皮；壳；树皮","example":"Crusta panis dura est.","exampleCN":"面包皮很硬。"},{"word":"crust","structure":"Latin crusta through Old French crouste","meaning":"a hard outer layer","meaningCN":"硬外层","example":"The crust protects the soft interior.","exampleCN":"外壳保护柔软的内部。"},{"word":"crusty","structure":"crust + -y (adjective)","meaning":"having a hard crust","meaningCN":"有硬壳的","example":"The bread came out warm and crusty.","exampleCN":"面包出炉时又热又有脆壳。"},{"word":"crusted","structure":"crust + -ed (participial adjective)","meaning":"covered with a hard layer","meaningCN":"结了一层硬壳的","example":"The boots were crusted with mud.","exampleCN":"靴子上结了一层泥壳。"},{"word":"crustal","structure":"crust + -al (adjective)","meaning":"of the earth's crust","meaningCN":"地壳的","example":"Crustal plates move a few centimetres a year.","exampleCN":"地壳板块每年移动几厘米。"},{"word":"crustacean","structure":"crusta + -aceus + -an","meaning":"a shellfish with a hard case","meaningCN":"有硬壳的甲壳类动物","example":"Crabs and lobsters are crustaceans.","exampleCN":"蟹与龙虾是甲壳类动物。"},{"word":"encrust","structure":"en- (in) + crust","meaning":"to cover with a hard layer","meaningCN":"使表面结壳","example":"Salt encrusted the old pipe.","exampleCN":"盐在旧管子上结了壳。"},{"word":"crustose","structure":"crust + -ose (full of)","meaning":"growing flat like a crust, as a lichen","meaningCN":"像壳一样平贴生长的（地衣）","example":"A crustose lichen spreads over the stone.","exampleCN":"一种壳状地衣在石面上铺开。"},{"word":"crustily","structure":"crusty + -ly (adverb, rare)","meaning":"in a crusty manner","meaningCN":"粗硬地；带脆壳地（较少用）","example":"He answered crustily and left the room.","exampleCN":"他粗声粗气地回答，然后离开了房间。"}],"latinEntries":[{"word":"crusta","structure":"crusta, crustae (f., first declension)","meaning":"rind, shell, bark","meaningCN":"果皮；壳；树皮"},{"word":"crustaceus","structure":"crustaceus, crustacea, crustaceum (adjective)","meaning":"having a hard shell","meaningCN":"有硬壳的"},{"word":"incrustare","structure":"incrustare, incrustavi, incrustatum (verb, first conjugation)","meaning":"to cover with a crust","meaningCN":"给……覆上硬壳"}]}}]);
